// Content for Norm Storm (node g18, ages 9-12, Chapter 3): NEW v2 build to GDD 18 (mechanic-embodying),
// the social-norms node (Thread E · Gender & Respect). "Which norms help, which harm." 84 researched,
// India-grounded scenarios across the understand → sort → test → change arc, each encoded as one of the
// shared v2 play actions (sort / strike-rewrite / branch / reflect / role-play / spot / match): no binary
// "tap the right card", led by the **help/harm sorting board** (sort ×20: the signature) + the
// strike-and-rewrite flip carried from Flip the Script. Teaches norm-literacy: what a social norm is (an
// unwritten rule, made by people, not nature, and changeable), which norms help everyone (kindness, consent,
// hygiene) vs which harm by limiting/ranking a group (gendered limits, period stigma, son-preference, dowry,
// untouchability), where norms come from, the **good-norm test** (respects everyone? hurts no one? fair both
// ways?: the reusable lens Speak Up g19 inherits), and how to question & change harmful ones respectfully.
// QUESTION WITH RESPECT (love culture & elders AND ask "is this fair, na?"); KEEP THE GOOD (not "all rules
// are bad": sort them); heavy topics handled lightly (never graphic); CHANGE FEELS POSSIBLE (start small,
// one voice can begin it: India's own changed norms ground it). Builds on g17 (Flip the Script); prereq g17.
// Rendered by the shared engine (components/games/v2-engine.tsx). gameId "norm-storm". DO NOT RENAME.

import type { Scenario, V2GameConfig } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  // What is a norm?
  {"id":"ns-001","cat":"what-is-a-norm","type":"reflect","hook":"Lensy: a 'norm' is an unwritten rule lots of people just follow. Heard the word before?","prompt":"What do you think?","options":["New word","Kind of","Makes sense"],"affirm":"A norm is an unwritten rule a group treats as 'normal'.","relearn":"A social norm is an unwritten rule a group follows.","persona":"any","source":"concept"},
  {"id":"ns-002","cat":"what-is-a-norm","type":"sort","hook":"Sort: is this a written rule, or an unwritten norm?","items":[{"id":"a","text":"\"Stop at a red light\""},{"id":"b","text":"\"Boys shouldn't cry\""},{"id":"c","text":"\"No phones in exams\""},{"id":"d","text":"\"Girls should be quiet\""},{"id":"e","text":"\"Wear a helmet on a bike\""},{"id":"f","text":"\"Touch elders' feet\""}],"bins":[{"id":"rule","label":"Written rule","valence":"neutral"},{"id":"norm","label":"Unwritten norm","valence":"tell"}],"key":{"a":"rule","b":"norm","c":"rule","d":"norm","e":"rule","f":"norm"},"relearn":"Norms are unwritten; rules are written down.","persona":"any","source":"concept"},
  {"id":"ns-003","cat":"what-is-a-norm","type":"sort","hook":"Sort: made by people, or fixed by nature?","items":[{"id":"a","text":"The sun rises in the east"},{"id":"b","text":"\"Pink is for girls\""},{"id":"c","text":"Water flows downhill"},{"id":"d","text":"\"Men should earn, women should cook\""},{"id":"e","text":"Rain falls down, not up"},{"id":"f","text":"\"Girls wear bangles, boys don't\""}],"bins":[{"id":"nature","label":"By nature","valence":"neutral"},{"id":"people","label":"Made by people","valence":"tell"}],"key":{"a":"nature","b":"people","c":"nature","d":"people","e":"nature","f":"people"},"relearn":"Norms are made by people, not fixed by nature.","persona":"any","source":"concept"},
  {"id":"ns-004","cat":"what-is-a-norm","type":"strike-rewrite","hook":"\"That's just how it's always been, so it can't change.\"","myth":{"un":"Norms have always been this way and can never change.","re":"Norms are made by people and change all the time.","why":"What's 'normal' is different across places and times."},"relearn":"Norms aren't fixed; people make them and people change them.","persona":"any","source":"concept"},
  {"id":"ns-005","cat":"what-is-a-norm","type":"sort","hook":"Sort: different in different places, or the same everywhere?","items":[{"id":"a","text":"Which hand you eat with"},{"id":"b","text":"That 2+2=4"},{"id":"c","text":"Taking shoes off indoors"},{"id":"d","text":"That ice is cold"},{"id":"e","text":"Whether you eat with hands or cutlery"},{"id":"f","text":"That the moon orbits Earth"}],"bins":[{"id":"varies","label":"Varies by place (norm)","valence":"tell"},{"id":"same","label":"Same everywhere (fact)","valence":"neutral"}],"key":{"a":"varies","b":"same","c":"varies","d":"same","e":"varies","f":"same"},"relearn":"Norms vary by place and culture; facts don't.","persona":"any","source":"concept"},
  {"id":"ns-006","cat":"what-is-a-norm","type":"spot","hook":"At a wedding. Spot what's an unwritten norm at work.","scene":[{"id":"a","text":"Everyone removes their shoes before the prayer area","trick":true},{"id":"b","text":"Guests greet the elders first","trick":true},{"id":"c","text":"There's lots of food laid out","trick":false},{"id":"d","text":"The hall has bright lights","trick":false},{"id":"e","text":"A band is playing music","trick":false}],"why":"Removing shoes and greeting elders first are unwritten norms. The food, lights and music are just things at the event.","relearn":"Lots of everyday behaviour is guided by unwritten norms.","persona":"any","source":"observation"},
  {"id":"ns-007","cat":"what-is-a-norm","type":"spot","hook":"At a railway counter. Spot the unwritten norm.","scene":[{"id":"a","text":"People stand in a line and wait their turn","trick":true},{"id":"b","text":"Someone who jumps the line gets frowns","trick":true},{"id":"c","text":"The counter sells train tickets","trick":false},{"id":"d","text":"There's a clock on the wall","trick":false},{"id":"e","text":"A fan is spinning overhead","trick":false}],"why":"Queuing and frowning at line-jumpers are norms we learn without any writing. The tickets, clock and fan are just part of the place.","relearn":"Norms are taught by example and reaction, not by rules.","persona":"any","source":"observation"},
  {"id":"ns-008","cat":"what-is-a-norm","type":"reflect","hook":"Lensy: not all norms are bad, and not all are good. Worth checking each one?","prompt":"What do you think?","options":["Yes","Check each","Fair point"],"affirm":"The skill is sorting helpful norms from harmful ones.","relearn":"Norms can be helpful or harmful; it's worth checking which.","persona":"any","source":"framing"},
  {"id":"ns-009","cat":"what-is-a-norm","type":"strike-rewrite","hook":"\"If everyone does it, it must be right.\"","myth":{"un":"If everyone follows a norm, it must be right.","re":"Common doesn't mean good; some popular norms are unfair.","why":"Lots of people once accepted unfair norms too."},"relearn":"A norm being common doesn't make it fair.","persona":"any","source":"critical thinking"},
  {"id":"ns-010","cat":"what-is-a-norm","type":"reflect","hook":"Lensy: ready to be a 'norm detective' and sort the storm of rules around you?","prompt":"What do you think?","options":["Ready","Let's go","Detective mode on"],"affirm":"A norm detective asks: does this help, or does this harm?","relearn":"You can examine norms instead of just absorbing them.","persona":"any","source":"framing"},
  {"id":"ns-011","cat":"what-is-a-norm","type":"match","hook":"Match the word to its meaning.","pairs":[{"left":"Norm","right":"Unwritten rule a group follows"},{"left":"Fact","right":"True everywhere, by nature"},{"left":"Law","right":"Written rule with consequences"},{"left":"Taste","right":"A liking that's just yours"},{"left":"Habit","right":"Something you do without thinking"}],"relearn":"Norm, fact, law, taste and habit are different kinds of 'rules'.","persona":"any","source":"vocabulary"},
  {"id":"ns-012","cat":"what-is-a-norm","type":"sort","hook":"Sort: a written law, or an unwritten norm?","items":[{"id":"a","text":"\"Wear a seatbelt\""},{"id":"b","text":"\"Don't wear white to a happy event\""},{"id":"c","text":"\"Pay your taxes\""},{"id":"d","text":"\"Touch elders' feet to show respect\""},{"id":"e","text":"\"Stop for a school bus\""},{"id":"f","text":"\"Bring sweets when you visit\""}],"bins":[{"id":"law","label":"Law","valence":"neutral"},{"id":"norm","label":"Norm","valence":"tell"}],"key":{"a":"law","b":"norm","c":"law","d":"norm","e":"law","f":"norm"},"relearn":"Some rules are laws; many are just norms.","persona":"any","source":"concept"},
  // Norms that help
  {"id":"ns-013","cat":"helpful-norms","type":"sort","hook":"Sort: does this norm help everyone, or quietly harm?","items":[{"id":"a","text":"Saying please and thank you"},{"id":"b","text":"Washing hands before eating"},{"id":"c","text":"Waiting your turn"},{"id":"d","text":"Helping someone who falls"},{"id":"e","text":"Serving girls food last"},{"id":"f","text":"Sharing the bench so all fit"}],"bins":[{"id":"helps","label":"Helps everyone","valence":"pos"},{"id":"harms","label":"Harms someone","valence":"neg"}],"key":{"a":"helps","b":"helps","c":"helps","d":"helps","e":"harms","f":"helps"},"relearn":"Many norms help everyone and keep life kind and fair.","persona":"any","source":"helpful norms"},
  {"id":"ns-014","cat":"helpful-norms","type":"sort","hook":"Sort: a helpful norm, or just a habit that hurts no one either way?","items":[{"id":"a","text":"Asking before borrowing"},{"id":"b","text":"Wearing blue on Mondays"},{"id":"c","text":"Not littering"},{"id":"d","text":"Parting your hair on one side"},{"id":"e","text":"Covering your mouth when you cough"},{"id":"f","text":"Eating curd before a trip"}],"bins":[{"id":"helps","label":"Helpful norm","valence":"pos"},{"id":"neutral","label":"Harmless habit","valence":"neutral"}],"key":{"a":"helps","b":"neutral","c":"helps","d":"neutral","e":"helps","f":"neutral"},"relearn":"Some norms actively help; others are just neutral habits.","persona":"any","source":"helpful norms"},
  {"id":"ns-015","cat":"helpful-norms","type":"match","hook":"Match the helpful norm to who it protects.","pairs":[{"left":"Ask before touching","right":"Everyone's body"},{"left":"Queue fairly","right":"People who waited"},{"left":"Tell the truth","right":"Trust between people"},{"left":"Lower your voice at night","right":"Neighbours who sleep"},{"left":"Bin your wrapper","right":"The shared street"}],"relearn":"Helpful norms protect people and trust.","persona":"any","source":"helpful norms"},
  {"id":"ns-016","cat":"helpful-norms","type":"match","hook":"Match the helpful norm to why it exists.","pairs":[{"left":"Wash hands","right":"Stops germs spreading"},{"left":"Say sorry","right":"Repairs a hurt"},{"left":"Help elders cross","right":"Keeps them safe"},{"left":"Share your notes","right":"Helps a friend catch up"},{"left":"Knock first","right":"Respects someone's space"}],"relearn":"Helpful norms usually have a caring reason behind them.","persona":"Rohit","source":"helpful norms"},
  {"id":"ns-017","cat":"helpful-norms","type":"reflect","hook":"Lensy: a good norm respects everyone and hurts no one. Useful definition?","prompt":"What do you think?","options":["Yes","Clear test","I'll remember it"],"affirm":"Respects everyone, hurts no one, that's a helpful norm.","relearn":"A helpful norm respects everyone and harms no one.","persona":"any","source":"definition"},
  {"id":"ns-018","cat":"helpful-norms","type":"reflect","hook":"Lensy: which helpful norm makes your day nicer?","prompt":"Pick one.","options":["People saying thanks","Folks waiting their turn","Neighbours helping out"],"affirm":"Helpful norms are the quiet glue of a kind community.","relearn":"Helpful norms keep a community kind and smooth.","persona":"any","source":"helpful norms"},
  {"id":"ns-019","cat":"helpful-norms","type":"branch","hook":"A new kid doesn't know the 'shoes off inside' norm here.","options":[{"text":"Kindly explain the norm, no shaming","consequence":"They learn and feel welcome.","outcome":"kind","best":true},{"text":"Laugh at them for not knowing","consequence":"Helpful norms are taught kindly, not used to shame."}],"debrief":"Even helpful norms should be shared with kindness, not mockery.","relearn":"Teach norms kindly; don't use them to shame newcomers.","persona":"any","source":"helpful norms / kindness"},
  {"id":"ns-020","cat":"helpful-norms","type":"branch","hook":"Everyone's littering at a picnic spot; the norm here seems to be 'just drop it'.","options":[{"text":"Follow the better norm: bin your trash anyway","consequence":"You set a helpful example; others may copy.","outcome":"leader","best":true},{"text":"Litter because everyone does","consequence":"You can keep a helpful norm even when others drop it."}],"debrief":"You can hold a helpful norm even when the crowd doesn't.","relearn":"You can keep doing the helpful thing even if others don't.","persona":"any","source":"helpful norms / integrity"},
  // Norms that harm
  {"id":"ns-021","cat":"harmful-norms","type":"sort","hook":"Sort: does this norm harm someone?","items":[{"id":"a","text":"\"Girls shouldn't go out after dark\""},{"id":"b","text":"\"Boys must never cry\""},{"id":"c","text":"\"Be kind to guests\""},{"id":"d","text":"\"Sons matter more than daughters\""},{"id":"e","text":"\"Everyone helps clear the plates\""},{"id":"f","text":"\"Only boys may light the lamp\""}],"bins":[{"id":"harms","label":"Harms someone","valence":"neg"},{"id":"helps","label":"Helps everyone","valence":"pos"}],"key":{"a":"harms","b":"harms","c":"helps","d":"harms","e":"helps","f":"harms"},"relearn":"Norms that limit or rank a group by gender harm people.","persona":"Diya","source":"harmful norms"},
  {"id":"ns-022","cat":"harmful-norms","type":"strike-rewrite","hook":"\"Girls shouldn't study too much; they'll marry anyway.\"","myth":{"un":"Girls don't need much education; they'll marry anyway.","re":"Every girl deserves a full education and her own future.","why":"Cutting girls' schooling harms them and society."},"relearn":"Girls deserve full education; the 'they'll marry anyway' norm harms them.","persona":"Diya","source":"harmful norms / education"},
  {"id":"ns-023","cat":"harmful-norms","type":"strike-rewrite","hook":"\"Boys must be tough providers and never show weakness.\"","myth":{"un":"Boys must always be tough providers who never show weakness.","re":"Boys can have feelings, ask for help, and share the load.","why":"This norm puts harmful pressure on boys too."},"relearn":"The 'always tough provider' norm harms boys as well.","persona":"Aarav","source":"harmful norms / masculinity"},
  {"id":"ns-024","cat":"harmful-norms","type":"strike-rewrite","hook":"\"During her period, a girl is impure and must stay apart.\"","myth":{"un":"A girl is impure during her period and must be kept apart.","re":"Periods are normal and healthy; no one should be shut out.","why":"Stigma norms shame girls for a natural process."},"relearn":"Period-stigma norms are harmful; menstruation is normal and healthy.","persona":"Diya","source":"harmful norms / menstruation"},
  {"id":"ns-025","cat":"harmful-norms","type":"strike-rewrite","hook":"\"A daughter is a burden; a son carries the family.\"","myth":{"un":"A daughter is a burden and a son is what really matters.","re":"Daughters and sons are equally valuable.","why":"Son-preference norms harm girls deeply."},"relearn":"Daughters and sons are equally valuable; son-preference harms girls.","persona":"any","source":"harmful norms / son preference"},
  {"id":"ns-026","cat":"harmful-norms","type":"strike-rewrite","hook":"\"A girl's family must give gifts and money to the groom.\"","myth":{"un":"It's normal for a bride's family to pay dowry.","re":"Dowry is harmful, and it's against the law in India.","why":"This norm treats girls as a cost and causes real harm."},"relearn":"Dowry is a harmful norm and is illegal in India.","persona":"Asha","source":"harmful norms / dowry (illegal since 1961)"},
  {"id":"ns-026b","cat":"harmful-norms","type":"strike-rewrite","hook":"\"Some people are 'lower' and shouldn't be touched or mixed with.\"","myth":{"un":"It's okay to treat some people as 'lower' or untouchable.","re":"Everyone is equal in dignity; untouchability is wrong and illegal.","why":"This old norm caused deep, unfair harm to whole communities."},"relearn":"Treating people as 'lower' is a harmful norm, and it's against the law.","persona":"any","source":"harmful norms / untouchability (abolished, Article 17)"},
  {"id":"ns-027","cat":"harmful-norms","type":"sort","hook":"Sort: who does each norm limit?","items":[{"id":"a","text":"\"Girls can't play outside\""},{"id":"b","text":"\"Boys can't do art\""},{"id":"c","text":"\"Girls must cook, not study\""},{"id":"d","text":"\"Boys can't be gentle\""},{"id":"e","text":"\"Girls shouldn't speak loudly\""},{"id":"f","text":"\"Boys shouldn't dance\""}],"bins":[{"id":"girls","label":"Limits girls","valence":"neg"},{"id":"boys","label":"Limits boys","valence":"neg"}],"key":{"a":"girls","b":"boys","c":"girls","d":"boys","e":"girls","f":"boys"},"relearn":"Harmful gender norms box in both girls and boys.","persona":"any","source":"harmful norms / gender"},
  {"id":"ns-028","cat":"harmful-norms","type":"sort","hook":"Sort: a harmful norm, or a fair rule?","items":[{"id":"a","text":"\"No outside play after dark for girls only\""},{"id":"b","text":"\"Everyone home by dark for safety\""},{"id":"c","text":"\"Only boys inherit property\""},{"id":"d","text":"\"Everyone shares chores\""},{"id":"e","text":"\"Girls alone serve the guests\""},{"id":"f","text":"\"We all wash up after meals\""}],"bins":[{"id":"harm","label":"Harmful norm","valence":"neg"},{"id":"fair","label":"Fair rule","valence":"pos"}],"key":{"a":"harm","b":"fair","c":"harm","d":"fair","e":"harm","f":"fair"},"relearn":"A rule that applies to one gender only is usually a harmful norm.","persona":"Diya","source":"harmful norms / fairness"},
  {"id":"ns-029","cat":"harmful-norms","type":"spot","hook":"At a family dinner. Spot the harmful norm.","scene":[{"id":"a","text":"The boys are served first and the most","trick":true},{"id":"b","text":"There's dal and rice","trick":false},{"id":"c","text":"The girls eat last, whatever's left","trick":true},{"id":"d","text":"A jug of water sits on the table","trick":false},{"id":"e","text":"Everyone washes hands before eating","trick":false}],"why":"Serving boys first and best is a harmful norm that treats girls as less.","relearn":"Serving food by gender rank is a harmful, unfair norm.","persona":"Diya","source":"harmful norms / observation"},
  {"id":"ns-030","cat":"harmful-norms","type":"spot","hook":"At a family gathering. Spot the harmful norm.","scene":[{"id":"a","text":"\"When will you control your son's crying?\"","trick":true},{"id":"b","text":"Tea is served","trick":false},{"id":"c","text":"\"He needs to man up\"","trick":true},{"id":"d","text":"The fan is turned on","trick":false},{"id":"e","text":"Relatives sit on the floor mat","trick":false}],"why":"Shaming a boy for crying is a harmful norm that hurts boys' feelings.","relearn":"Pressuring boys to never cry is a harmful norm.","persona":"Aarav","source":"harmful norms / masculinity"},
  {"id":"ns-031","cat":"harmful-norms","type":"branch","hook":"Relatives say Diya can't cycle to school anymore 'because she's a big girl now'.","options":[{"text":"Diya asks, respectfully, why her brother still can","consequence":"The unfair norm gets questioned out loud.","outcome":"brave","best":true},{"text":"Accept it silently","consequence":"A respectful question can expose an unfair gender norm."}],"debrief":"Asking 'why only me?' respectfully shines light on a harmful norm.","relearn":"You can respectfully question a norm that limits only you.","persona":"Diya","source":"harmful norms / voice"},
  {"id":"ns-032","cat":"harmful-norms","type":"branch","hook":"Friends say a boy can't join the rangoli-making 'because that's for girls'.","options":[{"text":"Say the art is for anyone and invite him in","consequence":"You break the harmful norm in the moment.","outcome":"ally","best":true},{"text":"Agree and shoo him away","consequence":"'Only girls/boys can do this' is a harmful norm; flip it."}],"debrief":"Gatekeeping fun by gender is a harmful norm you can refuse.","relearn":"You can refuse norms that gatekeep activities by gender.","persona":"any","source":"harmful norms / inclusion"},
  // Where norms come from
  {"id":"ns-033","cat":"where-from","type":"sort","hook":"Sort: where did each norm first come from?","items":[{"id":"a","text":"\"Cover the food\": keeps flies off"},{"id":"b","text":"\"Girls can't lead\": old power"},{"id":"c","text":"\"Greet elders\": shows respect"},{"id":"d","text":"\"Boys don't cook\": old role split"},{"id":"e","text":"\"Wash hands\": stay well"},{"id":"f","text":"\"Only sons inherit\": old unfairness"}],"bins":[{"id":"caring","label":"Began with care","valence":"pos"},{"id":"oldpower","label":"Old unfair habit","valence":"neg"}],"key":{"a":"caring","b":"oldpower","c":"caring","d":"oldpower","e":"caring","f":"oldpower"},"relearn":"Some norms began with care; others are just old, unfair habits.","persona":"any","source":"origins"},
  {"id":"ns-034","cat":"where-from","type":"strike-rewrite","hook":"\"Norms come from nature, so they can't be wrong.\"","myth":{"un":"Norms come from nature, so they must be correct.","re":"Norms come from people, history and habit, not nature.","why":"Human-made rules can be fair or unfair."},"relearn":"Norms come from people and history, not nature, so they can be wrong.","persona":"any","source":"origins"},
  {"id":"ns-035","cat":"where-from","type":"strike-rewrite","hook":"\"This norm is far too old to ever change.\"","myth":{"un":"This norm is too old to ever change.","re":"Many ancient norms in India have already changed.","why":"Age doesn't make a norm permanent or right."},"relearn":"Even very old norms can and do change.","persona":"any","source":"origins / change"},
  {"id":"ns-036","cat":"where-from","type":"strike-rewrite","hook":"\"Norms have always been the same everywhere.\"","myth":{"un":"Norms are the same in every place and time.","re":"Norms differ hugely across regions, families and eras.","why":"What's 'normal' is a local, changing thing."},"relearn":"Norms vary across place and time; none is universal.","persona":"any","source":"origins"},
  {"id":"ns-037","cat":"where-from","type":"sort","hook":"Sort: a norm that has genuinely changed in India, or a made-up 'change'?","items":[{"id":"a","text":"Girls now go to school in huge numbers"},{"id":"b","text":"Marrying off young kids is now banned"},{"id":"c","text":"The sky turned bright green one year"},{"id":"d","text":"Many widows can remarry now"},{"id":"e","text":"Untouchability is now illegal"},{"id":"f","text":"Rivers started flowing uphill"}],"bins":[{"id":"real","label":"Real change","valence":"pos"},{"id":"notreal","label":"Made-up","valence":"neg"}],"key":{"a":"real","b":"real","c":"notreal","d":"real","e":"real","f":"notreal"},"relearn":"Big harmful norms in India have genuinely changed over time.","persona":"any","source":"origins / India history"},
  {"id":"ns-038","cat":"where-from","type":"sort","hook":"Sort: who or what actually teaches us our norms?","items":[{"id":"a","text":"Family and elders"},{"id":"b","text":"TV, films and ads"},{"id":"c","text":"Friends and school"},{"id":"d","text":"The weather outside"},{"id":"e","text":"Stories and songs we grow up with"},{"id":"f","text":"The colour of your eyes"}],"bins":[{"id":"yes","label":"Teaches norms","valence":"pos"},{"id":"no","label":"Doesn't","valence":"neutral"}],"key":{"a":"yes","b":"yes","c":"yes","d":"no","e":"yes","f":"no"},"relearn":"We learn norms from family, media, friends and school.","persona":"any","source":"origins"},
  {"id":"ns-039","cat":"where-from","type":"reflect","hook":"Lensy: norms are like clothes a society wears, they can be changed when they no longer fit. Like that?","prompt":"What do you think?","options":["Yes","Good image","Makes sense"],"affirm":"Norms can be re-stitched to fit fairness better.","relearn":"Norms can be changed when they no longer serve fairness.","persona":"any","source":"metaphor"},
  {"id":"ns-040","cat":"where-from","type":"reflect","hook":"Lensy: knowing a norm was made by people, does it feel more changeable?","prompt":"What do you think?","options":["Yes","Much more","Good point"],"affirm":"If people made it, people can remake it.","relearn":"What people made, people can change.","persona":"any","source":"agency"},
  {"id":"ns-041","cat":"where-from","type":"reflect","hook":"Lensy: a norm that was normal 100 years ago can seem unfair now. Spot the lesson?","prompt":"What do you think?","options":["Norms change","Fairness grows","We learn better"],"affirm":"Each generation can question and improve the norms it inherits.","relearn":"Each generation can improve the norms it inherits.","persona":"any","source":"change"},
  {"id":"ns-042","cat":"where-from","type":"spot","hook":"An old school book from decades ago. Spot the bits that are an outdated norm.","scene":[{"id":"a","text":"\"Girls' subjects: cooking and sewing only\"","trick":true},{"id":"b","text":"It has a maths chapter for everyone","trick":false},{"id":"c","text":"\"Boys' subjects: science and trade only\"","trick":true},{"id":"d","text":"It teaches reading to the whole class","trick":false},{"id":"e","text":"There is a map of India inside","trick":false}],"why":"Splitting subjects by gender was once normal; now girls and boys study everything.","relearn":"Gender-split schooling was once a norm; it has changed.","persona":"Diya","source":"origins / change"},
  {"id":"ns-043","cat":"where-from","type":"spot","hook":"A grandparent's stories. Spot the two norms that have since changed.","scene":[{"id":"a","text":"\"A widow could never remarry\"","trick":true},{"id":"b","text":"\"We walked far to the well\"","trick":false},{"id":"c","text":"\"Girls left school early\"","trick":true},{"id":"d","text":"\"We sang at festival time\"","trick":false},{"id":"e","text":"\"Now things are fairer\"","trick":false}],"why":"Banning widow remarriage and cutting girls' schooling were harmful norms that have changed.","relearn":"Harmful norms our elders knew have changed for the better.","persona":"Rohit","source":"origins / change"},
  // The good-norm test
  {"id":"ns-044","cat":"good-norm-test","type":"sort","persona":"any","source":"good-norm test","relearn":"Test a norm: does it respect everyone equally?","hook":"The test: does this norm respect everyone? Sort.","items":[{"id":"a","text":"\"Everyone shares the housework\""},{"id":"b","text":"\"Only girls do housework\""},{"id":"c","text":"\"Listen when someone says stop\""},{"id":"d","text":"\"Boys decide, girls obey\""},{"id":"e","text":"\"Greet every guest the same\""},{"id":"f","text":"\"Sons get the bigger plate\""}],"bins":[{"id":"pass","label":"Respects everyone","valence":"pos"},{"id":"fail","label":"Disrespects someone","valence":"neg"}],"key":{"a":"pass","b":"fail","c":"pass","d":"fail","e":"pass","f":"fail"}},
  {"id":"ns-045","cat":"good-norm-test","type":"sort","persona":"Diya","source":"good-norm test / empathy","relearn":"A good norm feels fair even if you swap places.","hook":"The test: would it feel fair if you were on the other side? Sort.","items":[{"id":"a","text":"\"Take turns on the swing\""},{"id":"b","text":"\"Boys go first, always\""},{"id":"c","text":"\"Share the last samosa\""},{"id":"d","text":"\"Girls serve, then eat last\""},{"id":"e","text":"\"Both of us help with bags\""},{"id":"f","text":"\"Only she fetches the water\""}],"bins":[{"id":"fair","label":"Fair both ways","valence":"pos"},{"id":"unfair","label":"Unfair if flipped","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"}},
  {"id":"ns-046","cat":"good-norm-test","type":"branch","hook":"You're unsure if a family norm is helpful or harmful.","options":[{"text":"Ask: does it hurt anyone, and is it fair both ways?","consequence":"The test makes the answer clear.","outcome":"thoughtful","best":true},{"text":"Just assume it's fine because it's old","consequence":"Run it through the test instead of assuming."}],"debrief":"The good-norm test: respects everyone, hurts no one, fair both ways.","relearn":"Use the good-norm test instead of assuming a norm is fine.","persona":"any","source":"good-norm test"},
  {"id":"ns-047","cat":"good-norm-test","type":"branch","hook":"A norm is comfortable for you but quietly unfair to someone else.","options":[{"text":"Notice the unfairness and question it, even though it suits you","consequence":"You choose fairness over your own comfort.","outcome":"fair","best":true},{"text":"Keep quiet because it benefits you","consequence":"A good norm is fair to others too, not just to you."}],"debrief":"A norm that only suits you while hurting others fails the test.","relearn":"Question norms that suit you but harm others.","persona":"Aarav","source":"good-norm test / fairness"},
  {"id":"ns-048","cat":"good-norm-test","type":"branch","hook":"You spot a norm that's harmful but everyone insists it's 'tradition'.","options":[{"text":"Respect the people, but still question the harmful norm","consequence":"You separate caring for people from accepting harm.","outcome":"wise","best":true},{"text":"Accept it because it's called tradition","consequence":"You can honour people while questioning a harmful tradition."}],"debrief":"Calling something 'tradition' doesn't pass it through the test.","relearn":"Respect people, still question a harmful tradition.","persona":"Asha","source":"good-norm test / respect"},
  {"id":"ns-049","cat":"good-norm-test","type":"strike-rewrite","hook":"\"If it's tradition, it must be good.\"","myth":{"un":"If something is tradition, it must be good.","re":"Traditions can be kind or harmful; test each one.","why":"Age and habit don't equal fairness."},"relearn":"Tradition isn't automatically good; test it for harm.","persona":"any","source":"good-norm test"},
  {"id":"ns-050","cat":"good-norm-test","type":"strike-rewrite","hook":"\"Questioning a norm means I'm disrespecting my elders.\"","myth":{"un":"Questioning a norm disrespects my elders.","re":"You can love and respect elders and still ask 'is this fair?'.","why":"Respect and honest questions can go together."},"relearn":"Questioning a norm isn't the same as disrespecting people.","persona":"Diya","source":"good-norm test / respect"},
  {"id":"ns-051","cat":"good-norm-test","type":"role-play","hook":"You want to question a norm without sounding rude.","setup":"Ask with curiosity. Say:","yourLine":[{"text":"\"I'm just wondering, why is it like that?\"","best":true},{"text":"\"That's so stupid and old.\""}],"relearn":"A curious, respectful question opens minds better than an attack.","persona":"Diya","source":"good-norm test / voice"},
  {"id":"ns-052","cat":"good-norm-test","type":"role-play","hook":"An elder explains a norm; you see it harms someone.","setup":"Respond respectfully but honestly. Say:","yourLine":[{"text":"\"I hear you, can we make it fairer for everyone?\"","best":true},{"text":"\"You're just wrong.\""}],"relearn":"You can acknowledge someone and still push for fairness.","persona":"any","source":"good-norm test / voice"},
  {"id":"ns-053","cat":"good-norm-test","type":"reflect","hook":"Lensy: the three-part test, respects everyone, hurts no one, fair both ways. Got it?","prompt":"What do you think?","options":["Got it","Easy to remember","Three checks"],"affirm":"Run any norm through those three checks.","relearn":"Good-norm test: respects everyone, hurts no one, fair both ways.","persona":"any","source":"good-norm test"},
  {"id":"ns-054","cat":"good-norm-test","type":"reflect","hook":"Lensy: which norm around you would you put to the test first?","prompt":"Think of one.","options":["A chore one","A 'girls/boys can't' one","A 'log kya kahenge' one"],"affirm":"Testing the norms closest to you is where change starts.","relearn":"Start by testing the norms nearest to your own life.","persona":"any","source":"good-norm test / application"},
  {"id":"ns-055","cat":"good-norm-test","type":"match","persona":"any","source":"good-norm test","relearn":"Run each norm through the fairness test to see if it passes.","hook":"Match the norm to its test result.","pairs":[{"left":"\"Be kind to all\"","right":"Passes"},{"left":"\"Girls eat last\"","right":"Fails"},{"left":"\"Wait your turn\"","right":"Passes too"},{"left":"\"Boys can't cry\"","right":"Fails too"},{"left":"\"Ask before sharing\"","right":"Also passes"}]},
  {"id":"ns-056","cat":"good-norm-test","type":"sort","persona":"any","source":"good-norm test","relearn":"Helpful norms pass the fairness test; harmful ones fail it.","hook":"Sort: passes the good-norm test, or fails it?","items":[{"id":"a","text":"\"Ask before sharing someone's photo\""},{"id":"b","text":"\"Boys never apologise\""},{"id":"c","text":"\"Help a lost child\""},{"id":"d","text":"\"Girls shouldn't laugh loudly\""},{"id":"e","text":"\"Say thanks to the cook\""},{"id":"f","text":"\"Daughters skip school for chores\""}],"bins":[{"id":"pass","label":"Passes","valence":"pos"},{"id":"fail","label":"Fails","valence":"neg"}],"key":{"a":"pass","b":"fail","c":"pass","d":"fail","e":"pass","f":"fail"}},
  // Question it, change it
  {"id":"ns-057","cat":"question-change","type":"role-play","hook":"\"Log kya kahenge!\" (\"What will people say!\") is used to stop you doing something fair.","setup":"Answer it kindly. Say:","yourLine":[{"text":"\"Maybe people will learn something new.\"","best":true},{"text":"\"You're right, I'll stop.\""}],"relearn":"You can answer 'what will people say?' without giving up on fairness.","persona":"Diya","source":"question-change / log kya kahenge"},
  {"id":"ns-058","cat":"question-change","type":"role-play","hook":"A relative says \"good girls don't argue\".","setup":"Reframe it. Say:","yourLine":[{"text":"\"I'm not arguing, I'm asking a fair question.\"","best":true},{"text":"\"Sorry, I'll be quiet.\""}],"relearn":"Asking a fair question isn't 'arguing'.","persona":"Diya","source":"question-change / voice"},
  {"id":"ns-059","cat":"question-change","type":"role-play","hook":"Friends pressure you: \"everyone follows this, don't be weird\".","setup":"Hold your ground. Say:","yourLine":[{"text":"\"I'd rather be fair than just follow the crowd.\"","best":true},{"text":"\"Okay, I'll just go along.\""}],"relearn":"You can choose fairness over 'everyone does it'.","persona":"Aarav","source":"question-change / peer pressure"},
  {"id":"ns-060","cat":"question-change","type":"role-play","hook":"You want to suggest sharing chores fairly at home.","setup":"Propose it warmly. Say:","yourLine":[{"text":"\"What if we all share the chores, it'd be fairer.\"","best":true},{"text":"Say nothing and stay annoyed"}],"relearn":"You can warmly propose a fairer norm at home.","persona":"Rohit","source":"question-change / home"},
  {"id":"ns-061","cat":"question-change","type":"role-play","hook":"Someone says \"that's just our culture, don't question it\".","setup":"Respond with respect and curiosity. Say:","yourLine":[{"text":"\"I love our culture, that's why I want it to be fair.\"","best":true},{"text":"\"Fine, I won't care.\""}],"relearn":"Loving your culture and wanting it fairer go together.","persona":"Asha","source":"question-change / culture"},
  {"id":"ns-062","cat":"question-change","type":"role-play","hook":"Your younger sibling is being taught a harmful norm.","setup":"Offer a fairer message. Say:","yourLine":[{"text":"\"Actually, anyone can do that, you know.\"","best":true},{"text":"Let it pass"}],"relearn":"You can pass a fairer norm to younger kids.","persona":"any","source":"question-change / mentoring"},
  {"id":"ns-063","cat":"question-change","type":"role-play","hook":"A teacher follows a gendered classroom norm without noticing.","setup":"Ask politely for fairness. Say:","yourLine":[{"text":"\"Could we all get a turn, miss, not just the boys?\"","best":true},{"text":"Stay silent"}],"relearn":"A polite request can update an unfair classroom norm.","persona":"any","source":"question-change / school"},
  {"id":"ns-064","cat":"question-change","type":"branch","hook":"You want to change a harmful norm, but you're just one kid.","options":[{"text":"Start small, question it, and find others who agree","consequence":"Small acts add up; others join in.","outcome":"changemaker","best":true},{"text":"Give up because you're only one person","consequence":"Big norm changes started with a few people questioning."}],"debrief":"Norms change when people start questioning them together.","relearn":"Even one questioning voice can start a norm changing.","persona":"Asha","source":"question-change / collective"},
  {"id":"ns-065","cat":"question-change","type":"branch","hook":"Questioning a norm might get you teased.","options":[{"text":"Question it anyway, kindly and bravely","consequence":"You model courage; some respect you for it.","outcome":"brave","best":true},{"text":"Stay quiet to avoid teasing","consequence":"Standing for fairness can mean some short-term teasing."}],"debrief":"Changing norms takes a little courage; it's worth it.","relearn":"Questioning a harmful norm can take courage and is worth it.","persona":"Aarav","source":"question-change / courage"},
  {"id":"ns-066","cat":"question-change","type":"branch","hook":"An adult dismisses your fair point with \"you're just a child\".","options":[{"text":"Stay calm; restate your point respectfully","consequence":"Your steadiness makes the point land.","outcome":"steady","best":true},{"text":"Shout back","consequence":"Calm, respectful repetition works better than shouting."}],"debrief":"Kids' fair questions deserve to be heard; stay calm and clear.","relearn":"Make your fair point calmly, even if you're dismissed at first.","persona":"Diya","source":"question-change / voice"},
  {"id":"ns-067","cat":"question-change","type":"branch","hook":"You realise you've been following a harmful norm yourself.","options":[{"text":"Own it and start doing the fairer thing","consequence":"You change yourself first, the truest start.","outcome":"growth","best":true},{"text":"Feel guilty and do nothing","consequence":"Changing your own behaviour is the best first step."}],"debrief":"Changing a norm starts with changing what you do.","relearn":"You can start by changing the norms in your own behaviour.","persona":"any","source":"question-change / self"},
  {"id":"ns-068","cat":"question-change","type":"branch","hook":"A fair new norm you suggested is catching on with your friends.","options":[{"text":"Keep encouraging it gently","consequence":"The fairer norm spreads and sticks.","outcome":"changemaker","best":true},{"text":"Stop, thinking the job's done","consequence":"New norms stick when you keep gently modelling them."}],"debrief":"New norms spread when people keep living them.","relearn":"Fairer norms spread when people keep modelling them.","persona":"any","source":"question-change / spread"},
  {"id":"ns-069","cat":"question-change","type":"strike-rewrite","hook":"\"One kid can't change what a whole society believes.\"","myth":{"un":"One child can't change society's norms.","re":"Big changes often begin with a few people questioning.","why":"Every changed norm started somewhere small."},"relearn":"Norm change can start with one questioning voice.","persona":"Asha","source":"question-change / agency"},
  {"id":"ns-070","cat":"question-change","type":"strike-rewrite","hook":"\"Going along with a harmful norm is harmless if I do nothing.\"","myth":{"un":"Quietly going along with a harmful norm does no harm.","re":"Silence helps a harmful norm survive.","why":"Norms continue when people keep following them."},"relearn":"Quietly following a harmful norm helps keep it alive.","persona":"any","source":"question-change / bystander"},
  {"id":"ns-071","cat":"question-change","type":"strike-rewrite","hook":"\"Changing norms means throwing away all our culture.\"","myth":{"un":"Questioning a harmful norm means rejecting all our culture.","re":"You can keep what's good in a culture and fix what harms.","why":"Cultures grow by keeping the kind parts and dropping the cruel."},"relearn":"You can honour a culture while changing its harmful norms.","persona":"Asha","source":"question-change / culture"},
  {"id":"ns-072","cat":"question-change","type":"reflect","hook":"Lensy: a fairer norm you'd love to see become normal?","prompt":"Pick one.","options":["Shared chores","Girls out as freely as boys","Boys allowed to cry"],"affirm":"Picture it normal, then help make it so.","relearn":"Imagining a fairer norm is the first step to making it normal.","persona":"any","source":"question-change / vision"},
  {"id":"ns-073","cat":"question-change","type":"reflect","hook":"Lensy: biggest take-away from Norm Storm?","prompt":"Pick your motto.","options":["Norms are made by people","Some help, some harm","Test it for fairness","I can help change it"],"affirm":"Sort the storm: keep the helpful, question the harmful.","relearn":"Norms are made by people; keep the helpful, question the harmful.","persona":"any","source":"consolidation"},
  {"id":"ns-074","cat":"question-change","type":"spot","hook":"Your own daily life. Spot a norm you could improve.","scene":[{"id":"a","text":"You wait your turn politely","trick":false},{"id":"b","text":"You let only one gender carry 'heavy' things","trick":true},{"id":"c","text":"You say thank you to helpers","trick":false},{"id":"d","text":"You assume cooking at home is only your sister's job","trick":true},{"id":"e","text":"You share your snacks with a friend who has none","trick":false}],"why":"Even small everyday habits can carry a harmful gendered norm worth fixing.","relearn":"You can spot and improve harmful norms in your own routine.","persona":"any","source":"question-change / self"},
  {"id":"ns-075","cat":"what-is-a-norm","type":"sort","hook":"Sort: a norm the whole group shares, or just your own taste?","items":[{"id":"a","text":"Everyone greets elders first"},{"id":"b","text":"You like mango over banana"},{"id":"c","text":"People queue at the counter"},{"id":"d","text":"You prefer the window seat"},{"id":"e","text":"Guests take off shoes at the door"},{"id":"f","text":"You love rainy days best"}],"bins":[{"id":"norm","label":"Shared norm","valence":"tell"},{"id":"taste","label":"Personal taste","valence":"neutral"}],"key":{"a":"norm","b":"taste","c":"norm","d":"taste","e":"norm","f":"taste"},"relearn":"A norm is shared by a group; a taste is just yours.","persona":"any","source":"concept"},
  {"id":"ns-076","cat":"helpful-norms","type":"sort","hook":"Sort: a safety or consent norm worth keeping?","items":[{"id":"a","text":"Ask before hugging someone"},{"id":"b","text":"Knock before entering a room"},{"id":"c","text":"Grab whatever you want"},{"id":"d","text":"Hold the door for the next person"},{"id":"e","text":"Read a friend's diary uninvited"},{"id":"f","text":"Check it's okay before sharing a photo"}],"bins":[{"id":"keep","label":"Helpful, keep it","valence":"pos"},{"id":"drop","label":"Unkind, drop it","valence":"neg"}],"key":{"a":"keep","b":"keep","c":"drop","d":"keep","e":"drop","f":"keep"},"relearn":"Consent and courtesy norms protect everyone and are worth keeping.","persona":"any","source":"helpful norms"},
  {"id":"ns-077","cat":"harmful-norms","type":"sort","hook":"Sort: which of these norms ranks one group above another?","items":[{"id":"a","text":"Sons inherit, daughters don't"},{"id":"b","text":"Everyone shares the sweets"},{"id":"c","text":"Boys' opinions count more"},{"id":"d","text":"We all clean up together"},{"id":"e","text":"Only men sit at the head table"},{"id":"f","text":"Every voice gets a turn"}],"bins":[{"id":"ranks","label":"Ranks a group higher","valence":"neg"},{"id":"equal","label":"Treats all equally","valence":"pos"}],"key":{"a":"ranks","b":"equal","c":"ranks","d":"equal","e":"ranks","f":"equal"},"relearn":"Norms that rank one gender above another are harmful.","persona":"Diya","source":"harmful norms"},
  {"id":"ns-078","cat":"where-from","type":"sort","hook":"Sort: a norm that changed over time, or one that stayed because it still helps?","items":[{"id":"a","text":"Girls now play competitive sport"},{"id":"b","text":"We still say thank you"},{"id":"c","text":"Many dads now help cook"},{"id":"d","text":"We still help elders cross the road"},{"id":"e","text":"Women now drive buses and trains"},{"id":"f","text":"We still queue at the ration shop"}],"bins":[{"id":"changed","label":"Has changed","valence":"pos"},{"id":"stayed","label":"Stayed (still helps)","valence":"neutral"}],"key":{"a":"changed","b":"stayed","c":"changed","d":"stayed","e":"changed","f":"stayed"},"relearn":"Harmful norms change while helpful ones can stay.","persona":"any","source":"origins / change"},
  {"id":"ns-079","cat":"good-norm-test","type":"sort","persona":"any","source":"good-norm test","relearn":"Fair, inclusive norms pass the test; limiting ones fail.","hook":"Sort: passes the good-norm test, or fails?","items":[{"id":"a","text":"Everyone gets a turn to speak"},{"id":"b","text":"Girls can't ride bikes"},{"id":"c","text":"Share credit fairly"},{"id":"d","text":"Boys must hide fear"},{"id":"e","text":"Welcome new kids kindly"},{"id":"f","text":"Only sons get to study"}],"bins":[{"id":"pass","label":"Passes","valence":"pos"},{"id":"fail","label":"Fails","valence":"neg"}],"key":{"a":"pass","b":"fail","c":"pass","d":"fail","e":"pass","f":"fail"}},
  {"id":"ns-080","cat":"harmful-norms","type":"spot","hook":"A TV serial scene. Spot the harmful norm.","scene":[{"id":"a","text":"The daughter-in-law does every chore alone","trick":true},{"id":"b","text":"There is a family dinner","trick":false},{"id":"c","text":"The men are praised just for showing up","trick":true},{"id":"d","text":"The serial plays on the TV","trick":false},{"id":"e","text":"The title song repeats each episode","trick":false}],"why":"Showing women doing all the work while men are praised for little is a harmful norm.","relearn":"Media often normalises women doing all the household labour; spot it.","persona":"any","source":"harmful norms / media"},
  {"id":"ns-081","cat":"helpful-norms","type":"spot","hook":"On the bus. Spot the helpful norms.","scene":[{"id":"a","text":"A young person gives their seat to someone who needs it","trick":true},{"id":"b","text":"The bus is blue","trick":false},{"id":"c","text":"People say a quiet thank you","trick":true},{"id":"d","text":"The route number is forty","trick":false},{"id":"e","text":"It is a Tuesday afternoon","trick":false}],"why":"Offering a seat and saying thanks are helpful norms; the colour, number and day are just facts.","relearn":"Helpful norms like offering a seat keep a community caring.","persona":"Rohit","source":"helpful norms"},
  {"id":"ns-082","cat":"harmful-norms","type":"match","hook":"Match the harmful norm to who it hurts most.","pairs":[{"left":"Girls eat last","right":"Girls"},{"left":"Boys can't cry","right":"Boys"},{"left":"Daughters are a burden","right":"Daughters"},{"left":"Only sons inherit","right":"Sisters"},{"left":"Widows stay apart","right":"Widows"}],"relearn":"Each harmful norm has a clear group it hurts.","persona":"Diya","source":"harmful norms"},
  {"id":"ns-083","cat":"question-change","type":"branch","hook":"A fair idea of yours is dismissed as \"not how we do things\".","options":[{"text":"Gently ask \"could we try a fairer way?\"","consequence":"You open a door instead of a fight.","outcome":"changemaker","best":true},{"text":"Drop it instantly","consequence":"A gentle nudge can start a norm shifting."}],"debrief":"\"Not how we do things\" can become \"how we do things now\".","relearn":"You can gently propose a fairer way when waved off with tradition.","persona":"Asha","source":"question-change"},
  {"id":"ns-900","cat":"good-norm-test","type":"sort","persona":"any","source":"good-norm test","relearn":"A good norm respects everyone; a limiting one fails the test.","hook":"Run each norm through the test: passes or fails?","items":[{"id":"a","text":"\"Greet guests warmly\""},{"id":"b","text":"\"Only sons light the lamp\""},{"id":"c","text":"\"Wash hands before eating\""},{"id":"d","text":"\"Girls skip school on chore days\""},{"id":"e","text":"\"Say sorry when you bump someone\""},{"id":"f","text":"\"Boys mustn't cook\""}],"bins":[{"id":"pass","label":"Passes","valence":"pos"},{"id":"fail","label":"Fails","valence":"neg"}],"key":{"a":"pass","b":"fail","c":"pass","d":"fail","e":"pass","f":"fail"}},
  {"id":"ns-901","cat":"good-norm-test","type":"sort","persona":"Diya","source":"good-norm test / fairness","relearn":"A norm that helps everyone passes; one that ranks a group fails.","hook":"Diya tests the norms at home. Passes or fails?","items":[{"id":"a","text":"\"Everyone clears their own plate\""},{"id":"b","text":"\"Brothers get served first\""},{"id":"c","text":"\"Knock before entering a room\""},{"id":"d","text":"\"Girls eat after the men\""},{"id":"e","text":"\"Share the TV remote by turns\""},{"id":"f","text":"\"Daughters need no pocket money\""}],"bins":[{"id":"pass","label":"Passes","valence":"pos"},{"id":"fail","label":"Fails","valence":"neg"}],"key":{"a":"pass","b":"fail","c":"pass","d":"fail","e":"pass","f":"fail"}},
  {"id":"ns-902","cat":"good-norm-test","type":"sort","persona":"any","source":"good-norm test","relearn":"Fair both ways passes the test; unfair if flipped fails it.","hook":"Swap places: would it still feel fair? Sort.","items":[{"id":"a","text":"\"Take turns picking the game\""},{"id":"b","text":"\"Boys lead, girls follow\""},{"id":"c","text":"\"Split the sweets equally\""},{"id":"d","text":"\"Only girls fetch water\""},{"id":"e","text":"\"Listen when anyone is speaking\""},{"id":"f","text":"\"Sons inherit, daughters don't\""}],"bins":[{"id":"fair","label":"Fair both ways","valence":"pos"},{"id":"unfair","label":"Unfair if flipped","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"}},
  {"id":"ns-903","cat":"good-norm-test","type":"sort","persona":"Aarav","source":"good-norm test / boys","relearn":"Norms that box boys in fail the test too.","hook":"Aarav checks the 'be a man' rules. Passes or fails?","items":[{"id":"a","text":"\"Ask for help when you're stuck\""},{"id":"b","text":"\"Boys must never cry\""},{"id":"c","text":"\"Cheer your friend's win\""},{"id":"d","text":"\"Real men hide their fear\""},{"id":"e","text":"\"Apologise when you're wrong\""},{"id":"f","text":"\"Boys can't like dance\""}],"bins":[{"id":"pass","label":"Passes","valence":"pos"},{"id":"fail","label":"Fails","valence":"neg"}],"key":{"a":"pass","b":"fail","c":"pass","d":"fail","e":"pass","f":"fail"}},
  {"id":"ns-904","cat":"good-norm-test","type":"sort","persona":"any","source":"good-norm test / respects everyone","relearn":"The first check: does the norm respect everyone? Sort.","hook":"Does each norm respect everyone, or disrespect someone?","items":[{"id":"a","text":"\"Call elders by a respectful name\""},{"id":"b","text":"\"Mock the new kid's accent\""},{"id":"c","text":"\"Let everyone finish their turn\""},{"id":"d","text":"\"Tease boys who help in the kitchen\""},{"id":"e","text":"\"Welcome a guest with water\""},{"id":"f","text":"\"Laugh at a girl who plays cricket\""}],"bins":[{"id":"resp","label":"Respects everyone","valence":"pos"},{"id":"dis","label":"Disrespects someone","valence":"neg"}],"key":{"a":"resp","b":"dis","c":"resp","d":"dis","e":"resp","f":"dis"}},
  {"id":"ns-905","cat":"good-norm-test","type":"sort","persona":"any","source":"good-norm test / hurts no one","relearn":"The second check: does the norm hurt anyone? Sort.","hook":"Does each norm hurt no one, or quietly hurt someone?","items":[{"id":"a","text":"\"Cover your cough\""},{"id":"b","text":"\"Keep girls home when they bleed\""},{"id":"c","text":"\"Queue at the water tap\""},{"id":"d","text":"\"Skip a daughter's birthday\""},{"id":"e","text":"\"Switch off taps you're not using\""},{"id":"f","text":"\"Stop a widow from festivals\""}],"bins":[{"id":"safe","label":"Hurts no one","valence":"pos"},{"id":"hurt","label":"Quietly hurts someone","valence":"neg"}],"key":{"a":"safe","b":"hurt","c":"safe","d":"hurt","e":"safe","f":"hurt"}},
  {"id":"ns-906","cat":"good-norm-test","type":"sort","persona":"Asha","source":"good-norm test / keep-or-question","relearn":"Norms that pass the test are worth keeping; ones that fail are worth questioning.","hook":"Asha asks: keep this norm, or question it?","items":[{"id":"a","text":"\"Help a neighbour move heavy bags\""},{"id":"b","text":"\"Girls can't ride a cycle to school\""},{"id":"c","text":"\"Thank the cook after a meal\""},{"id":"d","text":"\"Pay dowry to marry a daughter\""},{"id":"e","text":"\"Share notes with a sick classmate\""},{"id":"f","text":"\"Boys must earn, never care\""}],"bins":[{"id":"keep","label":"Keep it","valence":"pos"},{"id":"quest","label":"Question it","valence":"uhoh"}],"key":{"a":"keep","b":"quest","c":"keep","d":"quest","e":"keep","f":"quest"}},
  {"id":"ns-907","cat":"good-norm-test","type":"sort","persona":"any","source":"good-norm test / tradition","relearn":"Calling a norm 'tradition' doesn't pass it; test each one.","hook":"Both are called 'tradition'. Test them: pass or fail?","items":[{"id":"a","text":"\"Touch elders' feet to greet them\""},{"id":"b","text":"\"Hide a girl away when she's bleeding\""},{"id":"c","text":"\"Cook a special dish for festivals\""},{"id":"d","text":"\"Serve sons bigger portions\""},{"id":"e","text":"\"Sing together at a wedding\""},{"id":"f","text":"\"Keep daughters out of family talks\""}],"bins":[{"id":"pass","label":"Passes the test","valence":"pos"},{"id":"fail","label":"Fails the test","valence":"neg"}],"key":{"a":"pass","b":"fail","c":"pass","d":"fail","e":"pass","f":"fail"}},
  {"id":"ns-908","cat":"good-norm-test","type":"sort","persona":"any","source":"good-norm test / who it's for","relearn":"A norm that applies to one gender only usually fails the test.","hook":"One gender only, or fair for all? Sort.","items":[{"id":"a","text":"\"Anyone can lead the class line\""},{"id":"b","text":"\"Only girls must stay quiet\""},{"id":"c","text":"\"Everyone helps clean up\""},{"id":"d","text":"\"Only boys may go out after dark\""},{"id":"e","text":"\"All children get equal turns to talk\""},{"id":"f","text":"\"Only girls learn to cook\""}],"bins":[{"id":"all","label":"Fair for all","valence":"pos"},{"id":"one","label":"One gender only","valence":"neg"}],"key":{"a":"all","b":"one","c":"all","d":"one","e":"all","f":"one"}},
  {"id":"ns-909","cat":"good-norm-test","type":"sort","persona":"Rohit","source":"good-norm test / home","relearn":"At home, sort the chores-norm by who it's fair to.","hook":"Rohit re-checks the house rules. Fair or unfair?","items":[{"id":"a","text":"\"Dad and the kids wash dishes too\""},{"id":"b","text":"\"Only mum does all the cooking\""},{"id":"c","text":"\"Everyone makes their own bed\""},{"id":"d","text":"\"Sister tidies the boys' room\""},{"id":"e","text":"\"We split the weekend chores\""},{"id":"f","text":"\"Girls can't watch the match\""}],"bins":[{"id":"fair","label":"Fair to all","valence":"pos"},{"id":"unfair","label":"Unfair to someone","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"}},
  {"id":"ns-910","cat":"good-norm-test","type":"sort","persona":"any","source":"good-norm test / why behind it","relearn":"A caring reason hints the norm passes; a ranking reason hints it fails.","hook":"Look at the reason behind each. Passes or fails?","items":[{"id":"a","text":"\"Wash veggies so no one falls sick\""},{"id":"b","text":"\"Girls walk behind to 'know their place'\""},{"id":"c","text":"\"Whisper in the library so others can read\""},{"id":"d","text":"\"Boys skip chores to 'stay manly'\""},{"id":"e","text":"\"Wait at the gate so no one is left out\""},{"id":"f","text":"\"Daughters drop out to save 'their' money\""}],"bins":[{"id":"pass","label":"Passes","valence":"pos"},{"id":"fail","label":"Fails","valence":"neg"}],"key":{"a":"pass","b":"fail","c":"pass","d":"fail","e":"pass","f":"fail"}},
  {"id":"ns-911","cat":"good-norm-test","type":"sort","persona":"any","source":"good-norm test / common-isn't-fair","relearn":"Common doesn't mean fair: a popular norm can still fail the test.","hook":"Both are common. Which still passes the fairness test?","items":[{"id":"a","text":"\"Most people queue at the clinic\""},{"id":"b","text":"\"Most homes serve girls last\""},{"id":"c","text":"\"Most folks remove shoes indoors\""},{"id":"d","text":"\"Most say boys shouldn't cry\""},{"id":"e","text":"\"Most greet a guest with chai\""},{"id":"f","text":"\"Most expect girls to marry, not study\""}],"bins":[{"id":"pass","label":"Passes","valence":"pos"},{"id":"fail","label":"Fails","valence":"neg"}],"key":{"a":"pass","b":"fail","c":"pass","d":"fail","e":"pass","f":"fail"}},
  {"id":"ns-912","cat":"good-norm-test","type":"sort","persona":"Diya","source":"good-norm test / school","relearn":"At school, sort the norms by whether they pass the fairness test.","hook":"Diya checks the playground rules. Passes or fails?","items":[{"id":"a","text":"\"Pick teams by skill, not gender\""},{"id":"b","text":"\"Girls can't play football\""},{"id":"c","text":"\"Share the ground time fairly\""},{"id":"d","text":"\"Boys grab the front benches\""},{"id":"e","text":"\"Help a classmate who fell\""},{"id":"f","text":"\"Only boys carry the sports kit\""}],"bins":[{"id":"pass","label":"Passes","valence":"pos"},{"id":"fail","label":"Fails","valence":"neg"}],"key":{"a":"pass","b":"fail","c":"pass","d":"fail","e":"pass","f":"fail"}},
  {"id":"ns-913","cat":"good-norm-test","type":"sort","persona":"any","source":"good-norm test / consent","relearn":"Consent and courtesy norms pass; norms that override a person fail.","hook":"Does the norm honour a person's 'no', or override it? Sort.","items":[{"id":"a","text":"\"Ask before sharing someone's photo\""},{"id":"b","text":"\"Force a kid to hug a relative\""},{"id":"c","text":"\"Stop tickling when they say stop\""},{"id":"d","text":"\"Make a girl smile for guests\""},{"id":"e","text":"\"Check before borrowing a friend's bag\""},{"id":"f","text":"\"Pinch a baby's cheeks anyway\""}],"bins":[{"id":"hon","label":"Honours the person","valence":"pos"},{"id":"ovr","label":"Overrides them","valence":"neg"}],"key":{"a":"hon","b":"ovr","c":"hon","d":"ovr","e":"hon","f":"ovr"}},
  {"id":"ns-914","cat":"good-norm-test","type":"sort","persona":"any","source":"good-norm test / festivals","relearn":"Even festival customs face the test: include everyone, or shut someone out?","hook":"Festival customs: do they include all, or shut someone out?","items":[{"id":"a","text":"\"Whole family makes the rangoli\""},{"id":"b","text":"\"Only boys burst the crackers\""},{"id":"c","text":"\"Share sweets with neighbours\""},{"id":"d","text":"\"Girls can't enter during periods\""},{"id":"e","text":"\"Kids and elders both pick songs\""},{"id":"f","text":"\"Daughters serve, sons celebrate\""}],"bins":[{"id":"inc","label":"Includes everyone","valence":"pos"},{"id":"out","label":"Shuts someone out","valence":"neg"}],"key":{"a":"inc","b":"out","c":"inc","d":"out","e":"inc","f":"out"}},
  {"id":"ns-915","cat":"good-norm-test","type":"branch","persona":"any","source":"good-norm test","relearn":"Run a norm through the three checks instead of guessing.","hook":"A new family norm appears. You're not sure about it.","options":[{"text":"Ask: respects everyone? hurts no one? fair both ways?","consequence":"The three checks make it clear.","outcome":"clear","best":true},{"text":"Guess from your gut and move on","consequence":"Use the three checks so you're not just guessing."}],"debrief":"The good-norm test: respects everyone, hurts no one, fair both ways."},
  {"id":"ns-916","cat":"good-norm-test","type":"branch","persona":"Diya","source":"good-norm test / fairness","relearn":"A norm can suit you and still fail the test for someone else.","hook":"A rule gives you the comfy spot but leaves your cousin out.","options":[{"text":"Notice it's unfair to her and say so","consequence":"You choose fairness over your own comfort.","outcome":"fair","best":true},{"text":"Enjoy it quietly since it helps you","consequence":"A norm that only suits you fails the test."}],"debrief":"A norm that suits you but quietly harms someone else fails the test."},
  {"id":"ns-917","cat":"good-norm-test","type":"branch","persona":"Asha","source":"good-norm test / respect","relearn":"You can respect people and still question a harmful tradition.","hook":"Everyone calls a limiting custom 'our tradition'.","options":[{"text":"Honour the people, still ask if the custom is fair","consequence":"You separate caring for people from accepting harm.","outcome":"wise","best":true},{"text":"Accept it just because it's tradition","consequence":"'Tradition' doesn't pass a norm through the test."}],"debrief":"Calling something 'tradition' doesn't pass it through the test."},
  {"id":"ns-918","cat":"good-norm-test","type":"branch","persona":"Aarav","source":"good-norm test / boys","relearn":"Test a 'boys must' norm the same way you'd test any other.","hook":"Mates say 'real boys never back down'. Is that a good norm?","options":[{"text":"Test it: does it hurt anyone? It boxes boys in","consequence":"You see the norm harms boys too.","outcome":"clear","best":true},{"text":"Follow it so you look tough","consequence":"A norm that hurts you still fails the test."}],"debrief":"A 'boys must' norm that limits or harms boys fails the test too."},
  {"id":"ns-919","cat":"good-norm-test","type":"branch","persona":"any","source":"good-norm test / other-side","relearn":"The swap test: imagine being on the other side of the norm.","hook":"A norm clearly favours your side over someone else's.","options":[{"text":"Imagine you were on their side. Would it feel fair?","consequence":"The swap test shows if it's truly fair.","outcome":"thoughtful","best":true},{"text":"Keep it because it favours you","consequence":"Try the swap test before deciding it's fair."}],"debrief":"A good norm feels fair even if you swap places."},
  {"id":"ns-920","cat":"good-norm-test","type":"branch","persona":"any","source":"good-norm test / age","relearn":"Being old doesn't make a norm pass the fairness test.","hook":"Someone says a norm is fine 'because it's very old'.","options":[{"text":"Old or new, run it through the fairness test","consequence":"Age doesn't decide if a norm is fair.","outcome":"clear","best":true},{"text":"Agree it must be good since it's so old","consequence":"Age doesn't equal fairness. Test it."}],"debrief":"How old a norm is doesn't decide whether it passes the test."},
  {"id":"ns-921","cat":"good-norm-test","type":"branch","persona":"Diya","source":"good-norm test / start-close","relearn":"Change starts by testing the norms closest to your own life.","hook":"You want to test a norm but don't know where to begin.","options":[{"text":"Start with a norm in your own home or class","consequence":"Testing the norms nearest you is where change starts.","outcome":"grounded","best":true},{"text":"Wait for the 'big' unfair norms far away","consequence":"Start with the norms closest to your own life."}],"debrief":"Start by testing the norms closest to your own life."},
  {"id":"ns-922","cat":"good-norm-test","type":"branch","persona":"any","source":"good-norm test / common","relearn":"A common norm can still fail the test.","hook":"Friends say 'everyone follows it, so it must be fair'.","options":[{"text":"Point out common doesn't mean fair. Test it","consequence":"You check the norm, not the crowd.","outcome":"clear","best":true},{"text":"Agree because so many people follow it","consequence":"Lots of people once accepted unfair norms too."}],"debrief":"A norm being common doesn't make it pass the fairness test."},
  {"id":"ns-923","cat":"good-norm-test","type":"branch","persona":"Rohit","source":"good-norm test / home","relearn":"Re-test a home norm by who carries the load.","hook":"At home, only one person does every single chore.","options":[{"text":"Ask if it's fair both ways, then share the load","consequence":"A shared, fair norm passes the test.","outcome":"fair","best":true},{"text":"Leave it since it's always been that way","consequence":"'Always been' isn't the fairness test."}],"debrief":"Test a home norm by whether the load is shared fairly."},
  {"id":"ns-924","cat":"good-norm-test","type":"branch","persona":"any","source":"good-norm test / curious-question","relearn":"A curious question opens minds better than an attack.","hook":"You think a norm is unfair and want to raise it.","options":[{"text":"Ask kindly: 'I'm curious: is this fair to everyone?'","consequence":"A gentle question invites others to think.","outcome":"open","best":true},{"text":"Snap that the norm is stupid and old","consequence":"An attack makes people defend the norm harder."}],"debrief":"A curious, respectful question opens minds better than an attack."},
  {"id":"ns-925","cat":"good-norm-test","type":"branch","persona":"Asha","source":"good-norm test / keep-the-good","relearn":"The test sorts norms; it doesn't tear them all down.","hook":"Someone fears testing norms means rejecting every custom.","options":[{"text":"Explain we keep the kind norms and question the harmful","consequence":"The test sorts, it doesn't trash everything.","outcome":"balanced","best":true},{"text":"Say all old customs should just go","consequence":"It's a sort: keep the helpful, question the harmful."}],"debrief":"The good-norm test keeps the helpful norms and questions the harmful ones."},
  {"id":"ns-926","cat":"good-norm-test","type":"strike-rewrite","persona":"any","source":"good-norm test / common","relearn":"Common doesn't mean fair; test the norm, not the crowd.","hook":"\"If everyone follows it, the norm must be fair.\"","myth":{"un":"If everyone follows a norm, it must be fair.","re":"Common doesn't mean fair. Test each norm for harm.","why":"Lots of people once accepted unfair norms too."}},
  {"id":"ns-927","cat":"good-norm-test","type":"strike-rewrite","persona":"any","source":"good-norm test / comfort","relearn":"A norm being comfortable for you doesn't mean it passes.","hook":"\"It feels normal to me, so it can't be unfair.\"","myth":{"un":"If a norm feels normal to me, it can't be unfair.","re":"A norm can feel normal to you and still hurt someone else.","why":"Comfort for one side isn't the fairness test."}},
  {"id":"ns-928","cat":"good-norm-test","type":"strike-rewrite","persona":"Aarav","source":"good-norm test / boys","relearn":"Norms that limit boys fail the test too.","hook":"\"A norm only counts as unfair if it hurts girls.\"","myth":{"un":"A norm is only unfair if it hurts girls.","re":"Harmful gender norms box in both girls and boys.","why":"'Boys must be tough' limits boys and fails the test."}},
  {"id":"ns-929","cat":"good-norm-test","type":"strike-rewrite","persona":"any","source":"good-norm test / questioning","relearn":"Questioning a norm is not arguing or disrespect.","hook":"\"Asking if a norm is fair means I'm just arguing.\"","myth":{"un":"Asking if a norm is fair means I'm just arguing.","re":"A fair question isn't arguing. It's how norms get checked.","why":"Honest questions and respect can go together."}},
  {"id":"ns-930","cat":"good-norm-test","type":"strike-rewrite","persona":"any","source":"good-norm test / age","relearn":"Age doesn't make a norm pass the fairness test.","hook":"\"A very old norm has to be a good one.\"","myth":{"un":"A very old norm has to be a good one.","re":"Age doesn't make a norm fair; test old and new the same way.","why":"Habit and time don't equal fairness."}},
  {"id":"ns-931","cat":"good-norm-test","type":"strike-rewrite","persona":"Asha","source":"good-norm test / one-voice","relearn":"You only need one norm to test first: the one nearest you.","hook":"\"There's no point testing a norm unless it's a huge one.\"","myth":{"un":"There's no point testing a norm unless it's a huge one.","re":"Start by testing the small norms closest to your own life.","why":"That's exactly where real change begins."}},
  {"id":"ns-932","cat":"good-norm-test","type":"strike-rewrite","persona":"any","source":"good-norm test / law-vs-norm","relearn":"A norm isn't fair just because people call it a rule.","hook":"\"If people treat a norm like a rule, it must be right.\"","myth":{"un":"If people treat a norm like a rule, it must be right.","re":"An unwritten norm isn't automatically fair; test it for harm.","why":"Many 'rules' are just norms people never checked."}},
  {"id":"ns-933","cat":"good-norm-test","type":"strike-rewrite","persona":"Diya","source":"good-norm test / swap","relearn":"If it wouldn't feel fair flipped, the norm fails the test.","hook":"\"A norm is fair as long as it suits my side.\"","myth":{"un":"A norm is fair as long as it suits my side.","re":"If it wouldn't feel fair flipped to the other side, it fails.","why":"A good norm feels fair even when you swap places."}},
  {"id":"ns-934","cat":"good-norm-test","type":"role-play","persona":"Diya","source":"good-norm test / voice","relearn":"A curious question opens minds better than a complaint.","hook":"You want to test a family norm out loud, kindly.","setup":"Ask with curiosity. Say:","yourLine":[{"text":"\"I'm curious: is this fair to everyone?\"","best":true},{"text":"\"This rule is dumb, change it.\""}]},
  {"id":"ns-935","cat":"good-norm-test","type":"role-play","persona":"any","source":"good-norm test / voice","relearn":"Name the check, not the person, when you raise a norm.","hook":"You spot a norm that hurts one group at the table.","setup":"Question the norm, not the people. Say:","yourLine":[{"text":"\"Does this rule respect everyone here?\"","best":true},{"text":"\"You're all being unfair on purpose.\""}]},
  {"id":"ns-936","cat":"good-norm-test","type":"role-play","persona":"Aarav","source":"good-norm test / boys","relearn":"You can say a 'be a man' norm fails the test, calmly.","hook":"Friends push the 'boys never cry' norm on you.","setup":"Test it out loud. Say:","yourLine":[{"text":"\"Hiding feelings isn't fair to boys either.\"","best":true},{"text":"\"Yeah, crying is for losers.\""}]},
  {"id":"ns-937","cat":"good-norm-test","type":"role-play","persona":"any","source":"good-norm test / swap","relearn":"Invite the other person to try the swap test.","hook":"Someone defends a norm that only favours their side.","setup":"Offer the swap test. Say:","yourLine":[{"text":"\"Would it feel fair if we were swapped?\"","best":true},{"text":"\"Forget it, you'll never get it.\""}]},
  {"id":"ns-938","cat":"good-norm-test","type":"role-play","persona":"Asha","source":"good-norm test / respect","relearn":"Acknowledge the elder, then ask the fairness question.","hook":"An elder explains a custom you think is unfair.","setup":"Respect them and still ask. Say:","yourLine":[{"text":"\"I hear you. Can we make it fairer for all?\"","best":true},{"text":"\"That's old-fashioned nonsense.\""}]},
  {"id":"ns-939","cat":"good-norm-test","type":"role-play","persona":"Diya","source":"good-norm test / tradition","relearn":"You can question a tradition without attacking it.","hook":"A custom is defended only with 'it's tradition'.","setup":"Question gently. Say:","yourLine":[{"text":"\"I love our traditions. Is this part fair?\"","best":true},{"text":"\"Traditions are all pointless anyway.\""}]},
  {"id":"ns-940","cat":"good-norm-test","type":"role-play","persona":"any","source":"good-norm test / common","relearn":"'Everyone does it' isn't proof a norm is fair.","hook":"Friends say a norm is fine because everyone follows it.","setup":"Make the point kindly. Say:","yourLine":[{"text":"\"Lots of people did unfair things once too.\"","best":true},{"text":"\"You're all sheep for following it.\""}]},
  {"id":"ns-941","cat":"good-norm-test","type":"role-play","persona":"Rohit","source":"good-norm test / home","relearn":"Propose the fairer version of a home norm warmly.","hook":"Only one person does every chore at home.","setup":"Suggest a fairer norm. Say:","yourLine":[{"text":"\"Let's share the chores so it's fair to all.\"","best":true},{"text":"\"That's just your job, not mine.\""}]},
  {"id":"ns-942","cat":"good-norm-test","type":"reflect","persona":"any","source":"good-norm test","relearn":"Good-norm test: respects everyone, hurts no one, fair both ways.","hook":"Lensy: three checks to test any norm. Which sticks for you?","prompt":"Pick one.","options":["Respects everyone","Hurts no one","Fair both ways"],"affirm":"Run any norm through those three checks."},
  {"id":"ns-943","cat":"good-norm-test","type":"reflect","persona":"any","source":"good-norm test / application","relearn":"Start by testing the norms nearest your own life.","hook":"Lensy: which norm around you would you test first?","prompt":"Think of one.","options":["A chore one","A 'girls/boys can't' one","A festival one"],"affirm":"Testing the norms closest to you is where change starts."},
  {"id":"ns-944","cat":"good-norm-test","type":"reflect","persona":"Diya","source":"good-norm test / swap","relearn":"A good norm feels fair even if you swap places.","hook":"Lensy: when has a rule felt unfair only when it was your turn?","prompt":"Remember a time.","options":["At home","At school","With friends"],"affirm":"Noticing the swap test is how you spot an unfair norm."},
  {"id":"ns-945","cat":"good-norm-test","type":"reflect","persona":"Aarav","source":"good-norm test / boys","relearn":"Norms that limit boys fail the test too.","hook":"Lensy: which 'boys must' norm would you most like to test?","prompt":"Pick one.","options":["'Never cry'","'Always be tough'","'Boys don't do chores'"],"affirm":"Any norm that boxes boys in is fair to question."},
  {"id":"ns-946","cat":"good-norm-test","type":"reflect","persona":"any","source":"good-norm test / respect","relearn":"Questioning a norm isn't disrespecting people.","hook":"Lensy: would you rather ask 'is this fair?' kindly or stay quiet?","prompt":"There's no wrong answer.","options":["Ask kindly","Ask later","Find someone to ask with"],"affirm":"Asking 'is this fair?' kindly respects both people and fairness."},
  {"id":"ns-947","cat":"good-norm-test","type":"reflect","persona":"any","source":"good-norm test / keep-the-good","relearn":"Keep the helpful norms; question the harmful ones.","hook":"Lensy: which helpful norm in your life would you keep for sure?","prompt":"Name one.","options":["Sharing","Saying thanks","Taking turns"],"affirm":"The test keeps the kind norms, not just questions the harmful."},
  {"id":"ns-948","cat":"good-norm-test","type":"reflect","persona":"Asha","source":"good-norm test / start-small","relearn":"One small test of a norm is where change starts.","hook":"Lensy: what's one tiny norm you could test this week?","prompt":"Pick something small.","options":["A chore split","A 'who goes first'","A 'who serves who'"],"affirm":"Even one small test of a norm is a real start."},
  {"id":"ns-949","cat":"good-norm-test","type":"reflect","persona":"any","source":"good-norm test / tradition","relearn":"Tradition isn't automatically good; test each one.","hook":"Lensy: which tradition would you happily test for fairness?","prompt":"Think of one you love.","options":["A festival one","A meal one","A greeting one"],"affirm":"You can love a tradition and still check if it's fair."},
  {"id":"ns-950","cat":"good-norm-test","type":"match","persona":"any","source":"good-norm test","relearn":"Run each norm through the fairness test to see if it passes.","hook":"Match the norm to its test result.","pairs":[{"left":"\"Be kind to everyone\"","right":"Passes: respects all"},{"left":"\"Girls eat last\"","right":"Fails: ranks a group"},{"left":"\"Wait your turn\"","right":"Passes: fair to all"},{"left":"\"Boys must hide tears\"","right":"Fails: boxes boys in"},{"left":"\"Ask before borrowing\"","right":"Passes: honours consent"}]},
  {"id":"ns-951","cat":"good-norm-test","type":"match","persona":"any","source":"good-norm test / three checks","relearn":"Match each part of the good-norm test to what it asks.","hook":"Match the test-check to its question.","pairs":[{"left":"Respects everyone","right":"Does it put anyone down?"},{"left":"Hurts no one","right":"Does it quietly harm someone?"},{"left":"Fair both ways","right":"Would it feel fair if swapped?"},{"left":"Not just tradition","right":"Is 'it's old' the only reason?"},{"left":"Not just common","right":"Is 'everyone does it' the reason?"}]},
  {"id":"ns-952","cat":"good-norm-test","type":"match","persona":"Diya","source":"good-norm test / flip","relearn":"A good norm stays fair when you flip who it's about.","hook":"Match the unfair norm to its fair flip.","pairs":[{"left":"\"Boys go first\"","right":"\"Take turns going first\""},{"left":"\"Girls serve, then eat\"","right":"\"Everyone serves and eats together\""},{"left":"\"Sons inherit only\"","right":"\"Daughters and sons inherit\""},{"left":"\"Girls can't cycle\"","right":"\"Anyone can cycle to school\""},{"left":"\"Boys never cry\"","right":"\"Anyone can show feelings\""}]},
  {"id":"ns-953","cat":"good-norm-test","type":"match","persona":"any","source":"good-norm test / reason","relearn":"A caring reason hints pass; a ranking reason hints fail.","hook":"Match the norm to the reason behind it.","pairs":[{"left":"\"Wash hands before food\"","right":"Caring: keeps people well"},{"left":"\"Girls walk behind\"","right":"Ranking: puts a group below"},{"left":"\"Queue at the tap\"","right":"Caring: fair for everyone"},{"left":"\"Boys skip chores\"","right":"Ranking: lets one group off"},{"left":"\"Cover a cough\"","right":"Caring: protects others"}]},
  {"id":"ns-954","cat":"good-norm-test","type":"match","persona":"any","source":"good-norm test / pass-fail words","relearn":"Sort the verdict words by whether a norm passes or fails.","hook":"Match the verdict to whether it's a pass or a fail.","pairs":[{"left":"\"Fair to all\"","right":"A clear pass"},{"left":"\"Ranks a group\"","right":"A clear fail"},{"left":"\"Hurts no one\"","right":"A pass"},{"left":"\"Limits one gender\"","right":"A fail"},{"left":"\"Respects everyone\"","right":"Also a pass"}]},
  {"id":"ns-955","cat":"good-norm-test","type":"match","persona":"Asha","source":"good-norm test / kind question","relearn":"A curious question opens minds; an attack closes them.","hook":"Match the situation to the kind, testing question.","pairs":[{"left":"A custom seems unfair","right":"\"Is this fair to everyone?\""},{"left":"A norm favours one side","right":"\"Would it feel fair if swapped?\""},{"left":"'It's tradition' is the only reason","right":"\"Is the custom itself fair?\""},{"left":"'Everyone does it' is the reason","right":"\"Does common make it fair?\""},{"left":"A norm hurts boys too","right":"\"Is this fair to boys as well?\""}]},
  {"id":"ns-956","cat":"good-norm-test","type":"match","persona":"any","source":"good-norm test / keep-or-question","relearn":"Helpful norms we keep; harmful ones we question.","hook":"Match the norm to: keep it, or question it?","pairs":[{"left":"\"Share with classmates\"","right":"Keep it"},{"left":"\"Daughters need no schooling\"","right":"Question it"},{"left":"\"Greet guests warmly\"","right":"Keep it too"},{"left":"\"Boys mustn't show fear\"","right":"Question it too"},{"left":"\"Pay dowry for a bride\"","right":"Question it: it's harmful"}]},
  {"id":"ns-957","cat":"good-norm-test","type":"spot","persona":"any","source":"good-norm test","relearn":"The norms that rank or limit a group fail the test. Spot them.","hook":"Norms at a family dinner. Spot the 2 that fail the test.","scene":[{"id":"a","text":"Everyone washes hands before eating","trick":false},{"id":"b","text":"Girls are served last, every time","trick":true},{"id":"c","text":"Guests are offered food first","trick":false},{"id":"d","text":"Boys are told to skip the clearing-up","trick":true},{"id":"e","text":"People thank whoever cooked","trick":false}],"why":"Serving girls last and excusing boys from chores rank a group. They fail the test."},
  {"id":"ns-958","cat":"good-norm-test","type":"spot","persona":"Diya","source":"good-norm test / school","relearn":"Norms that gatekeep by gender fail the test. Spot them.","hook":"Playground norms. Spot the 2 that fail the fairness test.","scene":[{"id":"a","text":"Teams are picked by skill","trick":false},{"id":"b","text":"Girls aren't allowed to play football","trick":true},{"id":"c","text":"Everyone gets a turn to bat","trick":false},{"id":"d","text":"Only boys carry the sports kit","trick":true},{"id":"e","text":"Players help up anyone who falls","trick":false}],"why":"Barring girls from football and making only boys carry kit gatekeep by gender. They fail."},
  {"id":"ns-959","cat":"good-norm-test","type":"spot","persona":"any","source":"good-norm test / home","relearn":"Norms that hand all the load to one group fail the test.","hook":"Norms at home. Spot the 2 that fail the test.","scene":[{"id":"a","text":"Everyone makes their own bed","trick":false},{"id":"b","text":"Only the daughter does the dishes","trick":true},{"id":"c","text":"Chores are split for the weekend","trick":false},{"id":"d","text":"Sons are never asked to cook","trick":true},{"id":"e","text":"Each person clears their own plate","trick":false}],"why":"Loading dishes on the daughter and excusing sons from cooking are unfair. They fail the test."},
  {"id":"ns-960","cat":"good-norm-test","type":"spot","persona":"Aarav","source":"good-norm test / boys","relearn":"Norms that box boys in fail the test too. Spot them.","hook":"'Be a man' norms. Spot the 2 that fail the fairness test.","scene":[{"id":"a","text":"Boys can ask for help when stuck","trick":false},{"id":"b","text":"Boys must never show they're scared","trick":true},{"id":"c","text":"Boys are free to enjoy dance","trick":false},{"id":"d","text":"A boy who cries is called weak","trick":true},{"id":"e","text":"Boys can share how they feel","trick":false}],"why":"'Never show fear' and shaming a boy for crying box boys in. They fail the test."},
  {"id":"ns-961","cat":"good-norm-test","type":"spot","persona":"any","source":"good-norm test / festival","relearn":"Festival customs that shut someone out fail the test.","hook":"Festival customs. Spot the 2 that fail the fairness test.","scene":[{"id":"a","text":"The whole family makes the rangoli","trick":false},{"id":"b","text":"Girls can't join while they're bleeding","trick":true},{"id":"c","text":"Sweets are shared with every neighbour","trick":false},{"id":"d","text":"Only sons may light the festival lamp","trick":true},{"id":"e","text":"Kids and elders both pick the songs","trick":false}],"why":"Shutting girls out during periods and barring daughters from the lamp exclude a group. They fail."},
  {"id":"ns-962","cat":"good-norm-test","type":"spot","persona":"any","source":"good-norm test / common-isn't-fair","relearn":"Common doesn't make a norm pass. Spot the 2 that still fail.","hook":"All of these are common. Spot the 2 that fail the test.","scene":[{"id":"a","text":"Most people queue at the clinic","trick":false},{"id":"b","text":"Most homes serve sons bigger portions","trick":true},{"id":"c","text":"Most folks remove shoes indoors","trick":false},{"id":"d","text":"Many say a girl's place is only at home","trick":true},{"id":"e","text":"Most greet a guest with chai","trick":false}],"why":"Bigger portions for sons and 'a girl's place is home' rank a group, common, but they fail."},
  {"id":"ns-963","cat":"good-norm-test","type":"spot","persona":"any","source":"good-norm test / consent","relearn":"Norms that override a person's 'no' fail the test.","hook":"Norms about touching. Spot the 2 that fail the test.","scene":[{"id":"a","text":"You ask before sharing a friend's photo","trick":false},{"id":"b","text":"A child is forced to hug a relative","trick":true},{"id":"c","text":"Tickling stops when they say stop","trick":false},{"id":"d","text":"A girl is told to smile for guests","trick":true},{"id":"e","text":"You check before borrowing a bag","trick":false}],"why":"Forcing a hug and ordering a girl to smile override a person's 'no'. They fail the test."},
  {"id":"ns-964","cat":"good-norm-test","type":"spot","persona":"Rohit","source":"good-norm test / who-decides","relearn":"Norms that let one group decide for all fail the test.","hook":"Who-decides norms. Spot the 2 that fail the fairness test.","scene":[{"id":"a","text":"The family picks the show together","trick":false},{"id":"b","text":"Only the men decide for everyone","trick":true},{"id":"c","text":"Kids get a say in weekend plans","trick":false},{"id":"d","text":"Girls' opinions are waved away","trick":true},{"id":"e","text":"Each person's vote counts the same","trick":false}],"why":"Letting only men decide and waving away girls' views rank a group. They fail the test."},
  {"id":"ns-990","cat":"harmful-norms","type":"sort","hook":"Sort: ranks one gender higher, or treats both the same?","items":[{"id":"a","text":"\"Only sons light the festival lamp\""},{"id":"b","text":"\"Both kids carry the diyas\""},{"id":"c","text":"\"Girls fetch water; boys rest\""},{"id":"d","text":"\"We share the water trips\""},{"id":"e","text":"\"The eldest son's word is final\""},{"id":"f","text":"\"Everyone's idea gets a hearing\""}],"bins":[{"id":"ranks","label":"Ranks a gender higher","valence":"neg"},{"id":"equal","label":"Treats both equally","valence":"pos"}],"key":{"a":"ranks","b":"equal","c":"ranks","d":"equal","e":"ranks","f":"equal"},"relearn":"Norms that rank one gender above another are harmful.","persona":"Diya","source":"harmful norms / ranking"},
  {"id":"ns-991","cat":"harmful-norms","type":"sort","hook":"Sort: a harmful gender norm, or a fair rule?","items":[{"id":"a","text":"\"Girls cover up; boys roam free\""},{"id":"b","text":"\"Everyone wears something comfy\""},{"id":"c","text":"\"Boys stay out late; girls can't\""},{"id":"d","text":"\"Everyone's home by the same time\""},{"id":"e","text":"\"Only daughters serve guests\""},{"id":"f","text":"\"All the kids help with guests\""}],"bins":[{"id":"harm","label":"Harmful gender norm","valence":"neg"},{"id":"fair","label":"Fair for everyone","valence":"pos"}],"key":{"a":"harm","b":"fair","c":"harm","d":"fair","e":"harm","f":"fair"},"relearn":"A rule for one gender only is usually a harmful norm.","persona":"Diya","source":"harmful norms / fairness"},
  {"id":"ns-992","cat":"harmful-norms","type":"sort","hook":"Sort: which of these limits boys, and which limits girls?","items":[{"id":"a","text":"\"Boys can't dance\""},{"id":"b","text":"\"Girls can't fix a cycle\""},{"id":"c","text":"\"Boys mustn't ask for help\""},{"id":"d","text":"\"Girls can't run for class monitor\""},{"id":"e","text":"\"Boys can't help in the kitchen\""},{"id":"f","text":"\"Girls shouldn't speak up in class\""}],"bins":[{"id":"boys","label":"Limits boys","valence":"neg"},{"id":"girls","label":"Limits girls","valence":"neg"}],"key":{"a":"boys","b":"girls","c":"boys","d":"girls","e":"boys","f":"girls"},"relearn":"Harmful gender norms box in both girls and boys.","persona":"any","source":"harmful norms / gender"},
  {"id":"ns-993","cat":"harmful-norms","type":"sort","hook":"Sort: a harmful norm to question, or a kind one to keep?","items":[{"id":"a","text":"\"A girl on her period can't enter the kitchen\""},{"id":"b","text":"\"Wash hands before cooking\""},{"id":"c","text":"\"Widows must wear only white\""},{"id":"d","text":"\"Greet guests warmly\""},{"id":"e","text":"\"Dark-skinned girls are 'less pretty'\""},{"id":"f","text":"\"Share food with whoever's hungry\""}],"bins":[{"id":"harm","label":"Harmful, question it","valence":"neg"},{"id":"keep","label":"Kind, keep it","valence":"pos"}],"key":{"a":"harm","b":"keep","c":"harm","d":"keep","e":"harm","f":"keep"},"relearn":"Norms that shame or limit a group are harmful; kind ones are worth keeping.","persona":"any","source":"harmful norms"},
  {"id":"ns-994","cat":"harmful-norms","type":"sort","hook":"Sort: who does each harmful norm hurt?","items":[{"id":"a","text":"\"Only boys get the bigger glass of milk\""},{"id":"b","text":"\"Boys can't cry at a funeral\""},{"id":"c","text":"\"Girls drop out to mind siblings\""},{"id":"d","text":"\"Boys must pay for everyone, always\""},{"id":"e","text":"\"Girls can't choose their own career\""},{"id":"f","text":"\"Boys who like cooking get teased\""}],"bins":[{"id":"girls","label":"Hurts girls","valence":"neg"},{"id":"boys","label":"Hurts boys","valence":"neg"}],"key":{"a":"girls","b":"boys","c":"girls","d":"boys","e":"girls","f":"boys"},"relearn":"Each harmful norm has a clear group it hurts; gender norms hurt girls and boys both.","persona":"any","source":"harmful norms / who-it-hurts"},
  {"id":"ns-995","cat":"harmful-norms","type":"sort","hook":"Sort: a harmful norm, or just a harmless habit?","items":[{"id":"a","text":"\"Daughters eat after everyone else\""},{"id":"b","text":"\"We eat dinner around 8\""},{"id":"c","text":"\"Boys shouldn't wear pink\""},{"id":"d","text":"\"We light a lamp in the evening\""},{"id":"e","text":"\"Girls can't study science\""},{"id":"f","text":"\"We keep slippers by the door\""}],"bins":[{"id":"harm","label":"Harmful norm","valence":"neg"},{"id":"habit","label":"Harmless habit","valence":"neutral"}],"key":{"a":"harm","b":"habit","c":"harm","d":"habit","e":"harm","f":"habit"},"relearn":"Some norms quietly harm by limiting a group; others are harmless habits that hurt no one.","persona":"any","source":"harmful norms / sorting"},
  {"id":"ns-996","cat":"harmful-norms","type":"sort","hook":"Sort: a harmful norm, or a fair family rule?","items":[{"id":"a","text":"\"Only the son gets sent to a good school\""},{"id":"b","text":"\"Every child finishes their homework\""},{"id":"c","text":"\"Girls hand their pay to brothers\""},{"id":"d","text":"\"Everyone helps clear the table\""},{"id":"e","text":"\"Boys decide, girls just agree\""},{"id":"f","text":"\"We make big choices together\""}],"bins":[{"id":"harm","label":"Harmful norm","valence":"neg"},{"id":"fair","label":"Fair rule","valence":"pos"}],"key":{"a":"harm","b":"fair","c":"harm","d":"fair","e":"harm","f":"fair"},"relearn":"Rules that favour one gender harm; rules that ask the same of everyone are fair.","persona":"Diya","source":"harmful norms / family"},
  {"id":"ns-997","cat":"harmful-norms","type":"sort","hook":"Sort: a hidden harmful norm, or a true compliment?","items":[{"id":"a","text":"\"You cook well, you'll be a good wife\""},{"id":"b","text":"\"You explained that clearly\""},{"id":"c","text":"\"Brave boy, you didn't cry\""},{"id":"d","text":"\"You worked hard, it shows\""},{"id":"e","text":"\"Such a fair-skinned, lucky girl\""},{"id":"f","text":"\"You were kind to share\""}],"bins":[{"id":"norm","label":"Hidden harmful norm","valence":"neg"},{"id":"real","label":"A true compliment","valence":"pos"}],"key":{"a":"norm","b":"real","c":"norm","d":"real","e":"norm","f":"real"},"relearn":"Some 'compliments' carry a harmful norm; real praise is about effort, not gender.","persona":"any","source":"harmful norms / hidden"},
  {"id":"ns-998","cat":"harmful-norms","type":"sort","hook":"Sort: does this norm pass the fairness test, or fail because it limits a group?","items":[{"id":"a","text":"\"Take turns batting in gully cricket\""},{"id":"b","text":"\"Girls field, boys always bat\""},{"id":"c","text":"\"Anyone can be team captain\""},{"id":"d","text":"\"Boys can't join the dance team\""},{"id":"e","text":"\"Share the one bat fairly\""},{"id":"f","text":"\"Girls can't play after lunch\""}],"bins":[{"id":"pass","label":"Fair, passes","valence":"pos"},{"id":"fail","label":"Limits a group, fails","valence":"neg"}],"key":{"a":"pass","b":"fail","c":"pass","d":"fail","e":"pass","f":"fail"},"relearn":"Norms that limit play by gender fail the fairness test; sharing rules pass.","persona":"any","source":"harmful norms / play"},
  {"id":"ns-999","cat":"harmful-norms","type":"sort","hook":"Sort: a harmful norm about boys, or a fair expectation for any kid?","items":[{"id":"a","text":"\"A real boy never shows fear\""},{"id":"b","text":"\"Everyone tidies their own mess\""},{"id":"c","text":"\"Boys must win every fight\""},{"id":"d","text":"\"Be honest about how you feel\""},{"id":"e","text":"\"Boys mustn't play with dolls\""},{"id":"f","text":"\"Ask for help when stuck\""}],"bins":[{"id":"harm","label":"Harmful norm for boys","valence":"neg"},{"id":"fair","label":"Fair for any kid","valence":"pos"}],"key":{"a":"harm","b":"fair","c":"harm","d":"fair","e":"harm","f":"fair"},"relearn":"The 'tough, fearless, no help' norm boxes boys in; honesty and help are fair for any kid.","persona":"Aarav","source":"harmful norms / masculinity"},
  {"id":"ns-1000","cat":"harmful-norms","type":"sort","hook":"Sort: a chore norm that harms by gender, or a fair one?","items":[{"id":"a","text":"\"Only Ma and the girls cook\""},{"id":"b","text":"\"Whoever's free starts dinner\""},{"id":"c","text":"\"Papa never enters the kitchen\""},{"id":"d","text":"\"Everyone learns to cook\""},{"id":"e","text":"\"Boys don't wash their plates\""},{"id":"f","text":"\"We each clean up our own\""}],"bins":[{"id":"harm","label":"Harmful, splits by gender","valence":"neg"},{"id":"fair","label":"Fair, shared by all","valence":"pos"}],"key":{"a":"harm","b":"fair","c":"harm","d":"fair","e":"harm","f":"fair"},"relearn":"Splitting all housework by gender is a harmful norm; sharing it fairly helps all.","persona":"Rohit","source":"harmful norms / housework"},
  {"id":"ns-1001","cat":"harmful-norms","type":"sort","hook":"Sort: ranks people by birth or skin, or respects everyone?","items":[{"id":"a","text":"\"Don't share a glass with 'them'\""},{"id":"b","text":"\"All drink from the same tap\""},{"id":"c","text":"\"Fair skin gets a better match\""},{"id":"d","text":"\"Respect every guest\""},{"id":"e","text":"\"Some families are 'beneath' us\""},{"id":"f","text":"\"All are equal in dignity\""}],"bins":[{"id":"harm","label":"Ranks people, harmful","valence":"neg"},{"id":"respect","label":"Respects everyone","valence":"pos"}],"key":{"a":"harm","b":"respect","c":"harm","d":"respect","e":"harm","f":"respect"},"relearn":"Norms that rank people by birth or skin are harmful; all are equal in dignity.","persona":"any","source":"harmful norms / dignity"},
  {"id":"ns-1002","cat":"harmful-norms","type":"sort","hook":"Sort: a harmful wedding norm to flip, or a fair one to keep?","items":[{"id":"a","text":"\"Bride's family must give a car\""},{"id":"b","text":"\"Both families share costs\""},{"id":"c","text":"\"A widow can't attend\""},{"id":"d","text":"\"Everyone's welcome to celebrate\""},{"id":"e","text":"\"Only the groom's wishes matter\""},{"id":"f","text":"\"Both partners are asked\""}],"bins":[{"id":"harm","label":"Harmful, flip it","valence":"neg"},{"id":"keep","label":"Fair, keep it","valence":"pos"}],"key":{"a":"harm","b":"keep","c":"harm","d":"keep","e":"harm","f":"keep"},"relearn":"Dowry and shutting people out are harmful norms; sharing costs fairly is not.","persona":"Asha","source":"harmful norms / weddings"},
  {"id":"ns-1003","cat":"harmful-norms","type":"strike-rewrite","hook":"\"Fair-skinned girls are prettier and easier to marry off.\"","myth":{"un":"A girl's worth and future depend on having fair skin.","re":"Skin colour says nothing about a person's worth or future.","why":"Ranking girls by skin tone is a harmful norm, not a fact."},"relearn":"Judging girls by skin colour is a harmful norm; worth isn't a shade.","persona":"any","source":"harmful norms / colourism"},
  {"id":"ns-1004","cat":"harmful-norms","type":"strike-rewrite","hook":"\"A girl should learn to cook because that's her real job.\"","myth":{"un":"A girl's main job is to cook and keep house.","re":"Cooking is a skill for anyone; a girl can choose her own path.","why":"Tying a girl's future to the kitchen limits her unfairly."},"relearn":"Cooking is a life skill for all; a girl's future is hers to choose.","persona":"Diya","source":"harmful norms / roles"},
  {"id":"ns-1005","cat":"harmful-norms","type":"strike-rewrite","hook":"\"Men don't do housework; that's women's work.\"","myth":{"un":"Housework is women's work and not for men.","re":"Housework is everyone's work; men can cook, clean and care too.","why":"Loading all chores on women is a harmful, tiring norm."},"relearn":"Housework belongs to everyone; the 'women's work' norm harms women.","persona":"Rohit","source":"harmful norms / housework"},
  {"id":"ns-1006","cat":"harmful-norms","type":"strike-rewrite","hook":"\"A boy who shows fear or cries is weak.\"","myth":{"un":"A boy who feels fear or cries is weak.","re":"Feeling and showing emotions is human, not weak.","why":"The 'never show feelings' norm hurts boys' wellbeing."},"relearn":"Showing feelings isn't weakness; the 'be tough' norm harms boys.","persona":"Aarav","source":"harmful norms / masculinity"},
  {"id":"ns-1007","cat":"harmful-norms","type":"strike-rewrite","hook":"\"Why educate a daughter? She'll just go to another house.\"","myth":{"un":"Educating a daughter is wasted since she'll marry into another family.","re":"Every girl deserves a full education and her own future.","why":"'She'll marry anyway' is a harmful norm that steals her chances."},"relearn":"A daughter's education is hers and worth it; 'she'll marry anyway' harms her.","persona":"Diya","source":"harmful norms / education"},
  {"id":"ns-1008","cat":"harmful-norms","type":"strike-rewrite","hook":"\"A girl on her period shouldn't touch the pickle or it spoils.\"","myth":{"un":"A girl on her period spoils food just by touching it.","re":"Periods are normal and healthy; they don't spoil food.","why":"This stigma norm shames girls for a natural process."},"relearn":"Periods don't spoil food; period-stigma norms wrongly shame girls.","persona":"Diya","source":"harmful norms / menstruation"},
  {"id":"ns-1009","cat":"harmful-norms","type":"strike-rewrite","hook":"\"The bride's family must give gold and cash, or it's an insult.\"","myth":{"un":"A bride's family is expected to give dowry to honour the marriage.","re":"Dowry is harmful and is against the law in India.","why":"Treating a girl as a cost to be paid for harms her deeply."},"relearn":"Dowry is a harmful norm and is against the law in India.","persona":"Asha","source":"harmful norms / dowry"},
  {"id":"ns-1010","cat":"harmful-norms","type":"strike-rewrite","hook":"\"Some families are 'lower' and shouldn't share our well.\"","myth":{"un":"It's fine to keep some families away from our well or temple.","re":"Everyone is equal in dignity; untouchability is wrong and illegal.","why":"Treating people as 'lower' caused deep, unfair harm."},"relearn":"Treating anyone as 'untouchable' is a harmful norm and against the law.","persona":"any","source":"harmful norms / untouchability"},
  {"id":"ns-1011","cat":"harmful-norms","type":"strike-rewrite","hook":"\"A son will care for us in old age; a daughter is for another home.\"","myth":{"un":"Only a son will look after parents in old age.","re":"Daughters and sons can both love and care for their parents.","why":"Son-preference is a harmful norm that wrongs daughters."},"relearn":"Both daughters and sons can care for parents; son-preference harms girls.","persona":"any","source":"harmful norms / son preference"},
  {"id":"ns-1012","cat":"harmful-norms","type":"strike-rewrite","hook":"\"A widow shouldn't wear bright colours or join celebrations.\"","myth":{"un":"A widow must stay plain and apart from happy events.","re":"A widow is a full person who can live, dress and celebrate freely.","why":"Shutting widows out is a harmful old norm, not a kindness."},"relearn":"Shutting widows out is a harmful norm; a widow can live fully.","persona":"any","source":"harmful norms / widows"},
  {"id":"ns-1013","cat":"harmful-norms","type":"strike-rewrite","hook":"\"Girls shouldn't laugh loudly or speak up; it's not ladylike.\"","myth":{"un":"A good girl stays quiet and doesn't speak up.","re":"Every girl can speak, laugh and share her ideas freely.","why":"Silencing girls is a harmful norm that shrinks their voice."},"relearn":"Girls can speak and laugh freely; the 'stay quiet' norm harms them.","persona":"Diya","source":"harmful norms / voice"},
  {"id":"ns-1014","cat":"harmful-norms","type":"strike-rewrite","hook":"\"Boys must be the family's earners; caring jobs aren't for them.\"","myth":{"un":"A boy must grow up to earn; caring work isn't for him.","re":"A boy can be a carer, cook, nurse or anything he chooses.","why":"The 'only-provider' norm limits boys' futures too."},"relearn":"Boys can choose caring work too; the 'only-provider' norm limits them.","persona":"Aarav","source":"harmful norms / masculinity"},
  {"id":"ns-1015","cat":"harmful-norms","type":"strike-rewrite","hook":"\"Let the boys finish eating; girls take whatever's left.\"","myth":{"un":"Boys should eat first and best; girls take the leftovers.","re":"Every child deserves an equal, full meal.","why":"Feeding boys first is a harmful norm that ranks girls below."},"relearn":"Every child deserves a full meal; serving boys first harms girls.","persona":"Diya","source":"harmful norms / food"},
  {"id":"ns-1016","cat":"harmful-norms","type":"strike-rewrite","hook":"\"A girl out alone after dark is 'asking for trouble'.\"","myth":{"un":"If something happens to a girl out at night, it's her own fault.","re":"No one is to blame for being harmed; safety is everyone's job.","why":"Blaming girls for harm is a harmful norm that lets it continue."},"relearn":"Being out isn't a girl's 'fault'; blaming her is a harmful norm.","persona":"Asha","source":"harmful norms / blame"},
  {"id":"ns-1017","cat":"harmful-norms","type":"strike-rewrite","hook":"\"Boys must be braver and stronger than any girl, always.\"","myth":{"un":"A boy must always be stronger and braver than girls.","re":"Strength and courage aren't a contest between genders.","why":"This norm pressures boys and puts girls down at once."},"relearn":"Strength isn't a gender contest; the 'beat the girls' norm harms both.","persona":"Aarav","source":"harmful norms / masculinity"},
  {"id":"ns-1018","cat":"harmful-norms","type":"strike-rewrite","hook":"\"A girl's place is at home; she doesn't need to travel or work outside.\"","myth":{"un":"A girl belongs at home and shouldn't work or travel outside.","re":"A girl can work, travel and lead, just like anyone.","why":"Confining girls to the home is a harmful, limiting norm."},"relearn":"A girl can work and travel; confining her to home is a harmful norm.","persona":"Diya","source":"harmful norms / roles"},
  {"id":"ns-1019","cat":"harmful-norms","type":"strike-rewrite","hook":"\"Don't praise a boy for helping at home; it'll make him soft.\"","myth":{"un":"A boy who helps with cooking or cleaning becomes 'soft'.","re":"Helping at home makes a boy capable and kind, not weak.","why":"Mocking boys who help is a harmful norm that keeps chores unfair."},"relearn":"Helping at home makes boys capable; mocking them is a harmful norm.","persona":"Rohit","source":"harmful norms / housework"},
  {"id":"ns-1020","cat":"harmful-norms","type":"strike-rewrite","hook":"\"Girls don't need to play sport; it's not for them.\"","myth":{"un":"Sport is for boys; girls don't really need it.","re":"Girls can play and excel at any sport they love.","why":"Keeping girls off the field is a harmful, limiting norm."},"relearn":"Girls can play any sport; the 'not for girls' norm limits them.","persona":"Diya","source":"harmful norms / sport"},
  {"id":"ns-1021","cat":"harmful-norms","type":"strike-rewrite","hook":"\"He's a boy, so of course he gets the bigger share.\"","myth":{"un":"A boy should naturally get the bigger or better share.","re":"Children deserve equal shares, whatever their gender.","why":"Giving boys more by default is a harmful, unfair norm."},"relearn":"Kids deserve equal shares; favouring boys by default is a harmful norm.","persona":"any","source":"harmful norms / favouritism"},
  {"id":"ns-1022","cat":"harmful-norms","type":"spot","hook":"At a family lunch. Spot the two harmful norms.","scene":[{"id":"a","text":"The boys are served first and given the most","trick":true},{"id":"b","text":"There is rice, dal and sabzi on the table","trick":false},{"id":"c","text":"The girls eat last, whatever is left over","trick":true},{"id":"d","text":"Everyone washes hands before eating","trick":false},{"id":"e","text":"A jug of water sits in the middle","trick":false}],"why":"Serving boys first and best while girls eat last is a harmful norm that ranks girls below.","relearn":"Serving food by gender rank is a harmful, unfair norm.","persona":"Diya","source":"harmful norms / food"},
  {"id":"ns-1023","cat":"harmful-norms","type":"spot","hook":"At a family gathering. Spot the two harmful norms about boys.","scene":[{"id":"a","text":"\"Stop crying, be a man about it\"","trick":true},{"id":"b","text":"Tea and snacks are passed around","trick":false},{"id":"c","text":"\"Real boys don't get scared like that\"","trick":true},{"id":"d","text":"Cousins are playing carrom in the corner","trick":false},{"id":"e","text":"An uncle asks about school results","trick":false}],"why":"Shaming a boy for crying or fear is a harmful norm that hurts boys' feelings.","relearn":"Pressuring boys to never cry or fear is a harmful norm.","persona":"Aarav","source":"harmful norms / masculinity"},
  {"id":"ns-1024","cat":"harmful-norms","type":"spot","hook":"A TV serial scene. Spot the two harmful norms.","scene":[{"id":"a","text":"The daughter-in-law does every chore alone","trick":true},{"id":"b","text":"The family sits down to dinner","trick":false},{"id":"c","text":"The men are praised just for showing up","trick":true},{"id":"d","text":"There is festive music in the background","trick":false},{"id":"e","text":"A grandmother tells a story","trick":false}],"why":"Showing women doing all the work while men are praised for little is a harmful norm.","relearn":"Media often normalises women doing all household labour; spot it.","persona":"any","source":"harmful norms / media"},
  {"id":"ns-1025","cat":"harmful-norms","type":"spot","hook":"A school sports day. Spot the two harmful norms.","scene":[{"id":"a","text":"\"Girls can only watch; boys play the matches\"","trick":true},{"id":"b","text":"Students line up for the races","trick":false},{"id":"c","text":"\"A girl who runs fast is 'too boyish'\"","trick":true},{"id":"d","text":"Teachers hand out water bottles","trick":false},{"id":"e","text":"There is a whistle and a starting line","trick":false}],"why":"Benching girls and mocking fast girls are harmful norms that limit them on the field.","relearn":"Keeping girls off the field by gender is a harmful, limiting norm.","persona":"Diya","source":"harmful norms / sport"},
  {"id":"ns-1026","cat":"harmful-norms","type":"spot","hook":"A wedding being planned. Spot the two harmful norms.","scene":[{"id":"a","text":"\"The bride's family must give a scooter as dowry\"","trick":true},{"id":"b","text":"The families pick a date together","trick":false},{"id":"c","text":"\"Don't invite her, she's a widow\"","trick":true},{"id":"d","text":"There is a guest list being made","trick":false},{"id":"e","text":"Sweets are being ordered for guests","trick":false}],"why":"Demanding dowry and shutting out a widow are harmful norms; one is even against the law.","relearn":"Dowry and excluding widows are harmful wedding norms.","persona":"Asha","source":"harmful norms / weddings"},
  {"id":"ns-1027","cat":"harmful-norms","type":"spot","hook":"A relative visiting a newborn. Spot the two harmful norms.","scene":[{"id":"a","text":"\"Oh, a girl? Better luck next time\"","trick":true},{"id":"b","text":"The baby is wrapped in a soft blanket","trick":false},{"id":"c","text":"\"At least pray the next one's a boy\"","trick":true},{"id":"d","text":"Neighbours bring sweets to celebrate","trick":false},{"id":"e","text":"The baby is sleeping peacefully","trick":false}],"why":"Treating a girl's birth as bad luck is son-preference, a harmful norm that wrongs daughters.","relearn":"Son-preference is a harmful norm; daughters and sons are equally valuable.","persona":"any","source":"harmful norms / son preference"},
  {"id":"ns-1028","cat":"harmful-norms","type":"spot","hook":"In a classroom. Spot the two harmful norms.","scene":[{"id":"a","text":"\"Let the boys answer the maths question\"","trick":true},{"id":"b","text":"There is a blackboard with sums on it","trick":false},{"id":"c","text":"\"Girls, you handle the decorations instead\"","trick":true},{"id":"d","text":"Students are sitting at their desks","trick":false},{"id":"e","text":"The bell rings for the next period","trick":false}],"why":"Steering boys to maths and girls to decorating is a harmful norm that limits both.","relearn":"Assigning tasks by gender is a harmful norm that boxes kids in.","persona":"any","source":"harmful norms / school"},
  {"id":"ns-1029","cat":"harmful-norms","type":"spot","hook":"At a village tap. Spot the two harmful norms.","scene":[{"id":"a","text":"\"Those families must wait till the end\"","trick":true},{"id":"b","text":"People fill their pots with water","trick":false},{"id":"c","text":"\"Don't let them use the same vessel\"","trick":true},{"id":"d","text":"There is a queue forming at the tap","trick":false},{"id":"e","text":"The morning sun is bright overhead","trick":false}],"why":"Making some families wait or keeping vessels apart is untouchability, a harmful and illegal norm.","relearn":"Treating people as 'lower' is a harmful norm and against the law.","persona":"any","source":"harmful norms / untouchability"},
  {"id":"ns-1030","cat":"harmful-norms","type":"spot","hook":"At a relative's house. Spot the two harmful norms.","scene":[{"id":"a","text":"\"Girls don't go up to the terrace alone\"","trick":true},{"id":"b","text":"There are plants on the balcony","trick":false},{"id":"c","text":"\"But the boys can roam wherever they like\"","trick":true},{"id":"d","text":"Cups of tea are on a tray","trick":false},{"id":"e","text":"A fan is whirring in the room","trick":false}],"why":"Letting boys roam free while girls are penned in is a harmful, unequal norm.","relearn":"A rule that limits only girls' freedom is a harmful gender norm.","persona":"Diya","source":"harmful norms / freedom"},
  {"id":"ns-1031","cat":"harmful-norms","type":"spot","hook":"Scrolling a video app. Spot the two harmful norms.","scene":[{"id":"a","text":"A clip says \"a real man never shows emotion\"","trick":true},{"id":"b","text":"A cooking video shows a simple recipe","trick":false},{"id":"c","text":"An ad hints fair skin gets you the job","trick":true},{"id":"d","text":"A puppy video has lots of likes","trick":false},{"id":"e","text":"A song plays over a travel clip","trick":false}],"why":"'Real men hide emotion' and 'fair skin wins' are harmful norms that media keeps repeating.","relearn":"Media repeats harmful norms; you can spot and question them.","persona":"Aarav","source":"harmful norms / media"},
  {"id":"ns-1032","cat":"harmful-norms","type":"match","hook":"Match the harmful norm to who it hurts most.","pairs":[{"left":"\"Girls study less, marry early\"","right":"A girl's future"},{"left":"\"Boys must never cry\"","right":"A boy's feelings"},{"left":"\"Dowry is expected\"","right":"A bride's family"},{"left":"\"Widows stay apart\"","right":"A widow"},{"left":"\"Some are 'untouchable'\"","right":"Whole communities"}],"relearn":"Each harmful norm has a clear group it hurts.","persona":"any","source":"harmful norms / who-it-hurts"},
  {"id":"ns-1033","cat":"harmful-norms","type":"match","hook":"Match the harmful norm to the fair version that replaces it.","pairs":[{"left":"\"Only sons get schooling\"","right":"Every child goes to school"},{"left":"\"Girls serve, eat last\"","right":"Everyone shares the meal"},{"left":"\"Boys can't show feelings\"","right":"Anyone can feel and share"},{"left":"\"Men avoid housework\"","right":"All share the chores"},{"left":"\"Fair skin is 'better'\"","right":"Every shade is fine"}],"relearn":"Each harmful norm can be flipped into a fair one that respects everyone.","persona":"any","source":"harmful norms / flips"},
  {"id":"ns-1034","cat":"harmful-norms","type":"match","hook":"Match each harmful norm to who it boxes in.","pairs":[{"left":"\"Be a tough provider, never cry\"","right":"A boy's feelings"},{"left":"\"Stay home, don't speak up\"","right":"A girl's voice"},{"left":"\"Win every fight or you're soft\"","right":"Boys under pressure"},{"left":"\"Cook and serve, don't study\"","right":"A girl's schooling"},{"left":"\"Pay for everyone, show no fear\"","right":"Boys as 'providers'"}],"relearn":"Harmful gender norms box in both girls and boys.","persona":"any","source":"harmful norms / gender"},
  {"id":"ns-1035","cat":"harmful-norms","type":"match","hook":"Match the harmful norm to why it's unfair.","pairs":[{"left":"\"Girls eat last\"","right":"Ranks girls below boys"},{"left":"\"Boys never ask for help\"","right":"Bottles up boys' troubles"},{"left":"\"Dowry must be paid\"","right":"Treats a girl as a cost"},{"left":"\"Don't touch 'those' people\"","right":"Denies equal dignity"},{"left":"\"Girls can't go out\"","right":"Limits a girl's freedom"}],"relearn":"Harmful norms are unfair because they rank, limit or shame a group.","persona":"any","source":"harmful norms / why-unfair"},
  {"id":"ns-1036","cat":"harmful-norms","type":"match","hook":"Match each harmful saying to the truth that answers it.","pairs":[{"left":"\"She'll marry anyway\"","right":"Her education is still hers"},{"left":"\"Boys don't cry\"","right":"Feelings are for everyone"},{"left":"\"A daughter is a burden\"","right":"Daughters are equally valued"},{"left":"\"It's tradition\"","right":"Test each one for fairness"},{"left":"\"Log kya kahenge\"","right":"You can still choose fair"}],"relearn":"Every harmful saying has a fair truth that answers it.","persona":"any","source":"harmful norms / answers"},
  {"id":"ns-1037","cat":"harmful-norms","type":"match","hook":"Match the place to the harmful norm you might spot there.","pairs":[{"left":"At the dinner table","right":"Girls served last"},{"left":"At a wedding","right":"Dowry demanded"},{"left":"On the playground","right":"Girls benched, boys play"},{"left":"At the village tap","right":"Some made to wait at the end"},{"left":"On a TV serial","right":"Women do all the chores"}],"relearn":"Harmful norms show up in everyday places; spotting them is the first step.","persona":"any","source":"harmful norms / spotting"},
  {"id":"ns-1038","cat":"harmful-norms","type":"match","hook":"Match the harmful norm to the kind, fair belief that replaces it.","pairs":[{"left":"\"Sons matter more\"","right":"Daughters and sons are equal"},{"left":"\"Periods are impure\"","right":"Periods are normal and healthy"},{"left":"\"Widows are unlucky\"","right":"A widow can live fully"},{"left":"\"Fair skin is best\"","right":"Worth isn't a skin shade"},{"left":"\"Some are 'lower'\"","right":"Everyone is equal in dignity"}],"relearn":"Each harmful belief can be replaced with a kind, fair one.","persona":"any","source":"harmful norms / beliefs"},
  {"id":"ns-1039","cat":"harmful-norms","type":"branch","hook":"Diya's pocket money is cut so her brother gets extra 'because he's a boy'.","options":[{"text":"Ask calmly why the share isn't equal for both","consequence":"The unfair gender norm gets named out loud.","outcome":"brave","best":true},{"text":"Say nothing and feel it's just normal","consequence":"A respectful question can expose an unfair norm."}],"debrief":"Giving boys more by default is a harmful norm you can question kindly.","relearn":"You can respectfully question a norm that favours one gender.","persona":"Diya","source":"harmful norms / fairness"},
  {"id":"ns-1040","cat":"harmful-norms","type":"branch","hook":"Aarav is told to 'man up' and stop crying after a scary fall.","options":[{"text":"Let himself feel it and tell someone he trusts","consequence":"He gets comfort and the 'never cry' norm loosens.","outcome":"honest","best":true},{"text":"Bottle it all up to look tough","consequence":"Hiding every feeling to seem tough is the harmful norm hurting boys."}],"debrief":"Boys can feel and share; 'man up and never cry' is a harmful norm.","relearn":"Boys can have feelings and ask for help; the 'be tough' norm harms them.","persona":"Aarav","source":"harmful norms / masculinity"},
  {"id":"ns-1041","cat":"harmful-norms","type":"branch","hook":"At dinner, the girls are told to wait while the boys are served first.","options":[{"text":"Suggest everyone is served together, fairly","consequence":"The 'boys first' ranking gets gently challenged.","outcome":"fair","best":true},{"text":"Accept it because that's how it's always been","consequence":"'That's how it's always been' keeps an unfair norm alive."}],"debrief":"Serving by gender rank is a harmful norm a kind suggestion can shift.","relearn":"You can propose serving everyone fairly instead of by gender.","persona":"Diya","source":"harmful norms / food"},
  {"id":"ns-1042","cat":"harmful-norms","type":"branch","hook":"A friend says a classmate 'can't sit with us, his family is lower'.","options":[{"text":"Say everyone's equal and invite the classmate over","consequence":"You break a harmful, unjust norm in the moment.","outcome":"ally","best":true},{"text":"Go along so your friend isn't upset","consequence":"Going along quietly lets a harmful, unfair norm carry on."}],"debrief":"Treating anyone as 'lower' is a harmful norm; everyone is equal in dignity.","relearn":"You can refuse a norm that ranks people by birth or family.","persona":"any","source":"harmful norms / dignity"},
  {"id":"ns-1043","cat":"harmful-norms","type":"branch","hook":"Relatives plan to pull a cousin out of school to marry her young.","options":[{"text":"Tell a trusted adult and ask if she can keep studying","consequence":"You raise it with someone who can help.","outcome":"caring","best":true},{"text":"Decide it's not your business","consequence":"Staying silent lets a harmful norm decide her future."}],"debrief":"Cutting a girl's schooling to marry her young is a harmful norm worth questioning.","relearn":"You can tell a trusted adult when a harmful norm threatens a girl's future.","persona":"Asha","source":"harmful norms / education"},
  {"id":"ns-1044","cat":"harmful-norms","type":"branch","hook":"Aarav's cousins tease a boy for joining the dance group instead of cricket.","options":[{"text":"Say anyone can dance and cheer the boy on","consequence":"You flip a harmful 'that's not for boys' norm.","outcome":"ally","best":true},{"text":"Join the teasing to fit in","consequence":"Mocking a boy for his choice keeps a harmful norm going."}],"debrief":"'That activity isn't for boys' is a harmful norm you can refuse.","relearn":"You can refuse norms that gatekeep activities by gender.","persona":"Aarav","source":"harmful norms / inclusion"},
  {"id":"ns-1045","cat":"harmful-norms","type":"reflect","hook":"Lensy: a 'harmful norm' is one that limits or ranks a group, like 'girls can't' or 'boys must'. Spot what they share?","prompt":"What do you think?","options":["They limit a group","They're unfair","They box people in"],"affirm":"Harmful norms limit or rank a group; that's how you spot them.","relearn":"Harmful norms limit or rank a group by gender or birth.","persona":"any","source":"harmful norms / definition"},
  {"id":"ns-1046","cat":"harmful-norms","type":"reflect","hook":"Lensy: which kind of harmful norm do you notice most around you?","prompt":"Pick one.","options":["'Girls can't' ones","'Boys must' ones","'Some are lower' ones"],"affirm":"Naming the harmful norms around you is the first step to questioning them.","relearn":"You can notice and name the harmful norms in your own surroundings.","persona":"any","source":"harmful norms / noticing"},
  {"id":"ns-1047","cat":"harmful-norms","type":"reflect","hook":"Lensy: a harmful norm can hurt the very person it seems to 'favour' too. Like boys pushed to never cry?","prompt":"What do you think?","options":["Yes, it hurts boys too","Both get boxed in","Hadn't thought of it"],"affirm":"Harmful gender norms box in both sides, even the one they seem to favour.","relearn":"Harmful gender norms box in both girls and boys.","persona":"Aarav","source":"harmful norms / both-sides"},
  {"id":"ns-1048","cat":"harmful-norms","type":"reflect","hook":"Lensy: Diya gets served last at every meal. How might that feel, day after day?","prompt":"What do you think?","options":["Unfair","Like she counts less","Tiring"],"affirm":"Naming how a harmful norm feels helps you see why it's worth changing.","relearn":"Harmful norms have a real, daily cost for the people they limit.","persona":"Diya","source":"harmful norms / empathy"},
  {"id":"ns-1049","cat":"harmful-norms","type":"reflect","hook":"Lensy: 'It's our tradition' is sometimes used to wave off a harmful norm. Does that make it fair?","prompt":"What do you think?","options":["No","Test it anyway","Tradition isn't proof"],"affirm":"Calling a norm 'tradition' doesn't make it fair; you can test it kindly.","relearn":"'It's tradition' doesn't make a harmful norm fair.","persona":"any","source":"harmful norms / tradition"},
  {"id":"ns-1050","cat":"harmful-norms","type":"reflect","hook":"Lensy: which harmful norm would you most love to see disappear?","prompt":"Pick one.","options":["Girls served last","Boys can't cry","Dowry"],"affirm":"Picturing a harmful norm gone is the start of helping it change.","relearn":"Imagining a harmful norm gone is a first step toward changing it.","persona":"any","source":"harmful norms / vision"},
  {"id":"ns-1051","cat":"harmful-norms","type":"reflect","hook":"Lensy: a harmful norm often hides behind 'that's just how it is'. Worth a second look?","prompt":"What do you think?","options":["Yes","Always look closer","Don't just accept it"],"affirm":"'That's just how it is' is often where a harmful norm hides; look closer.","relearn":"Harmful norms hide behind 'that's just how it is'; look closer.","persona":"any","source":"harmful norms / questioning"},
  {"id":"ns-1052","cat":"harmful-norms","type":"reflect","hook":"Lensy: spotting a harmful norm isn't blaming a person, it's noticing an unfair rule. See the difference?","prompt":"What do you think?","options":["Yes","Norm, not the person","That helps"],"affirm":"You can love people and still notice and question the harmful norm they follow.","relearn":"Spotting a harmful norm means examining the rule, not attacking the person.","persona":"any","source":"harmful norms / norm-not-person"},
  {"id":"ns-1053","cat":"harmful-norms","type":"role-play","hook":"A relative says girls in the family don't go to college 'because of what people will say'.","setup":"Answer kindly but firmly. Say:","yourLine":[{"text":"\"I'd love to study further, can we figure it out together?\"","best":true},{"text":"\"Fine, I'll just stay home then.\""}],"relearn":"You can stand up for a girl's education kindly, without giving up.","persona":"Diya","source":"harmful norms / education"},
  {"id":"ns-1054","cat":"harmful-norms","type":"role-play","hook":"An uncle tells Aarav 'boys don't help in the kitchen, go sit with the men'.","setup":"Reply warmly. Say:","yourLine":[{"text":"\"I actually like helping, cooking is a good skill.\"","best":true},{"text":"\"Okay, I'll just go sit, sorry.\""}],"relearn":"Boys can help in the kitchen; you can say so warmly.","persona":"Aarav","source":"harmful norms / housework"},
  {"id":"ns-1055","cat":"harmful-norms","type":"role-play","hook":"Someone says a friend's family 'shouldn't share our plates because of their caste'.","setup":"Speak up gently. Say:","yourLine":[{"text":"\"Everyone's equal, na, my friend eats with us.\"","best":true},{"text":"\"Hmm, okay, whatever you say.\""}],"relearn":"You can gently stand for equal dignity against an unfair norm.","persona":"any","source":"harmful norms / dignity"},
  {"id":"ns-1056","cat":"harmful-norms","type":"role-play","hook":"A cousin teases that crying makes Aarav 'less of a man'.","setup":"Answer steadily. Say:","yourLine":[{"text":"\"Feeling things is human, it doesn't make me weak.\"","best":true},{"text":"\"You're right, I shouldn't have cried.\""}],"relearn":"Showing feelings isn't weakness; you can say that calmly.","persona":"Aarav","source":"harmful norms / masculinity"},
  {"id":"ns-1057","cat":"harmful-norms","type":"role-play","hook":"Diya is told she can't take part in a festival event during her period.","setup":"Respond gently but clearly. Say:","yourLine":[{"text":"\"Periods are normal, I'd still like to join in.\"","best":true},{"text":"\"Okay, I'll just sit out and hide.\""}],"relearn":"Periods are normal; you can ask to be included, kindly.","persona":"Diya","source":"harmful norms / menstruation"},
  {"id":"ns-1058","cat":"harmful-norms","type":"role-play","hook":"A relative jokes that a baby girl is 'less lucky' than a baby boy would be.","setup":"Reply warmly. Say:","yourLine":[{"text":"\"A daughter's just as wonderful, we're lucky either way.\"","best":true},{"text":"\"Yeah, maybe next time it'll be a boy.\""}],"relearn":"Daughters and sons are equally valuable; you can say so warmly.","persona":"any","source":"harmful norms / son preference"},
  {"id":"ns-1059","cat":"harmful-norms","type":"role-play","hook":"At a match, boys say girls 'can only watch, not play'.","setup":"Stand your ground kindly. Say:","yourLine":[{"text":"\"We can all play, give us a turn too.\"","best":true},{"text":"\"Okay, we'll just watch from here.\""}],"relearn":"Girls can play too; you can ask for a fair turn.","persona":"Diya","source":"harmful norms / sport"},
  {"id":"ns-1060","cat":"harmful-norms","type":"role-play","hook":"A relative hints that the bride's family 'should give a good gift' as dowry.","setup":"Reply respectfully but firmly. Say:","yourLine":[{"text":"\"Dowry isn't right, and it's against the law, na.\"","best":true},{"text":"\"I suppose we'll have to arrange something.\""}],"relearn":"Dowry is harmful and against the law; you can say so respectfully.","persona":"Asha","source":"harmful norms / dowry"},
  {"id":"ns-1420","cat":"harmful-norms","type":"sort","hook":"Sort: does this norm harm someone?","items":[{"id":"a","text":"\"Girls shouldn't go out after dark\""},{"id":"b","text":"\"Boys must never cry\""},{"id":"c","text":"\"Be kind to guests\""},{"id":"d","text":"\"Sons matter more than daughters\""},{"id":"e","text":"\"Wash hands before eating\""},{"id":"f","text":"\"Girls eat last, whatever's left\""}],"bins":[{"id":"harms","label":"Harms someone","valence":"neg"},{"id":"helps","label":"Helps everyone","valence":"pos"}],"key":{"a":"harms","b":"harms","c":"helps","d":"harms","e":"helps","f":"harms"},"relearn":"Norms that limit or rank a group by gender harm people.","persona":"Diya","source":"harmful norms"},
  {"id":"ns-1421","cat":"harmful-norms","type":"sort","hook":"Sort: who does each norm limit?","items":[{"id":"a","text":"\"Girls can't play outside\""},{"id":"b","text":"\"Boys can't do art\""},{"id":"c","text":"\"Girls must cook, not study\""},{"id":"d","text":"\"Boys can't be gentle\""},{"id":"e","text":"\"Girls shouldn't lead the class\""},{"id":"f","text":"\"Boys mustn't ask for help\""}],"bins":[{"id":"girls","label":"Limits girls","valence":"neg"},{"id":"boys","label":"Limits boys","valence":"neg"}],"key":{"a":"girls","b":"boys","c":"girls","d":"boys","e":"girls","f":"boys"},"relearn":"Harmful gender norms box in both girls and boys.","persona":"any","source":"harmful norms / gender"},
  {"id":"ns-1422","cat":"harmful-norms","type":"sort","hook":"Sort: a harmful norm, or a fair rule?","items":[{"id":"a","text":"\"No outside play after dark for girls only\""},{"id":"b","text":"\"Everyone home by dark for safety\""},{"id":"c","text":"\"Only boys inherit property\""},{"id":"d","text":"\"Everyone shares chores\""},{"id":"e","text":"\"Girls can't pick their own subjects\""},{"id":"f","text":"\"Each kid picks subjects they like\""}],"bins":[{"id":"harm","label":"Harmful norm","valence":"neg"},{"id":"fair","label":"Fair rule","valence":"pos"}],"key":{"a":"harm","b":"fair","c":"harm","d":"fair","e":"harm","f":"fair"},"relearn":"A rule that applies to one gender only is usually a harmful norm.","persona":"Diya","source":"harmful norms / fairness"},
  {"id":"ns-1423","cat":"harmful-norms","type":"sort","hook":"Sort: which of these norms ranks one group above another?","items":[{"id":"a","text":"Sons inherit, daughters don't"},{"id":"b","text":"Everyone shares the sweets"},{"id":"c","text":"Boys' opinions count more"},{"id":"d","text":"We all clean up together"},{"id":"e","text":"Only sons carry the family name's pride"},{"id":"f","text":"Every child's dreams matter equally"}],"bins":[{"id":"ranks","label":"Ranks a group higher","valence":"neg"},{"id":"equal","label":"Treats all equally","valence":"pos"}],"key":{"a":"ranks","b":"equal","c":"ranks","d":"equal","e":"ranks","f":"equal"},"relearn":"Norms that rank one gender above another are harmful.","persona":"Diya","source":"harmful norms"},
  {"id":"ns-1424","cat":"harmful-norms","type":"spot","hook":"At a family dinner. Spot the two harmful norms.","scene":[{"id":"a","text":"The boys are served first and the most","trick":true},{"id":"b","text":"There is dal and rice","trick":false},{"id":"c","text":"The girls eat last, whatever's left","trick":true},{"id":"d","text":"A jug of water is on the table","trick":false},{"id":"e","text":"Everyone sits down together to eat","trick":false}],"why":"Serving boys first and best is a harmful norm that treats girls as less.","relearn":"Serving food by gender rank is a harmful, unfair norm.","persona":"Diya","source":"harmful norms / observation"},
  {"id":"ns-1425","cat":"harmful-norms","type":"spot","hook":"At a family gathering. Spot the two harmful norms.","scene":[{"id":"a","text":"\"When will you control your son's crying?\"","trick":true},{"id":"b","text":"Tea is served","trick":false},{"id":"c","text":"\"He needs to man up\"","trick":true},{"id":"d","text":"Cousins are chatting on the sofa","trick":false},{"id":"e","text":"Snacks are passed around the room","trick":false}],"why":"Shaming a boy for crying is a harmful norm that hurts boys' feelings.","relearn":"Pressuring boys to never cry is a harmful norm.","persona":"Aarav","source":"harmful norms / masculinity"},
  {"id":"ns-1426","cat":"harmful-norms","type":"spot","hook":"A TV serial scene. Spot the two harmful norms.","scene":[{"id":"a","text":"The daughter-in-law does every chore alone","trick":true},{"id":"b","text":"There is a family dinner","trick":false},{"id":"c","text":"The men are praised just for showing up","trick":true},{"id":"d","text":"A lamp is lit in the hall","trick":false},{"id":"e","text":"Background music plays softly","trick":false}],"why":"Showing women doing all the work while men are praised for little is a harmful norm.","relearn":"Media often normalises women doing all the household labour; spot it.","persona":"any","source":"harmful norms / media"},
  {"id":"ns-1427","cat":"harmful-norms","type":"match","hook":"Match the harmful norm to who it hurts most.","pairs":[{"left":"Girls eat last","right":"Girls"},{"left":"Boys can't cry","right":"Boys"},{"left":"Daughters are a burden","right":"Daughters"},{"left":"Widows stay apart","right":"Widows"},{"left":"Some are 'untouchable'","right":"Whole communities"}],"relearn":"Each harmful norm has a clear group it hurts.","persona":"Diya","source":"harmful norms"},
  {"id":"ns-1080","cat":"helpful-norms","type":"sort","hook":"Sort: helpful norm, or a habit that hurts no one either way?","items":[{"id":"a","text":"Covering food to keep flies off"},{"id":"b","text":"Touching elders' feet to greet"},{"id":"c","text":"Letting a tired person sit first"},{"id":"d","text":"Always parting rice into a neat heap"},{"id":"e","text":"Returning a borrowed book"},{"id":"f","text":"Eating with your right hand"}],"bins":[{"id":"helps","label":"Helpful norm","valence":"pos"},{"id":"neutral","label":"Harmless habit","valence":"neutral"}],"key":{"a":"helps","b":"neutral","c":"helps","d":"neutral","e":"helps","f":"neutral"},"relearn":"Some norms actively help; others are just neutral habits that hurt no one.","persona":"any","source":"helpful norms"},
  {"id":"ns-1081","cat":"helpful-norms","type":"sort","hook":"Sort: does this norm respect everyone, or rank one group below another?","items":[{"id":"a","text":"Everyone shares the chores"},{"id":"b","text":"Only girls clear the plates"},{"id":"c","text":"All kids get the same snack"},{"id":"d","text":"Boys eat first, girls wait"},{"id":"e","text":"Whoever's free helps cook"},{"id":"f","text":"Listening when a friend talks"}],"bins":[{"id":"good","label":"Respects everyone","valence":"pos"},{"id":"unfair","label":"Ranks a group","valence":"neg"}],"key":{"a":"good","b":"unfair","c":"good","d":"unfair","e":"good","f":"good"},"relearn":"A helpful norm respects everyone; a norm that ranks one group is unfair.","persona":"any","source":"helpful norms / good test"},
  {"id":"ns-1082","cat":"helpful-norms","type":"sort","hook":"Diya: at a wedding, which norms here are kind to all?","items":[{"id":"a","text":"Greeting every guest warmly"},{"id":"b","text":"Saving the best food for sons only"},{"id":"c","text":"Helping the cooks clean up"},{"id":"d","text":"Letting younger cousins go hungry"},{"id":"e","text":"Sharing sweets with all the kids"},{"id":"f","text":"Thanking the people who served"}],"bins":[{"id":"kind","label":"Kind to all","valence":"pos"},{"id":"unkind","label":"Leaves someone out","valence":"neg"}],"key":{"a":"kind","b":"unkind","c":"kind","d":"unkind","e":"kind","f":"kind"},"relearn":"A helpful norm welcomes everyone; one that leaves a group out fails the kindness test.","persona":"Diya","source":"helpful norms"},
  {"id":"ns-1083","cat":"helpful-norms","type":"sort","hook":"Sort: keep it, or it quietly hurts someone?","items":[{"id":"a","text":"Wait for the lift, don't push in"},{"id":"b","text":"Mock a new kid's accent"},{"id":"c","text":"Offer water to a guest"},{"id":"d","text":"Spread a rumour for fun"},{"id":"e","text":"Hold the gate for someone behind"},{"id":"f","text":"Pick on the smallest in the group"}],"bins":[{"id":"keep","label":"Helpful, keep it","valence":"pos"},{"id":"drop","label":"Hurtful, drop it","valence":"neg"}],"key":{"a":"keep","b":"drop","c":"keep","d":"drop","e":"keep","f":"drop"},"relearn":"Keep the norms that respect everyone; drop the ones that hurt a person.","persona":"any","source":"helpful norms"},
  {"id":"ns-1084","cat":"helpful-norms","type":"sort","hook":"Sort: a courtesy norm, or a habit that's just yours?","items":[{"id":"a","text":"Saying 'after you' at a door"},{"id":"b","text":"Drinking tea before milk"},{"id":"c","text":"Giving up a seat for a pregnant aunty"},{"id":"d","text":"Folding your blanket your own way"},{"id":"e","text":"Letting someone with one item go ahead"},{"id":"f","text":"Wearing your watch on the left"}],"bins":[{"id":"courtesy","label":"Courtesy norm","valence":"pos"},{"id":"personal","label":"Personal habit","valence":"neutral"}],"key":{"a":"courtesy","b":"personal","c":"courtesy","d":"personal","e":"courtesy","f":"personal"},"relearn":"Courtesy norms are shared and kind; personal habits are just yours.","persona":"any","source":"helpful norms"},
  {"id":"ns-1085","cat":"helpful-norms","type":"sort","hook":"Asha: at the clinic queue, sort the kind norms from the harsh ones.","items":[{"id":"a","text":"First come, first served"},{"id":"b","text":"Letting a sick baby be seen sooner"},{"id":"c","text":"Cutting ahead because you're loud"},{"id":"d","text":"Saving a spot for an old man"},{"id":"e","text":"Pushing past the weaker people"},{"id":"f","text":"Telling others where the form is"}],"bins":[{"id":"kind","label":"Kind norm","valence":"pos"},{"id":"harsh","label":"Harsh norm","valence":"neg"}],"key":{"a":"kind","b":"kind","c":"harsh","d":"kind","e":"harsh","f":"kind"},"relearn":"Kind queue norms help the weakest; harsh ones reward whoever pushes hardest.","persona":"Asha","source":"helpful norms"},
  {"id":"ns-1086","cat":"helpful-norms","type":"sort","hook":"Sort: helps everyone, or quietly harms one group?","items":[{"id":"a","text":"Everyone gets a turn to speak"},{"id":"b","text":"Girls can't play on the field"},{"id":"c","text":"We clean up after ourselves"},{"id":"d","text":"Boys mustn't ever cry"},{"id":"e","text":"We share the cricket bat fairly"},{"id":"f","text":"Quieter kids get heard too"}],"bins":[{"id":"helps","label":"Helps everyone","valence":"pos"},{"id":"harms","label":"Harms a group","valence":"neg"}],"key":{"a":"helps","b":"harms","c":"helps","d":"harms","e":"helps","f":"helps"},"relearn":"Good norms include everyone; harmful ones box in one group by gender.","persona":"any","source":"helpful norms"},
  {"id":"ns-1087","cat":"helpful-norms","type":"sort","hook":"Sort: a hygiene norm that helps, or a habit that hurts no one?","items":[{"id":"a","text":"Throwing rubbish in the bin"},{"id":"b","text":"Keeping your shoes by the door"},{"id":"c","text":"Washing hands after the toilet"},{"id":"d","text":"Always picking the window seat"},{"id":"e","text":"Covering a sneeze with your elbow"},{"id":"f","text":"Stirring your dal three times"}],"bins":[{"id":"hygiene","label":"Helps health","valence":"pos"},{"id":"neutral","label":"Harmless habit","valence":"neutral"}],"key":{"a":"hygiene","b":"neutral","c":"hygiene","d":"neutral","e":"hygiene","f":"neutral"},"relearn":"Hygiene norms protect everyone's health; some habits are just neutral.","persona":"any","source":"helpful norms"},
  {"id":"ns-1088","cat":"helpful-norms","type":"sort","hook":"Rohit: at home, sort the norms that help the family from the ones that don't.","items":[{"id":"a","text":"Whoever's free does the dishes"},{"id":"b","text":"Only Ma cooks, never the men"},{"id":"c","text":"We thank whoever made dinner"},{"id":"d","text":"Sister fetches water, brother rests"},{"id":"e","text":"Dad helps with homework too"},{"id":"f","text":"We all fold our own clothes"}],"bins":[{"id":"helps","label":"Shares fairly","valence":"pos"},{"id":"unfair","label":"Dumps it on one","valence":"neg"}],"key":{"a":"helps","b":"unfair","c":"helps","d":"unfair","e":"helps","f":"helps"},"relearn":"A helpful home norm shares the load; an unfair one piles it on one person.","persona":"Rohit","source":"helpful norms"},
  {"id":"ns-1089","cat":"helpful-norms","type":"sort","hook":"Sort: a respect norm worth keeping, or just a regional custom?","items":[{"id":"a","text":"Letting a speaker finish"},{"id":"b","text":"Greeting with 'namaste'"},{"id":"c","text":"Saying sorry when you bump someone"},{"id":"d","text":"Eating sweets on festival days"},{"id":"e","text":"Thanking the bus conductor"},{"id":"f","text":"Lighting a diya at Diwali"}],"bins":[{"id":"respect","label":"Respect norm","valence":"pos"},{"id":"custom","label":"Local custom","valence":"neutral"}],"key":{"a":"respect","b":"custom","c":"respect","d":"custom","e":"respect","f":"custom"},"relearn":"Respect norms keep people kind; many customs are simply local and harm no one.","persona":"any","source":"helpful norms"},
  {"id":"ns-1090","cat":"helpful-norms","type":"sort","hook":"Sort: builds trust, or breaks it?","items":[{"id":"a","text":"Keeping a promise you made"},{"id":"b","text":"Reading a friend's messages"},{"id":"c","text":"Returning extra change you got"},{"id":"d","text":"Telling a secret you swore to keep"},{"id":"e","text":"Owning up when you break something"},{"id":"f","text":"Blaming a sibling for your mess"}],"bins":[{"id":"trust","label":"Builds trust","valence":"pos"},{"id":"breaks","label":"Breaks trust","valence":"neg"}],"key":{"a":"trust","b":"breaks","c":"trust","d":"breaks","e":"trust","f":"breaks"},"relearn":"Helpful norms build trust between people; some habits quietly break it.","persona":"any","source":"helpful norms"},
  {"id":"ns-1091","cat":"helpful-norms","type":"sort","hook":"Aarav: in the gaming group, sort the norms that keep it fun for all.","items":[{"id":"a","text":"Taking turns on the one console"},{"id":"b","text":"Leaving the new player out"},{"id":"c","text":"Helping a weaker teammate learn"},{"id":"d","text":"Mocking whoever loses"},{"id":"e","text":"Sharing tips so all improve"},{"id":"f","text":"Hogging the controller all day"}],"bins":[{"id":"fun","label":"Fun for all","valence":"pos"},{"id":"toxic","label":"Spoils it","valence":"neg"}],"key":{"a":"fun","b":"toxic","c":"fun","d":"toxic","e":"fun","f":"toxic"},"relearn":"Good group norms keep play fair and fun; harsh ones push people out.","persona":"Aarav","source":"helpful norms"},
  {"id":"ns-1092","cat":"helpful-norms","type":"sort","hook":"Sort: this norm protects people, or it just sounds strict?","items":[{"id":"a","text":"Holding the railing on stairs"},{"id":"b","text":"No shouting in the library"},{"id":"c","text":"Wearing a helmet on a cycle"},{"id":"d","text":"No singing at breakfast"},{"id":"e","text":"Crossing only at the zebra line"},{"id":"f","text":"No whistling indoors"}],"bins":[{"id":"safe","label":"Keeps people safe","valence":"pos"},{"id":"just-strict","label":"Just a strict habit","valence":"neutral"}],"key":{"a":"safe","b":"just-strict","c":"safe","d":"just-strict","e":"safe","f":"just-strict"},"relearn":"Safety norms have a caring reason; some 'strict' rules are just habits.","persona":"any","source":"helpful norms"},
  {"id":"ns-1093","cat":"helpful-norms","type":"sort","hook":"Sort: caring reason behind it, or no real reason at all?","items":[{"id":"a","text":"Boil water before drinking it"},{"id":"b","text":"Don't step on books"},{"id":"c","text":"Let pregnant women rest more"},{"id":"d","text":"Don't cut your nails at night"},{"id":"e","text":"Cover a cut to keep it clean"},{"id":"f","text":"Don't sweep after sunset"}],"bins":[{"id":"reason","label":"Has a caring reason","valence":"pos"},{"id":"no-reason","label":"Just an old habit","valence":"neutral"}],"key":{"a":"reason","b":"no-reason","c":"reason","d":"no-reason","e":"reason","f":"no-reason"},"relearn":"Many helpful norms have a real caring reason; some old habits simply don't.","persona":"any","source":"helpful norms"},
  {"id":"ns-1094","cat":"helpful-norms","type":"sort","hook":"Sort: this welcomes a newcomer, or shuts them out?","items":[{"id":"a","text":"Showing a new kid where things are"},{"id":"b","text":"Laughing at how they talk"},{"id":"c","text":"Saving them a seat at lunch"},{"id":"d","text":"Ignoring them for being 'outsiders'"},{"id":"e","text":"Explaining the local norm gently"},{"id":"f","text":"Whispering about them in a group"}],"bins":[{"id":"welcome","label":"Welcomes them","valence":"pos"},{"id":"shuts-out","label":"Shuts them out","valence":"neg"}],"key":{"a":"welcome","b":"shuts-out","c":"welcome","d":"shuts-out","e":"welcome","f":"shuts-out"},"relearn":"Teach norms kindly and welcome newcomers; don't use norms to shut people out.","persona":"any","source":"helpful norms / kindness"},
  {"id":"ns-1095","cat":"helpful-norms","type":"sort","hook":"Sort: keeps the shared space nice, or only suits you?","items":[{"id":"a","text":"Wiping the table after you eat"},{"id":"b","text":"Playing music loud at midnight"},{"id":"c","text":"Watering the shared plants"},{"id":"d","text":"Parking across two spaces"},{"id":"e","text":"Flushing and leaving it clean"},{"id":"f","text":"Dumping your bin by the gate"}],"bins":[{"id":"shared","label":"Cares for all","valence":"pos"},{"id":"selfish","label":"Suits only you","valence":"neg"}],"key":{"a":"shared","b":"selfish","c":"shared","d":"selfish","e":"shared","f":"selfish"},"relearn":"Helpful norms care for the shared space; a norm that suits only you can harm others.","persona":"any","source":"helpful norms"},
  {"id":"ns-1096","cat":"helpful-norms","type":"match","hook":"Match the helpful norm to the good it does.","pairs":[{"left":"Cover your sneeze","right":"Keeps others from falling ill"},{"left":"Listen without cutting in","right":"Makes people feel heard"},{"left":"Return what you borrow","right":"Keeps a friendship easy"},{"left":"Offer your seat","right":"Helps someone who's tired"},{"left":"Say thank you","right":"Makes a small kindness land"}],"relearn":"Each helpful norm does a clear, caring good.","persona":"any","source":"helpful norms"},
  {"id":"ns-1097","cat":"helpful-norms","type":"match","hook":"Match the kind home norm to who it helps.","pairs":[{"left":"Sharing the housework","right":"Whoever was overloaded"},{"left":"Calling everyone to eat","right":"The one who'd be left out"},{"left":"Asking before you take","right":"The owner of the thing"},{"left":"Helping with homework","right":"A struggling younger one"},{"left":"Saving food for the latecomer","right":"Whoever comes home late"}],"relearn":"Fair home norms spread the care to everyone, not just one person.","persona":"Rohit","source":"helpful norms"},
  {"id":"ns-1098","cat":"helpful-norms","type":"match","hook":"Match the school norm to why it's kind.","pairs":[{"left":"Wait your turn to answer","right":"Everyone gets a chance"},{"left":"Share your lunch","right":"No one stays hungry"},{"left":"Help carry heavy bags","right":"Eases a tired friend"},{"left":"Clean the board after class","right":"The next group can use it"},{"left":"Welcome a shy new student","right":"They feel they belong"}],"relearn":"Kind school norms make sure no one is left out or left behind.","persona":"any","source":"helpful norms"},
  {"id":"ns-1099","cat":"helpful-norms","type":"match","hook":"Asha: match the courtesy to the trust it builds.","pairs":[{"left":"Keeping a promise","right":"People can rely on you"},{"left":"Owning your mistake","right":"Others stay honest too"},{"left":"Knocking before entering","right":"Privacy is respected"},{"left":"Giving honest credit","right":"Effort gets seen"},{"left":"Saying sorry and meaning it","right":"A hurt gets repaired"}],"relearn":"Courtesy norms quietly build the trust a group runs on.","persona":"Asha","source":"helpful norms"},
  {"id":"ns-1100","cat":"helpful-norms","type":"match","hook":"Match the consent norm to what it protects.","pairs":[{"left":"Ask before you hug","right":"Someone's comfort"},{"left":"Check before sharing a photo","right":"Their privacy"},{"left":"Wait for a yes to borrow","right":"What's theirs"},{"left":"Stop when they say stop","right":"Their boundary"},{"left":"Ask before you tickle","right":"Their body"}],"relearn":"Consent norms protect each person's body, space and choices.","persona":"any","source":"helpful norms"},
  {"id":"ns-1101","cat":"helpful-norms","type":"match","hook":"Match the public-space norm to the harm it prevents.","pairs":[{"left":"Bin your wrapper","right":"A littered street"},{"left":"Lower your voice at night","right":"Sleepless neighbours"},{"left":"Queue at the counter","right":"Pushing and chaos"},{"left":"Keep left on stairs","right":"Bumping into people"},{"left":"Pick up after your dog","right":"A dirty footpath"}],"relearn":"Shared-space norms quietly stop small harms that add up for everyone.","persona":"any","source":"helpful norms"},
  {"id":"ns-1102","cat":"helpful-norms","type":"match","hook":"Match the kind act to the feeling it gives.","pairs":[{"left":"Holding the gate open","right":"Someone feels noticed"},{"left":"Cheering a nervous speaker","right":"They feel braver"},{"left":"Saving a friend a seat","right":"They feel wanted"},{"left":"Thanking the cleaner","right":"Their work feels seen"},{"left":"Sharing your umbrella","right":"They feel looked after"}],"relearn":"Small helpful norms leave people feeling seen and cared for.","persona":"any","source":"helpful norms"},
  {"id":"ns-1103","cat":"helpful-norms","type":"match","hook":"Match the helpful habit to the reason it caught on.","pairs":[{"left":"Covering cooked food","right":"Flies spread germs"},{"left":"Washing before eating","right":"Hands carry dirt"},{"left":"Resting an injured leg","right":"It heals faster"},{"left":"Drinking boiled water","right":"It's safer to drink"},{"left":"Airing out a damp room","right":"Mould won't grow"}],"relearn":"Many helpful norms began as smart, caring solutions to a real problem.","persona":"any","source":"helpful norms"},
  {"id":"ns-1104","cat":"helpful-norms","type":"match","hook":"Match the gentle norm to the person it lifts.","pairs":[{"left":"Walking slowly with grandma","right":"An elder who's frail"},{"left":"Reading aloud for a friend","right":"Someone who can't see well"},{"left":"Carrying water for a neighbour","right":"Someone unwell"},{"left":"Saving notes for an absentee","right":"A sick classmate"},{"left":"Translating for a visitor","right":"Someone new to the place"}],"relearn":"Helpful norms reach for whoever needs a hand that day.","persona":"any","source":"helpful norms"},
  {"id":"ns-1105","cat":"helpful-norms","type":"match","hook":"Diya: match the fair norm to the unfair one it replaces.","pairs":[{"left":"All share the chores","right":"Only girls clean up"},{"left":"Everyone eats together","right":"Girls eat last"},{"left":"Any kid can cycle to school","right":"Cycling 'isn't for girls'"},{"left":"All cousins get sweets","right":"Sons get the most"},{"left":"Anyone can lead the game","right":"Only boys decide"}],"relearn":"A fair norm can replace an unfair one and still respect the family.","persona":"Diya","source":"helpful norms"},
  {"id":"ns-1106","cat":"helpful-norms","type":"match","hook":"Match the helpful norm to where it's needed.","pairs":[{"left":"Switch off taps you pass","right":"A dripping public tap"},{"left":"Mute your phone","right":"A quiet hospital ward"},{"left":"Stand in line","right":"A busy ration shop"},{"left":"Give way to an ambulance","right":"A jammed road"},{"left":"Speak softly","right":"A library reading room"}],"relearn":"Helpful norms fit the place; each one prevents a small harm there.","persona":"any","source":"helpful norms"},
  {"id":"ns-1107","cat":"helpful-norms","type":"reflect","hook":"Lensy: a helpful norm respects everyone and harms no one. Which helpful norm do you live by?","prompt":"Pick one you'd keep.","options":["Waiting my turn","Saying thank you","Asking before I borrow"],"affirm":"Whichever you picked, it respects others and harms no one. That's a good norm.","relearn":"A helpful norm respects everyone and harms no one.","persona":"any","source":"helpful norms"},
  {"id":"ns-1108","cat":"helpful-norms","type":"reflect","hook":"Lensy: which small kindness makes your street feel friendlier?","prompt":"There's no wrong pick.","options":["Neighbours greeting each other","People binning their litter","Folks holding the gate open"],"affirm":"Any of these is the quiet glue that keeps a place kind.","relearn":"Helpful norms are the quiet glue of a kind community.","persona":"any","source":"helpful norms"},
  {"id":"ns-1109","cat":"helpful-norms","type":"reflect","hook":"Diya: when you teach a younger cousin a norm, how do you want to do it?","prompt":"What feels right to you?","options":["Explain it gently","Show them by doing it","Answer their 'why' kindly"],"affirm":"All three teach a norm with care, never with shame. That's how good norms spread.","relearn":"Teach norms kindly; don't use them to shame.","persona":"Diya","source":"helpful norms"},
  {"id":"ns-1110","cat":"helpful-norms","type":"reflect","hook":"Lensy: everyone's littering, but you bin yours. Why might you keep doing the helpful thing?","prompt":"Whatever fits you.","options":["The street stays nicer","Someone might copy me","It just feels right"],"affirm":"Each reason holds. You can keep a helpful norm even when the crowd drops it.","relearn":"You can keep the helpful thing even when others don't.","persona":"any","source":"helpful norms / integrity"},
  {"id":"ns-1111","cat":"helpful-norms","type":"reflect","hook":"Rohit: a norm where everyone shares the housework. How does that feel to you?","prompt":"No wrong answer.","options":["Fairer for everyone","Lighter for whoever was tired","Just kind, really"],"affirm":"However you see it, a shared-load norm respects everyone at home.","relearn":"A helpful home norm shares the care, and that respects everyone.","persona":"Rohit","source":"helpful norms"},
  {"id":"ns-1112","cat":"helpful-norms","type":"reflect","hook":"Lensy: someone says thank you to you for a small help. What does that do?","prompt":"Pick whatever's true for you.","options":["Makes me feel seen","Makes me want to help again","Just makes the day nicer"],"affirm":"Any of these. A tiny norm like 'thanks' carries real warmth.","relearn":"Small helpful norms leave people feeling seen.","persona":"any","source":"helpful norms"},
  {"id":"ns-1113","cat":"helpful-norms","type":"reflect","hook":"Asha: which helpful norm would you most want to pass to younger kids?","prompt":"Choose one to carry forward.","options":["Wait your turn fairly","Ask before you take","Welcome the new person"],"affirm":"Whatever you'd pass on, you're keeping the helpful part of your culture alive.","relearn":"You can keep and pass on the helpful norms you inherit.","persona":"Asha","source":"helpful norms"},
  {"id":"ns-1114","cat":"helpful-norms","type":"reflect","hook":"Lensy: a guest arrives and you offer them water without being asked. Why do that?","prompt":"Whatever feels right.","options":["It makes them feel welcome","It's just how we care here","It costs me nothing"],"affirm":"Each is a fine reason. Hospitality is a helpful norm with a caring heart.","relearn":"Helpful norms usually have a caring reason behind them.","persona":"any","source":"helpful norms"},
  {"id":"ns-1115","cat":"helpful-norms","type":"reflect","hook":"Aarav: in your game group, what makes a norm worth keeping?","prompt":"No wrong take.","options":["It keeps play fair","It lets everyone join","It stops the mocking"],"affirm":"All of these keep the group fun for everyone, not just the loudest.","relearn":"Good group norms keep play fair and welcoming.","persona":"Aarav","source":"helpful norms"},
  {"id":"ns-1116","cat":"helpful-norms","type":"reflect","hook":"Lensy: which helpful norm do you wish more people followed?","prompt":"Pick the one you'd choose.","options":["Lowering noise at night","Keeping shared spaces clean","Letting elders go first"],"affirm":"Any pick is a norm that respects others and harms no one. A good one.","relearn":"A helpful norm respects everyone and harms no one.","persona":"any","source":"helpful norms"},
  {"id":"ns-1117","cat":"helpful-norms","type":"reflect","hook":"Lensy: a norm can help, or just be a harmless habit. Which 'just a habit' one is yours?","prompt":"Share whatever's true.","options":["The way I fold clothes","Which hand I wear my watch on","My usual breakfast"],"affirm":"That one's simply yours and harms no one, that's a neutral habit, not a rule for all.","relearn":"Some norms help; others are just neutral personal habits.","persona":"any","source":"helpful norms"},
  {"id":"ns-1118","cat":"helpful-norms","type":"branch","hook":"A classmate doesn't know the 'wait outside the staff room' norm and walks in.","options":[{"text":"Quietly tell them the norm later","consequence":"They learn it, not embarrassed.","outcome":"kind","best":true},{"text":"Shout 'you can't be in there!'","consequence":"They feel shamed by the harsh telling."},{"text":"Say nothing, let them keep slipping up","consequence":"They keep getting it wrong, no kind hint."}],"debrief":"A helpful norm is best shared gently, not used to shame.","relearn":"Teach norms kindly; don't shame newcomers.","persona":"any","source":"kindness"},
  {"id":"ns-1119","cat":"helpful-norms","type":"branch","hook":"At the water cooler everyone's cutting the line, 'just push in'.","options":[{"text":"Keep queuing fairly anyway","consequence":"You hold the norm; some fall in line behind you.","outcome":"leader","best":true},{"text":"Push in because everyone does","consequence":"The fair norm fades; small kids lose out."},{"text":"Give up and walk away thirsty","consequence":"Nothing improves; you miss your turn."}],"debrief":"You can keep a helpful norm even when the crowd drops it.","relearn":"You can keep the helpful thing even if others don't.","persona":"any","source":"integrity"},
  {"id":"ns-1120","cat":"helpful-norms","type":"branch","hook":"Your group jokes about a new boy's accent. A 'mock the outsider' norm is forming.","options":[{"text":"Welcome him and learn his name","consequence":"He relaxes; a kinder norm starts.","outcome":"kind","best":true},{"text":"Join the laughing to fit in","consequence":"He feels shut out; the unkind norm hardens."},{"text":"Stay silent and look away","consequence":"The mocking carries on, unsoftened."}],"debrief":"Norms should welcome newcomers, not shut them out.","relearn":"Use norms kindly; never to shut people out.","persona":"any","source":"kindness"},
  {"id":"ns-1121","cat":"helpful-norms","type":"branch","hook":"Diya: at dinner, boys eat first and girls eat the leftovers.","options":[{"text":"Warmly suggest everyone eats together","consequence":"It feels fairer; you asked respectfully.","outcome":"fair","best":true},{"text":"Eat the leftovers silently again","consequence":"The unfair norm carries on unquestioned."},{"text":"Snap and storm off, no dinner","consequence":"The point is lost in anger; nothing changes."}],"debrief":"You can love your family and still propose a fairer norm.","relearn":"A fair norm can replace an unfair one, asked kindly.","persona":"Diya","source":"fair home"},
  {"id":"ns-1122","cat":"helpful-norms","type":"branch","hook":"Rohit: your son sees you doing dishes: 'isn't that Ma's job?'","options":[{"text":"Say chores are for whoever's free, keep washing","consequence":"He learns a fairer norm by watching you.","outcome":"model","best":true},{"text":"Hand him the plate: 'not for men'","consequence":"The old 'men skip housework' norm passes on."},{"text":"Laugh it off, put the plate down","consequence":"A chance to model a fairer norm slips by."}],"debrief":"Helpful home norms are taught best by living them.","relearn":"You model a fairer norm by doing the helpful thing.","persona":"Rohit","source":"fair home"},
  {"id":"ns-1123","cat":"helpful-norms","type":"branch","hook":"On a packed bus, an elder is standing. Nobody's moving; the norm's gone sleepy.","options":[{"text":"Offer your seat, say it kindly","consequence":"They sit, grateful; others notice and shift up.","outcome":"kind","best":true},{"text":"Pretend to be asleep","consequence":"The elder keeps standing, swaying."},{"text":"Wait for someone older to do it","consequence":"All wait for all; the elder stays standing."}],"debrief":"A helpful norm only works when someone actually does it.","relearn":"Offering a seat is a norm that needs someone to start it.","persona":"any","source":"helpful norms"},
  {"id":"ns-1124","cat":"helpful-norms","type":"branch","hook":"A friend shares your photo in a group without asking: 'everyone does it.'","options":[{"text":"Gently ask them to check first next time","consequence":"They learn 'ask before you share' is kinder.","outcome":"consent","best":true},{"text":"Share their photo to get even","consequence":"Now two feel their privacy ignored."},{"text":"Let it slide, feel bad quietly","consequence":"The 'share without asking' habit keeps going."}],"debrief":"'Ask before you share' is a consent norm worth keeping.","relearn":"Consent norms protect everyone, worth keeping.","persona":"any","source":"consent"},
  {"id":"ns-1125","cat":"helpful-norms","type":"branch","hook":"Aarav: a weaker teammate keeps losing and the group wants to drop him.","options":[{"text":"Suggest the group help him improve","consequence":"He gets better and stays; the norm turns kind.","outcome":"include","best":true},{"text":"Vote to kick him to keep winning","consequence":"He's pushed out; the 'mock the loser' norm wins."},{"text":"Shrug, let the group decide","consequence":"He's dropped, no one in his corner."}],"debrief":"Good group norms help the weakest, not push them out.","relearn":"Helpful group norms include people, not rank them.","persona":"Aarav","source":"helpful norms"},
  {"id":"ns-1126","cat":"helpful-norms","type":"branch","hook":"Your team finishes a project. The 'norm' is to thank only the loudest leader.","options":[{"text":"Name everyone who helped, quiet ones too","consequence":"Shy helpers feel seen; credit is shared.","outcome":"fair","best":true},{"text":"Just thank the loudest, as usual","consequence":"The quiet workers go unnoticed again."},{"text":"Say nothing, let it pass","consequence":"Effort goes unseen; the unfair habit holds."}],"debrief":"A fair norm gives honest credit to everyone who helped.","relearn":"Helpful norms make sure quiet effort gets seen too.","persona":"any","source":"helpful norms"},
  {"id":"ns-1127","cat":"helpful-norms","type":"branch","hook":"Asha: at a workshop, a shy girl is talked over.","options":[{"text":"Make space: 'let's hear her, she had a point'","consequence":"She speaks; an 'all get heard' norm takes root.","outcome":"include","best":true},{"text":"Carry on with the louder voices","consequence":"Her idea is lost; she stays silent."},{"text":"Tell her to just speak louder","consequence":"She shrinks back; the talking-over goes on."}],"debrief":"A helpful norm makes sure quieter people get heard too.","relearn":"Good norms give everyone a turn, not just the loudest.","persona":"Asha","source":"helpful norms"},
  {"id":"ns-1128","cat":"helpful-norms","type":"branch","hook":"A younger kid is about to cross outside the zebra line, like the crowd.","options":[{"text":"Walk them to the crossing, use it together","consequence":"They cross safely, learn the safer norm.","outcome":"safe","best":true},{"text":"Let them follow the crowd across","consequence":"They take the risky shortcut all take."},{"text":"Yell at them to stop, walk off","consequence":"They freeze, confused, no safe path."}],"debrief":"A safety norm is best passed on by doing it with someone.","relearn":"Safety norms protect people; model them, don't shout.","persona":"any","source":"helpful norms"},
  {"id":"ns-1129","cat":"helpful-norms","type":"spot","hook":"In the classroom. Spot the helpful norms at work.","scene":[{"id":"a","text":"A student waits to be called before answering","trick":true},{"id":"b","text":"The walls are painted yellow","trick":false},{"id":"c","text":"Someone shares a spare pen with a friend","trick":true},{"id":"d","text":"There are thirty desks in rows","trick":false},{"id":"e","text":"The clock reads ten past nine","trick":false}],"why":"Waiting your turn and sharing are helpful norms; wall colour, desk count and time are just facts.","relearn":"Helpful norms keep a classroom fair and kind.","persona":"any","source":"helpful norms"},
  {"id":"ns-1130","cat":"helpful-norms","type":"spot","hook":"In the kitchen at home. Spot the helpful norms.","scene":[{"id":"a","text":"Dad washes up after his own meal","trick":true},{"id":"b","text":"The kettle is steel","trick":false},{"id":"c","text":"Everyone says thanks to whoever cooked","trick":true},{"id":"d","text":"There are four chairs at the table","trick":false},{"id":"e","text":"The dal is in a blue bowl","trick":false}],"why":"Sharing clean-up and thanking the cook are fair home norms; the kettle, chairs and bowl are just details.","relearn":"Fair home norms share the load and the thanks.","persona":"Rohit","source":"helpful norms"},
  {"id":"ns-1131","cat":"helpful-norms","type":"spot","hook":"At the corner shop queue. Spot the helpful norms.","scene":[{"id":"a","text":"People wait their turn without pushing","trick":true},{"id":"b","text":"The shop sells biscuits","trick":false},{"id":"c","text":"Someone lets an elder go ahead","trick":true},{"id":"d","text":"A fan spins on the ceiling","trick":false},{"id":"e","text":"The shutter is half green","trick":false}],"why":"Queuing fairly and letting an elder ahead are kind norms; the biscuits, fan and shutter are just scenery.","relearn":"Helpful queue norms keep things fair and gentle.","persona":"any","source":"helpful norms"},
  {"id":"ns-1132","cat":"helpful-norms","type":"spot","hook":"In the playground. Spot the helpful norms.","scene":[{"id":"a","text":"Kids take turns on the one swing","trick":true},{"id":"b","text":"The slide is red","trick":false},{"id":"c","text":"A girl is asked to join the cricket","trick":true},{"id":"d","text":"There are two neem trees","trick":false},{"id":"e","text":"The ground is sandy","trick":false}],"why":"Taking turns and including a girl in the game are fair norms; the slide, trees and ground are just facts.","relearn":"Good play norms share turns and include everyone.","persona":"Diya","source":"helpful norms"},
  {"id":"ns-1133","cat":"helpful-norms","type":"spot","hook":"At a festival gathering. Spot the helpful norms.","scene":[{"id":"a","text":"Guests are greeted warmly at the door","trick":true},{"id":"b","text":"Marigolds hang on the wall","trick":false},{"id":"c","text":"Sweets are shared with every child","trick":true},{"id":"d","text":"The lights are strung in a line","trick":false},{"id":"e","text":"Drums are playing outside","trick":false}],"why":"Welcoming guests and sharing with all the children are kind norms; the flowers, lights and drums are just the scene.","relearn":"Helpful norms make a gathering welcoming for everyone.","persona":"any","source":"helpful norms"},
  {"id":"ns-1134","cat":"helpful-norms","type":"spot","hook":"On a quiet ward at the hospital. Spot the helpful norms.","scene":[{"id":"a","text":"People keep their voices low","trick":true},{"id":"b","text":"The floor is white tiles","trick":false},{"id":"c","text":"A visitor mutes their phone","trick":true},{"id":"d","text":"There are six beds in the room","trick":false},{"id":"e","text":"A window faces the road","trick":false}],"why":"Keeping quiet and muting a phone help patients rest; the tiles, beds and window are just facts.","relearn":"Helpful norms protect people who need calm and rest.","persona":"any","source":"helpful norms"},
  {"id":"ns-1135","cat":"helpful-norms","type":"spot","hook":"At the bus stop. Spot the helpful norms.","scene":[{"id":"a","text":"A boy helps an aunty lift her bag","trick":true},{"id":"b","text":"The shelter roof is tin","trick":false},{"id":"c","text":"People let those getting off step out first","trick":true},{"id":"d","text":"A poster shows a film","trick":false},{"id":"e","text":"The bench seats three","trick":false}],"why":"Helping with a bag and letting people off first are kind norms; the roof, poster and bench are just details.","relearn":"Small helpful norms make a busy stop kinder for all.","persona":"any","source":"helpful norms"},
  {"id":"ns-1136","cat":"helpful-norms","type":"role-play","hook":"A new girl doesn't know we put bags on the shelf, not the floor. Say it kindly.","setup":"She's just dropped her bag where it'll trip people. You want to help, not embarrass her.","yourLine":[{"text":"Hey, we usually pop bags on that shelf, I'll show you.","best":true},{"text":"You can't just dump it there, everyone knows that."},{"text":"Ugh, new kids never get it right."}],"relearn":"Teach a norm kindly; don't use it to shame a newcomer.","persona":"any","source":"helpful norms / kindness"},
  {"id":"ns-1137","cat":"helpful-norms","type":"role-play","hook":"Diya: at dinner you'd like to suggest everyone eats together, respectfully.","setup":"The boys are being served first as always. You want to ask for a fairer norm without a fight.","yourLine":[{"text":"Could we all sit and eat together? It feels nicer that way.","best":true},{"text":"This is so unfair, I'm not eating last again."},{"text":"Fine, I'll just take the leftovers like always."}],"relearn":"You can ask for a fairer norm kindly and still respect your family.","persona":"Diya","source":"helpful norms"},
  {"id":"ns-1138","cat":"helpful-norms","type":"role-play","hook":"Someone cuts the queue at the water tap. Hold the fair norm, kindly.","setup":"A bigger kid pushed in front of a smaller one. You're next in line.","yourLine":[{"text":"Hey, she was here first, let's keep the line fair.","best":true},{"text":"Whatever, just go, I don't care."},{"text":"Push back in front of him yourself."}],"relearn":"You can hold a fair queue norm without being harsh.","persona":"any","source":"helpful norms"},
  {"id":"ns-1139","cat":"helpful-norms","type":"role-play","hook":"Rohit: your son asks why you're folding laundry. Model the fair norm.","setup":"He thinks housework is 'Ma's job'. You want to show him it's shared.","yourLine":[{"text":"In our house, whoever's free pitches in. Want to help fold?","best":true},{"text":"Don't tell anyone, men aren't supposed to do this."},{"text":"Just go, this isn't your business."}],"relearn":"You teach a fairer home norm by living it openly.","persona":"Rohit","source":"helpful norms"},
  {"id":"ns-1140","cat":"helpful-norms","type":"role-play","hook":"A friend is about to share your photo in a group. Ask for the consent norm.","setup":"They've got their thumb over send. You'd rather they checked first.","yourLine":[{"text":"Quick, can you ask me before you post that? I'd like that.","best":true},{"text":"Don't you dare send that or I'll never talk to you."},{"text":"Eh, do what you want, it's fine I guess."}],"relearn":"'Ask before you share' is a consent norm worth keeping.","persona":"any","source":"helpful norms"},
  {"id":"ns-1141","cat":"helpful-norms","type":"role-play","hook":"Asha: a quiet girl in the group keeps getting talked over. Make space for her.","setup":"She started to speak and someone cut in. You want her heard.","yourLine":[{"text":"Hang on, I think she was saying something, let's hear her.","best":true},{"text":"If she wanted to talk she'd just be louder."},{"text":"Let's move on, we don't have all day."}],"relearn":"A helpful norm makes sure quieter people get heard too.","persona":"Asha","source":"helpful norms"},
  {"id":"ns-1142","cat":"helpful-norms","type":"role-play","hook":"Aarav: the group wants to drop a weaker player. Speak for the kinder norm.","setup":"They're about to kick him for losing. You think the group could help him instead.","yourLine":[{"text":"Let's just teach him the combos, he'll get good fast.","best":true},{"text":"Yeah, he's useless, kick him."},{"text":"I dunno, whatever you all decide."}],"relearn":"Good group norms include and help, not rank and reject.","persona":"Aarav","source":"helpful norms"},
  {"id":"ns-1143","cat":"helpful-norms","type":"role-play","hook":"An elder is standing on the bus while you sit. Offer the seat warmly.","setup":"They look tired and the bus is swaying. You'd like to give up your seat.","yourLine":[{"text":"Please, sir, take my seat, I'm getting off soon anyway.","best":true},{"text":"You can stand, I got here first."},{"text":"Pretend you don't see and look out the window."}],"relearn":"Offering a seat is a small helpful norm that needs someone to start it.","persona":"any","source":"helpful norms"},
  {"id":"ns-1144","cat":"helpful-norms","type":"strike-rewrite","hook":"Strike the myth about helpful norms.","myth":{"un":"Good manners are a waste of time.","re":"Manners are small norms that show respect and put people at ease.","why":"A please, a thank-you or a held door costs nothing and makes others feel valued."},"relearn":"Helpful norms like courtesy keep a community kind.","persona":"any","source":"helpful norms"},
  {"id":"ns-1145","cat":"helpful-norms","type":"strike-rewrite","hook":"Strike the myth.","myth":{"un":"If everyone's pushing in line, you might as well too.","re":"You can keep queuing fairly even when others don't.","why":"Holding a helpful norm protects the smallest and weakest, and others may follow your lead."},"relearn":"You can keep doing the helpful thing even when the crowd doesn't.","persona":"any","source":"helpful norms / integrity"},
  {"id":"ns-1146","cat":"helpful-norms","type":"strike-rewrite","hook":"Strike the myth about teaching norms.","myth":{"un":"If a new kid doesn't know our ways, it's fine to laugh at them.","re":"You teach a norm kindly, by showing, not by shaming.","why":"Mocking someone for not knowing a custom makes them feel small and doesn't help them learn."},"relearn":"Teach norms kindly; don't use them to shame newcomers.","persona":"any","source":"helpful norms / kindness"},
  {"id":"ns-1147","cat":"helpful-norms","type":"strike-rewrite","hook":"Rohit: strike the myth.","myth":{"un":"Housework is only a woman's job.","re":"Chores belong to whoever's around; everyone can share the load.","why":"Sharing housework is fairer and gives everyone more time and rest, women included."},"relearn":"A fair home norm shares the load instead of dumping it on one person.","persona":"Rohit","source":"helpful norms"},
  {"id":"ns-1148","cat":"helpful-norms","type":"strike-rewrite","hook":"Strike the myth about asking first.","myth":{"un":"If you're close to someone, you don't need to ask before hugging them.","re":"Even with people you love, a quick check that a hug is welcome is kind.","why":"Asking respects that the other person gets a say over their own body, always."},"relearn":"Consent and courtesy norms protect everyone and are worth keeping.","persona":"any","source":"helpful norms"},
  {"id":"ns-1149","cat":"helpful-norms","type":"strike-rewrite","hook":"Strike the myth.","myth":{"un":"One person picking up litter can't make any difference.","re":"Keeping a helpful norm yourself can quietly start others doing it too.","why":"People copy what they see; one bin-using example often nudges a whole group."},"relearn":"You can keep a helpful norm even when others don't, and it can spread.","persona":"any","source":"helpful norms"},
  {"id":"ns-1150","cat":"helpful-norms","type":"strike-rewrite","hook":"Strike the myth about saying sorry.","myth":{"un":"Saying sorry makes you look weak.","re":"A real apology is a strong norm that repairs a hurt and rebuilds trust.","why":"Owning a mistake takes courage and helps the other person, and the friendship, heal."},"relearn":"Helpful norms like a genuine sorry repair hurts and build trust.","persona":"any","source":"helpful norms"},
  {"id":"ns-1151","cat":"helpful-norms","type":"strike-rewrite","hook":"Strike the myth about quiet helpers.","myth":{"un":"Only the loudest person in a group deserves the credit.","re":"A fair norm names everyone who helped, including the quiet ones.","why":"Effort that goes unseen gets discouraged; sharing credit keeps people willing to help."},"relearn":"Helpful norms make sure quiet effort gets seen too.","persona":"any","source":"helpful norms"},
  {"id":"ns-1170","cat":"question-change","type":"role-play","hook":"At a wedding, an aunty says \"girls serve, boys sit\" and waves you to the kitchen.","setup":"Answer it warmly. Say:","yourLine":[{"text":"\"Let's all help, then we'll all enjoy the food together.\"","best":true},{"text":"\"Okay, I'll go serve.\""}],"relearn":"You can answer 'what will people say?' without giving up on fairness.","persona":"Diya","source":"question-change / log kya kahenge"},
  {"id":"ns-1171","cat":"question-change","type":"role-play","hook":"A cousin teases your brother for crying: \"don't be a girl, be a man\".","setup":"Stand up for him. Say:","yourLine":[{"text":"\"Crying is fine, anyone can have feelings.\"","best":true},{"text":"\"Yeah, toughen up, bhai.\""}],"relearn":"Boys can have feelings; the 'never cry' norm isn't a rule.","persona":"Aarav","source":"question-change / be a man"},
  {"id":"ns-1172","cat":"question-change","type":"role-play","hook":"Relatives say \"a big girl shouldn't cycle to the market on her own\".","setup":"Ask kindly for fairness. Say:","yourLine":[{"text":"\"My cousin does, so why can't I cycle there too?\"","best":true},{"text":"\"Fine, I'll always ask someone to come.\""}],"relearn":"You can respectfully question a norm that limits you by gender.","persona":"Diya","source":"question-change / mobility"},
  {"id":"ns-1173","cat":"question-change","type":"role-play","hook":"At dinner, the boys are served first and you're told \"that's how it's done\".","setup":"Name it gently. Say:","yourLine":[{"text":"\"Could we serve everyone together next time?\"","best":true},{"text":"\"It's fine, I'll wait.\""}],"relearn":"You can ask 'is this fair?' without disrespecting anyone.","persona":"Diya","source":"question-change / served last"},
  {"id":"ns-1174","cat":"question-change","type":"role-play","hook":"A neighbour tells your dad \"men shouldn't be seen washing clothes\".","setup":"Back your dad up. Say:","yourLine":[{"text":"\"Anyone in the house can wash clothes, it's just work.\"","best":true},{"text":"\"You're right, Papa, leave it.\""}],"relearn":"Housework isn't only one gender's job; norms aren't nature.","persona":"Rohit","source":"question-change / home"},
  {"id":"ns-1175","cat":"question-change","type":"role-play","hook":"An elder says \"don't ask so many questions, just respect tradition\".","setup":"Reframe it kindly. Say:","yourLine":[{"text":"\"I do respect you, and I'm just asking if it's fair.\"","best":true},{"text":"\"Sorry, I'll stop asking.\""}],"relearn":"Questioning a norm isn't the same as disrespecting people.","persona":"Asha","source":"question-change / respect"},
  {"id":"ns-1176","cat":"question-change","type":"role-play","hook":"During your period, you're told to stay out of the kitchen.","setup":"Question it calmly. Say:","yourLine":[{"text":"\"Periods are normal; can we talk about why I'm kept out?\"","best":true},{"text":"\"Okay, I'll stay away.\""}],"relearn":"Periods are normal and healthy; no one should be shut out.","persona":"Diya","source":"question-change / period stigma"},
  {"id":"ns-1177","cat":"question-change","type":"role-play","hook":"Friends say \"art and dance are for girls, don't join\".","setup":"Hold your ground. Say:","yourLine":[{"text":"\"Anyone who likes dance can dance, including me.\"","best":true},{"text":"\"Okay, maybe it's not for boys.\""}],"relearn":"You can choose fairness over 'everyone says so'.","persona":"Aarav","source":"question-change / peer pressure"},
  {"id":"ns-1178","cat":"question-change","type":"role-play","hook":"A teacher says \"boys lift the benches, girls sweep\" by default.","setup":"Suggest a fairer way. Say:","yourLine":[{"text":"\"Could we swap jobs so everyone does both, miss?\"","best":true},{"text":"Stay quiet and just sweep"}],"relearn":"A polite request can update an unfair classroom norm.","persona":"any","source":"question-change / school"},
  {"id":"ns-1179","cat":"question-change","type":"role-play","hook":"Your little sister is told \"sit properly, girls don't run around\".","setup":"Offer her a fairer message. Say:","yourLine":[{"text":"\"You can run and play as much as you like.\"","best":true},{"text":"Let it pass"}],"relearn":"You can pass a fairer norm to younger kids.","persona":"any","source":"question-change / mentoring"},
  {"id":"ns-1180","cat":"question-change","type":"role-play","hook":"At a function, you're told girls can't light the diya, only boys.","setup":"Ask warmly. Say:","yourLine":[{"text":"\"Could I light one too? I'd love to be part of it.\"","best":true},{"text":"\"Oh, okay, I'll just watch.\""}],"relearn":"A ritual norm that gatekeeps by gender can be questioned kindly.","persona":"Diya","source":"question-change / ritual"},
  {"id":"ns-1181","cat":"question-change","type":"role-play","hook":"A relative says \"why study so hard, you'll just get married\".","setup":"Answer it firmly and kindly. Say:","yourLine":[{"text":"\"I'm building my own future, marriage or not.\"","best":true},{"text":"\"Maybe you're right, what's the point.\""}],"relearn":"Every girl deserves a full education and her own future.","persona":"Diya","source":"question-change / education"},
  {"id":"ns-1182","cat":"question-change","type":"role-play","hook":"Your team says \"only boys captain, that's the norm here\".","setup":"Open it up. Say:","yourLine":[{"text":"\"Let's let anyone good lead, girl or boy.\"","best":true},{"text":"\"Fine, a boy can be captain.\""}],"relearn":"A 'one gender only' rule is usually a norm worth questioning.","persona":"any","source":"question-change / leadership"},
  {"id":"ns-1183","cat":"question-change","type":"role-play","hook":"An uncle laughs that you, a boy, want to learn cooking.","setup":"Reply easily. Say:","yourLine":[{"text":"\"Cooking's a great skill for anyone to have.\"","best":true},{"text":"\"Haha, yeah, it's a bit odd.\""}],"relearn":"You can choose fairness over 'that's not for boys'.","persona":"Aarav","source":"question-change / be a man"},
  {"id":"ns-1184","cat":"question-change","type":"role-play","hook":"Someone says \"this caste rule is old, just follow it quietly\".","setup":"Respond with respect. Say:","yourLine":[{"text":"\"Everyone's equal in dignity; I'd rather treat people fairly.\"","best":true},{"text":"\"Okay, I won't think about it.\""}],"relearn":"Everyone is equal in dignity; old unfair norms can be questioned.","persona":"Asha","source":"question-change / dignity"},
  {"id":"ns-1185","cat":"question-change","type":"role-play","hook":"At home you're told \"sons get to choose, daughters just adjust\".","setup":"Name it kindly. Say:","yourLine":[{"text":"\"Daughters and sons can both have a say, na?\"","best":true},{"text":"\"Okay, I'll just adjust.\""}],"relearn":"Daughters and sons are equally valuable and deserve a say.","persona":"Diya","source":"question-change / son-preference"},
  {"id":"ns-1186","cat":"question-change","type":"role-play","hook":"Friends dare you to mock a boy who joined the cooking club.","setup":"Refuse and reframe. Say:","yourLine":[{"text":"\"Nah, good for him, cooking's a useful skill.\"","best":true},{"text":"\"Haha okay, let's tease him.\""}],"relearn":"You can choose fairness over going along with the crowd.","persona":"Aarav","source":"question-change / peer pressure"},
  {"id":"ns-1187","cat":"question-change","type":"role-play","hook":"Your grandmother worries \"log kya kahenge if you play cricket with boys\".","setup":"Reassure her warmly. Say:","yourLine":[{"text":"\"I'll be fine, Dadi; playing is fair for everyone.\"","best":true},{"text":"\"You're right, I'll stop playing.\""}],"relearn":"You can answer 'what will people say?' and still choose fairness.","persona":"Diya","source":"question-change / log kya kahenge"},
  {"id":"ns-1188","cat":"question-change","type":"branch","hook":"Your class always picks boys for the science quiz, never girls.","options":[{"text":"Suggest picking on skill, and name a girl who's great at it","consequence":"The teacher tries it; the norm starts shifting.","outcome":"changemaker","best":true},{"text":"Say nothing, it's always been this way","consequence":"Staying silent keeps the unfair pick going."}],"debrief":"A small, kind suggestion can update a tired classroom norm.","relearn":"Even one questioning voice can start a norm changing.","persona":"any","source":"question-change / school"},
  {"id":"ns-1189","cat":"question-change","type":"branch","hook":"At home, only your sister is asked to clear plates after meals.","options":[{"text":"Offer to share the clearing-up from today","consequence":"You model a fairer split; others copy it.","outcome":"changemaker","best":true},{"text":"Enjoy not being asked and stay seated","consequence":"Going along keeps the unfair chore norm alive."}],"debrief":"Changing a norm starts with changing what you do.","relearn":"You can start by changing the norms in your own behaviour.","persona":"Rohit","source":"question-change / home"},
  {"id":"ns-1190","cat":"question-change","type":"branch","hook":"A WhatsApp forward jokes that \"real men never cry\".","options":[{"text":"Reply that feelings are healthy for everyone","consequence":"A friend says he felt the same; you're not alone.","outcome":"brave","best":true},{"text":"Forward it on for a laugh","consequence":"Passing on the joke helps the harmful norm spread."}],"debrief":"Boys can have feelings; you can question the 'be tough' norm.","relearn":"Silence or sharing helps a harmful norm survive.","persona":"Aarav","source":"question-change / media"},
  {"id":"ns-1191","cat":"question-change","type":"branch","hook":"Your aunt insists you skip school during your period.","options":[{"text":"Calmly explain periods are normal and you want to attend","consequence":"She listens; you don't miss your lessons.","outcome":"steady","best":true},{"text":"Miss school quietly to avoid a fuss","consequence":"Going along keeps a stigma norm that costs your learning."}],"debrief":"Periods are normal; no one should be shut out of school.","relearn":"You can question a stigma norm calmly and keep your rights.","persona":"Diya","source":"question-change / period stigma"},
  {"id":"ns-1192","cat":"question-change","type":"branch","hook":"Elders praise a family for giving a big dowry at a wedding.","options":[{"text":"Quietly tell a friend that dowry harms families and is wrong","consequence":"Your friend agrees; the idea spreads a little.","outcome":"changemaker","best":true},{"text":"Join in praising it so you fit in","consequence":"Praising it helps a harmful norm look normal."}],"debrief":"Dowry harms people and is against the law in India.","relearn":"You can question a harmful 'tradition' without rejecting your culture.","persona":"Asha","source":"question-change / dowry"},
  {"id":"ns-1193","cat":"question-change","type":"branch","hook":"Your friend group never lets the new girl join their games.","options":[{"text":"Invite her in and ask others to make space","consequence":"She joins; the group's habit of excluding shifts.","outcome":"changemaker","best":true},{"text":"Follow the group and leave her out","consequence":"Going along keeps an unkind exclusion norm alive."}],"debrief":"A fairer norm spreads when one person starts living it.","relearn":"Changing a norm starts with changing what you do.","persona":"any","source":"question-change / inclusion"},
  {"id":"ns-1193b","cat":"question-change","type":"branch","hook":"At a temple line, women are told to wait while men go first.","options":[{"text":"Ask politely if everyone can take turns in one queue","consequence":"A few nod; the line becomes fairer.","outcome":"steady","best":true},{"text":"Just accept it because it's always been so","consequence":"Accepting it quietly keeps the unfair queue going."}],"debrief":"'Always been so' isn't a reason; you can ask 'is this fair?'.","relearn":"A norm being old or common doesn't make it fair.","persona":"any","source":"question-change / queue"},
  {"id":"ns-1194","cat":"question-change","type":"branch","hook":"Your uncle says girls in the family shouldn't take up sports.","options":[{"text":"Share how your cousin thrives at kabaddi and ask him to watch","consequence":"He's impressed; his view softens.","outcome":"changemaker","best":true},{"text":"Agree to avoid an argument","consequence":"Agreeing keeps a limiting norm in place."}],"debrief":"A curious, respectful approach opens minds better than a fight.","relearn":"You can love your family and still ask 'is this fair?'.","persona":"Diya","source":"question-change / sport"},
  {"id":"ns-1195","cat":"question-change","type":"branch","hook":"You hear a shopkeeper refuse a customer over caste.","options":[{"text":"Later tell a trusted grown-up it felt unfair and wrong","consequence":"They take it seriously; you learn how to act.","outcome":"steady","best":true},{"text":"Decide it's not your business","consequence":"Looking away lets an unfair, illegal norm continue."}],"debrief":"Everyone is equal in dignity; untouchability is wrong and illegal.","relearn":"If a norm harms someone, telling a trusted grown-up helps.","persona":"any","source":"question-change / dignity"},
  {"id":"ns-1196","cat":"question-change","type":"branch","hook":"Your team plans to leave girls out of the big match \"to be safe\".","options":[{"text":"Propose mixed teams and a fair trial game","consequence":"The trial works; everyone plays.","outcome":"changemaker","best":true},{"text":"Go along to keep the peace","consequence":"Going along keeps girls boxed out of the game."}],"debrief":"A 'protective' rule that only limits girls is worth questioning.","relearn":"Harmful norms box in people; you can propose a fairer one.","persona":"any","source":"question-change / sport"},
  {"id":"ns-1197","cat":"question-change","type":"branch","hook":"A cousin says \"don't bother questioning, nothing ever changes here\".","options":[{"text":"Point out norms that already changed, like girls now in school","consequence":"He sees change is real and joins in.","outcome":"hopeful","best":true},{"text":"Agree that change is impossible","consequence":"Believing nothing changes keeps you from trying."}],"debrief":"Big harmful norms in India have genuinely changed over time.","relearn":"Even very old norms can and do change.","persona":"Asha","source":"question-change / hope"},
  {"id":"ns-1198","cat":"question-change","type":"branch","hook":"At a sleepover, friends mock a boy for liking to knit.","options":[{"text":"Say it's a cool skill and change the subject kindly","consequence":"The teasing stops; he relaxes.","outcome":"brave","best":true},{"text":"Laugh along so you're not the odd one out","consequence":"Laughing along keeps a 'not for boys' norm alive."}],"debrief":"Hobbies aren't for one gender; you can question the joke kindly.","relearn":"You can choose fairness over 'everyone's laughing'.","persona":"Aarav","source":"question-change / peer pressure"},
  {"id":"ns-1199","cat":"question-change","type":"branch","hook":"Your nani says a widow in the family shouldn't wear bright colours.","options":[{"text":"Gently ask if she'd like to, and why the rule exists","consequence":"It opens a kind talk; the rule softens.","outcome":"steady","best":true},{"text":"Repeat the rule to others as just how it is","consequence":"Repeating it as fact helps the limiting norm survive."}],"debrief":"A norm that limits one group can be questioned with love.","relearn":"You can love your family and still gently ask 'is this fair?'.","persona":"any","source":"question-change / restriction"},
  {"id":"ns-1200","cat":"question-change","type":"branch","hook":"Your dad jokes he 'can't' cook because that's 'women's work'.","options":[{"text":"Invite him to cook one dish with you this weekend","consequence":"He tries it; the home norm shifts a little.","outcome":"changemaker","best":true},{"text":"Let it slide as just a joke","consequence":"Letting it slide keeps the 'men don't cook' norm."}],"debrief":"Cooking isn't one gender's job; norms are habits, not nature.","relearn":"Fairer norms spread when people start modelling them.","persona":"Rohit","source":"question-change / home"},
  {"id":"ns-1201","cat":"question-change","type":"branch","hook":"A senior tells juniors \"girls can't do the heavy lab work\".","options":[{"text":"Pair up fairly and show the work suits anyone","consequence":"The juniors see it's about skill, not gender.","outcome":"changemaker","best":true},{"text":"Repeat the senior's rule to the juniors","consequence":"Passing it down keeps a limiting norm alive."}],"debrief":"Capability isn't decided by gender; you can model a fairer norm.","relearn":"You can pass a fairer norm to younger kids, not a harmful one.","persona":"any","source":"question-change / mentoring"},
  {"id":"ns-1202","cat":"question-change","type":"strike-rewrite","hook":"\"If you question a norm, you're disrespecting your elders.\"","myth":{"un":"Asking 'is this fair?' disrespects your elders.","re":"You can respect elders and still ask honest questions.","why":"Respect and fair questions go together, not against each other."},"relearn":"Questioning a norm is not the same as disrespecting people.","persona":"Asha","source":"question-change / respect"},
  {"id":"ns-1203","cat":"question-change","type":"strike-rewrite","hook":"\"A norm everyone in our area follows must be the fair one.\"","myth":{"un":"A norm is fair because everyone here follows it.","re":"A norm being common doesn't make it fair.","why":"Many people once followed unfair norms too."},"relearn":"Common doesn't mean fair; test each norm.","persona":"any","source":"question-change / common"},
  {"id":"ns-1204","cat":"question-change","type":"strike-rewrite","hook":"\"Changing a norm has to be a huge, dramatic protest.\"","myth":{"un":"Changing a norm needs one big dramatic protest.","re":"Change usually starts small, with everyday fair choices.","why":"Fairer norms spread when people quietly keep living them."},"relearn":"Changing a norm starts with small, everyday choices.","persona":"Asha","source":"question-change / collective"},
  {"id":"ns-1205","cat":"question-change","type":"strike-rewrite","hook":"\"If I just stay quiet, a harmful norm won't really affect anyone.\"","myth":{"un":"Staying quiet about a harmful norm keeps it harmless.","re":"Silence helps a harmful norm survive.","why":"Norms continue as long as people keep going along with them."},"relearn":"Quietly going along helps keep a harmful norm alive.","persona":"any","source":"question-change / bystander"},
  {"id":"ns-1206","cat":"question-change","type":"strike-rewrite","hook":"\"You're only a kid, so your fair question doesn't count.\"","myth":{"un":"A kid's fair question doesn't really count.","re":"Kids' fair questions deserve to be heard.","why":"A clear, calm question can make a point land at any age."},"relearn":"Make your fair point calmly; your voice counts.","persona":"Diya","source":"question-change / voice"},
  {"id":"ns-1207","cat":"question-change","type":"strike-rewrite","hook":"\"Wanting a norm to be fairer means you hate your own culture.\"","myth":{"un":"Wanting a norm to be fairer means hating your culture.","re":"You can love your culture and want it fairer at once.","why":"Cultures grow by keeping the kind parts and dropping the cruel."},"relearn":"Loving your culture and wanting it fairer go together.","persona":"Asha","source":"question-change / culture"},
  {"id":"ns-1208","cat":"question-change","type":"strike-rewrite","hook":"\"Boys who share housework are being soft and unmanly.\"","myth":{"un":"A boy who shares housework is being unmanly.","re":"Sharing the load is fair and useful for everyone.","why":"Chores are just work; they're not owned by one gender."},"relearn":"Boys can share the load; that norm helps everyone.","persona":"Rohit","source":"question-change / home"},
  {"id":"ns-1209","cat":"question-change","type":"strike-rewrite","hook":"\"It's our tradition, so it can't possibly be unfair.\"","myth":{"un":"If it's tradition, it can't be unfair.","re":"Traditions can be kind or harmful; test each one.","why":"Calling something tradition doesn't pass it through the fairness test."},"relearn":"'It's tradition' isn't a reason; check if it's fair.","persona":"any","source":"question-change / tradition"},
  {"id":"ns-1210","cat":"question-change","type":"reflect","hook":"Lensy: which fairer norm would you most like to start at home?","prompt":"Pick one.","options":["Everyone shares chores","Girls and boys play out equally","Feelings are okay for all"],"affirm":"Picture it normal, then take one small step to start it.","relearn":"Imagining a fairer norm is the first step to making it normal.","persona":"any","source":"question-change / vision"},
  {"id":"ns-1211","cat":"question-change","type":"reflect","hook":"Lensy: when a norm feels unfair, what's a kind first move?","prompt":"Pick what fits you.","options":["Ask a gentle question","Tell a trusted grown-up","Try the fairer thing yourself"],"affirm":"Any of these is a brave, kind start.","relearn":"Questioning a harmful norm kindly is a brave first step.","persona":"any","source":"question-change / agency"},
  {"id":"ns-1212","cat":"question-change","type":"reflect","hook":"Lensy: which line would you use to answer 'log kya kahenge'?","prompt":"Pick your line.","options":["\"Maybe they'll learn something\"","\"I'd rather be fair\"","\"I love them and want fairness\""],"affirm":"Each one answers the question without giving up on fairness.","relearn":"You can answer 'what will people say?' and still choose fairness.","persona":"Diya","source":"question-change / log kya kahenge"},
  {"id":"ns-1213","cat":"question-change","type":"reflect","hook":"Lensy: who could you team up with to question a harmful norm?","prompt":"Pick one.","options":["A friend who agrees","A trusted teacher","A caring family member"],"affirm":"Change is easier together; find your people.","relearn":"Big norm changes often begin with a few people questioning together.","persona":"Asha","source":"question-change / collective"},
  {"id":"ns-1214","cat":"question-change","type":"reflect","hook":"Lensy: what helps you stay calm when a fair point gets dismissed?","prompt":"Pick what works for you.","options":["Take a breath","Restate it simply","Remember it's worth saying"],"affirm":"Calm and clear lands better than loud; well done.","relearn":"Make your fair point calmly, even if dismissed at first.","persona":"Aarav","source":"question-change / voice"},
  {"id":"ns-1215","cat":"question-change","type":"reflect","hook":"Lensy: which part of your culture would you most want to keep?","prompt":"Pick one you love.","options":["Festivals together","Caring for elders","Sharing food with neighbours"],"affirm":"Keep the kind parts; you can question the cruel ones too.","relearn":"You can keep what's good in a culture and fix what harms.","persona":"any","source":"question-change / culture"},
  {"id":"ns-1216","cat":"question-change","type":"spot","hook":"Spot the harmful norm hiding among fair ones at this family meal.","scene":[{"id":"a","text":"Everyone washes hands before eating","trick":false},{"id":"b","text":"Only the girls are told to serve and clear","trick":true},{"id":"c","text":"People say thank you to whoever cooked","trick":false},{"id":"d","text":"Boys are served first because 'they need more'","trick":true},{"id":"e","text":"Guests are offered water as they arrive","trick":false}],"why":"Serving only by gender and feeding boys first rank one group above another.","relearn":"You can spot harmful norms hiding among fair, helpful ones.","persona":"any","source":"question-change / spot"},
  {"id":"ns-1217","cat":"question-change","type":"spot","hook":"Spot the harmful norm among these classroom habits.","scene":[{"id":"a","text":"Students queue quietly for the water tap","trick":false},{"id":"b","text":"Only boys are picked to answer in maths","trick":true},{"id":"c","text":"Everyone shares the cleaning roster","trick":false},{"id":"d","text":"Girls are told they 'can't' do the heavy lab work","trick":true},{"id":"e","text":"The class thanks the helper who fixed the fan","trick":false}],"why":"Picking by gender and saying one gender 'can't' limit students unfairly.","relearn":"A norm that limits a group by gender is worth questioning.","persona":"any","source":"question-change / school"},
  {"id":"ns-1218","cat":"question-change","type":"spot","hook":"Spot the harmful norm among these home rules.","scene":[{"id":"a","text":"Shoes come off at the door","trick":false},{"id":"b","text":"Only the daughter does the cleaning each day","trick":true},{"id":"c","text":"Everyone greets guests warmly","trick":false},{"id":"d","text":"The son's wishes always come before the daughter's","trick":true},{"id":"e","text":"The family eats dinner together","trick":false}],"why":"Loading chores onto the daughter and ranking the son above her are harmful, gendered norms.","relearn":"Daughters and sons are equally valuable and deserve equal say.","persona":"Diya","source":"question-change / home"},
  {"id":"ns-1219","cat":"question-change","type":"spot","hook":"Spot the harmful norm among these things people say about boys.","scene":[{"id":"a","text":"\"Wash up before dinner.\"","trick":false},{"id":"b","text":"\"Boys must never cry, ever.\"","trick":true},{"id":"c","text":"\"Help carry the bags, please.\"","trick":false},{"id":"d","text":"\"Asking for help means you're weak.\"","trick":true},{"id":"e","text":"\"Say thank you to the auto driver.\"","trick":false}],"why":"'Never cry' and 'help means weak' box boys in and harm them too.","relearn":"Boys can have feelings and ask for help; that norm harms boys.","persona":"Aarav","source":"question-change / be a man"},
  {"id":"ns-1220","cat":"question-change","type":"spot","hook":"Spot the harmful norm hiding in this festival scene.","scene":[{"id":"a","text":"Neighbours share sweets all around","trick":false},{"id":"b","text":"Girls are kept away from the main rituals","trick":true},{"id":"c","text":"Everyone helps clean up afterwards","trick":false},{"id":"d","text":"A bigger gift is expected from the bride's family","trick":true},{"id":"e","text":"People queue politely for prasad","trick":false}],"why":"Barring girls from rituals and expecting a bride's gift are harmful, unfair norms.","relearn":"You can question a harmful 'tradition' while keeping the kind parts.","persona":"any","source":"question-change / ritual"},
  {"id":"ns-1221","cat":"question-change","type":"spot","hook":"Spot the harmful norm among these playground habits.","scene":[{"id":"a","text":"Kids take turns on the swing","trick":false},{"id":"b","text":"Girls aren't allowed to play cricket here","trick":true},{"id":"c","text":"Everyone helps a kid who falls","trick":false},{"id":"d","text":"The new kid is left out 'because that's how it is'","trick":true},{"id":"e","text":"Players shake hands after a match","trick":false}],"why":"Banning girls from a game and excluding the new kid limit people unfairly.","relearn":"A norm being 'how it is' doesn't make it fair.","persona":"any","source":"question-change / play"},
  {"id":"ns-1222","cat":"question-change","type":"spot","hook":"Spot the harmful norm in these things said about study and work.","scene":[{"id":"a","text":"\"Finish your homework before playing.\"","trick":false},{"id":"b","text":"\"Why study, you'll just get married.\"","trick":true},{"id":"c","text":"\"Read a little every day, it helps.\"","trick":false},{"id":"d","text":"\"Girls shouldn't aim for big careers.\"","trick":true},{"id":"e","text":"\"Ask your teacher if you're stuck.\"","trick":false}],"why":"'You'll just marry' and 'no big careers' limit a girl's future unfairly.","relearn":"Every girl deserves a full education and her own future.","persona":"Diya","source":"question-change / education"},
  {"id":"ns-1223","cat":"question-change","type":"sort","hook":"Sort each move into 'Helps change a norm' or 'Keeps it stuck'.","items":[{"id":"a","text":"Gently ask 'could we try a fairer way?'"},{"id":"b","text":"Stay silent so no one's upset"},{"id":"c","text":"Model the fairer thing yourself"},{"id":"d","text":"Tease anyone who questions the norm"},{"id":"e","text":"Find others who agree and team up"},{"id":"f","text":"Repeat 'that's just how it is'"}],"bins":[{"id":"helps","label":"Helps change it","valence":"pos"},{"id":"stuck","label":"Keeps it stuck","valence":"neg"}],"key":{"a":"helps","b":"stuck","c":"helps","d":"stuck","e":"helps","f":"stuck"},"relearn":"Questioning kindly, modelling fairness and teaming up help norms change.","persona":"Asha","source":"question-change / collective"},
  {"id":"ns-1224","cat":"question-change","type":"sort","hook":"Sort each line into 'Brave fair question' or 'Just going along'.","items":[{"id":"a","text":"\"Could everyone get a turn, not just boys?\""},{"id":"b","text":"\"Okay, I'll stay quiet.\""},{"id":"c","text":"\"I love you, and is this fair?\""},{"id":"d","text":"\"Fine, everyone does it.\""},{"id":"e","text":"\"Can we share the chores?\""},{"id":"f","text":"\"You're right, I'll adjust.\""}],"bins":[{"id":"brave","label":"Brave fair question","valence":"tell"},{"id":"along","label":"Just going along","valence":"uhoh"}],"key":{"a":"brave","b":"along","c":"brave","d":"along","e":"brave","f":"along"},"relearn":"Asking a fair question isn't arguing; going along keeps norms stuck.","persona":"Diya","source":"question-change / voice"},
  {"id":"ns-1225","cat":"question-change","type":"sort","hook":"Sort each thought into 'True about change' or 'A myth'.","items":[{"id":"a","text":"Change can start with one voice"},{"id":"b","text":"One kid can't change anything"},{"id":"c","text":"Fairer norms spread when people live them"},{"id":"d","text":"Questioning rejects all your culture"},{"id":"e","text":"You can love family and ask for fairness"},{"id":"f","text":"If it's old, it must be fair"}],"bins":[{"id":"true","label":"True about change","valence":"pos"},{"id":"myth","label":"A myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Norms are made by people; keep the helpful, question the harmful.","persona":"any","source":"question-change / agency"},
  {"id":"ns-1226","cat":"question-change","type":"sort","hook":"Sort each reply to 'log kya kahenge' into 'Stays fair' or 'Gives up fairness'.","items":[{"id":"a","text":"\"Maybe they'll learn something new.\""},{"id":"b","text":"\"You're right, I'll stop.\""},{"id":"c","text":"\"I'd rather be fair than follow.\""},{"id":"d","text":"\"Okay, I'll just go along.\""},{"id":"e","text":"\"I love them and still want fairness.\""},{"id":"f","text":"\"Fine, I won't care.\""}],"bins":[{"id":"fair","label":"Stays fair","valence":"pos"},{"id":"gives","label":"Gives up fairness","valence":"neg"}],"key":{"a":"fair","b":"gives","c":"fair","d":"gives","e":"fair","f":"gives"},"relearn":"You can answer 'what will people say?' without giving up on fairness.","persona":"Diya","source":"question-change / log kya kahenge"},
  {"id":"ns-1227","cat":"question-change","type":"sort","hook":"Sort each at-home choice into 'Fairer norm' or 'Keeps the old one'.","items":[{"id":"a","text":"Dad offers to cook tonight"},{"id":"b","text":"Only the daughter clears plates"},{"id":"c","text":"Everyone shares chores by a rota"},{"id":"d","text":"The son's wishes come first"},{"id":"e","text":"Brother and sister both wash clothes"},{"id":"f","text":"Girls serve, boys sit and wait"}],"bins":[{"id":"fairer","label":"Fairer norm","valence":"pos"},{"id":"old","label":"Keeps the old one","valence":"neg"}],"key":{"a":"fairer","b":"old","c":"fairer","d":"old","e":"fairer","f":"old"},"relearn":"Fairer norms spread when people start modelling them at home.","persona":"Rohit","source":"question-change / home"},
  {"id":"ns-1228","cat":"question-change","type":"sort","hook":"Sort each move into 'Kind way to question' or 'Harsh way that backfires'.","items":[{"id":"a","text":"Ask a gentle, curious question"},{"id":"b","text":"Shout that everyone's wrong"},{"id":"c","text":"Share an example that opens minds"},{"id":"d","text":"Mock people for their old views"},{"id":"e","text":"Stay calm and restate your point"},{"id":"f","text":"Insult elders to win the argument"}],"bins":[{"id":"kind","label":"Kind way","valence":"pos"},{"id":"harsh","label":"Harsh way","valence":"neg"}],"key":{"a":"kind","b":"harsh","c":"kind","d":"harsh","e":"kind","f":"harsh"},"relearn":"A curious, respectful question opens minds better than an attack.","persona":"Asha","source":"question-change / approach"},
  {"id":"ns-1229","cat":"question-change","type":"sort","hook":"Sort each into 'Changed for better' or 'Still to question'.","items":[{"id":"a","text":"Girls now go to school"},{"id":"b","text":"Some still skip girls in periods"},{"id":"c","text":"Widows can remarry now"},{"id":"d","text":"Some still expect a dowry"},{"id":"e","text":"Untouchability is now wrong, illegal"},{"id":"f","text":"Some still tell boys not to cry"}],"bins":[{"id":"changed","label":"Changed for better","valence":"pos"},{"id":"toquestion","label":"Still to question","valence":"neg"}],"key":{"a":"changed","b":"toquestion","c":"changed","d":"toquestion","e":"changed","f":"toquestion"},"relearn":"Big harmful norms in India have changed; more still can.","persona":"any","source":"question-change / hope"},
  {"id":"ns-1230","cat":"question-change","type":"sort","hook":"Sort each one into 'Worth keeping' or 'Worth questioning'.","items":[{"id":"a","text":"Helping a kid who falls"},{"id":"b","text":"Serving only by gender"},{"id":"c","text":"Saying thank you to helpers"},{"id":"d","text":"Telling girls they 'can't' cycle"},{"id":"e","text":"Sharing food with neighbours"},{"id":"f","text":"Ranking sons above daughters"}],"bins":[{"id":"keep","label":"Worth keeping","valence":"pos"},{"id":"question","label":"Worth questioning","valence":"neg"}],"key":{"a":"keep","b":"question","c":"keep","d":"question","e":"keep","f":"question"},"relearn":"Keep the helpful norms; question the ones that limit or rank a group.","persona":"any","source":"question-change / sort"},
  {"id":"ns-1231","cat":"question-change","type":"match","hook":"Match each pushback to a kind, fair reply.","pairs":[{"left":"\"Log kya kahenge?\"","right":"\"Maybe they'll learn something.\""},{"left":"\"Good girls don't argue.\"","right":"\"I'm not arguing, just asking.\""},{"left":"\"That's just our culture.\"","right":"\"I love it; I want it fair.\""},{"left":"\"You're only a child.\"","right":"\"My fair question counts.\""},{"left":"\"Everyone does it.\"","right":"\"I'd rather be fair.\""}],"relearn":"Each pushback has a calm, fair answer that stays warm.","persona":"Diya","source":"question-change / voice"},
  {"id":"ns-1232","cat":"question-change","type":"match","hook":"Match each harmful norm to the fairer version you could propose.","pairs":[{"left":"Only girls clear the plates","right":"Everyone shares the clearing-up"},{"left":"Boys are served food first","right":"All are served together"},{"left":"Girls can't cycle to school","right":"Anyone can cycle to school"},{"left":"Boys must never cry","right":"Feelings are okay for everyone"},{"left":"Sons' wishes come first","right":"Daughters and sons get equal say"}],"relearn":"For each harmful norm there's a fairer one you can warmly propose.","persona":"any","source":"question-change / propose"},
  {"id":"ns-1233","cat":"question-change","type":"match","hook":"Match each step of starting change to what it looks like.","pairs":[{"left":"Notice the unfair norm","right":"\"Hey, only boys get picked here.\""},{"left":"Ask a kind question","right":"\"Could we choose on skill instead?\""},{"left":"Model the fairer way","right":"You share the chore yourself"},{"left":"Find others","right":"A friend agrees and joins in"},{"left":"Keep it going","right":"You gently encourage the new habit"}],"relearn":"Change has small steps: notice, ask, model, team up, keep going.","persona":"Asha","source":"question-change / steps"},
  {"id":"ns-1234","cat":"question-change","type":"match","hook":"Match each myth about questioning to the truth that answers it.","pairs":[{"left":"Questioning is disrespect","right":"Respect and fair questions go together"},{"left":"One kid can't change anything","right":"Change can start with one voice"},{"left":"Staying quiet is harmless","right":"Silence helps a harmful norm survive"},{"left":"Common means fair","right":"Common doesn't make a norm fair"},{"left":"Old means right","right":"Even old norms can be wrong and change"}],"relearn":"Every myth about questioning has a fair answer.","persona":"any","source":"question-change / myths"},
  {"id":"ns-1235","cat":"question-change","type":"match","hook":"Match each person to a fair line they could say.","pairs":[{"left":"A girl told 'don't argue'","right":"\"I'm asking, not arguing.\""},{"left":"A boy teased for crying","right":"\"Feelings are fine for anyone.\""},{"left":"A dad told 'men don't cook'","right":"\"Cooking's a useful skill.\""},{"left":"A kid told to exclude a friend","right":"\"Let's make space for her.\""},{"left":"A child waved off as 'too young'","right":"\"My fair point counts.\""}],"relearn":"Anyone can find a calm, fair line to question a norm.","persona":"any","source":"question-change / voice"},
  {"id":"ns-1236","cat":"question-change","type":"match","hook":"Match each 'log kya kahenge' worry to a fair comeback.","pairs":[{"left":"\"People will gossip if you play.\"","right":"\"Playing is fair.\""},{"left":"\"Relatives will judge you.\"","right":"\"I'm building my future.\""},{"left":"\"Neighbours will talk if Papa cooks.\"","right":"\"Cooking is nice.\""},{"left":"\"What will the village say?\"","right":"\"They may see a fairer way.\""},{"left":"\"You'll shame us by asking.\"","right":"\"Asking fairly honours us.\""}],"relearn":"You can answer 'what will people say?' and still choose fairness.","persona":"Diya","source":"question-change / log kya kahenge"},
  {"id":"ns-1237","cat":"question-change","type":"match","hook":"Match each changed norm to who quietly started it.","pairs":[{"left":"Girls began going to school","right":"Families who asked 'why not ours?'"},{"left":"Widows could remarry","right":"People who called the ban unfair"},{"left":"Boys share chores","right":"Homes that split work fairly"},{"left":"Mixed teams play","right":"Kids who asked all to join"},{"left":"Dowry seen as wrong","right":"People who refused to expect it"}],"relearn":"Big norms changed because people quietly questioned and acted.","persona":"Asha","source":"question-change / hope"},
  {"id":"ns-1238","cat":"question-change","type":"match","hook":"Match each tricky phrase to a question that tests it.","pairs":[{"left":"\"It's always been this way.\"","right":"\"Is it actually fair?\""},{"left":"\"It's our tradition.\"","right":"\"Is it kind to everyone?\""},{"left":"\"Everyone does it.\"","right":"\"Does common mean fair?\""},{"left":"\"You're too young to ask.\"","right":"\"Doesn't a fair question count?\""},{"left":"\"Elders know best.\"","right":"\"Can I respect them and still ask?\""}],"relearn":"'Always been this way' isn't a reason; test each norm for fairness.","persona":"any","source":"question-change / test"},
  {"id":"ns-1260","cat":"what-is-a-norm","type":"reflect","hook":"Lensy: a norm is a rule no one wrote down, but everyone in a group just follows. Spotted one today?","prompt":"What do you think?","options":["Maybe","I'll watch for them","They're everywhere"],"affirm":"Once you notice them, you see unwritten norms all day long.","relearn":"A norm is an unwritten rule a group treats as normal.","persona":"any","source":"framing"},
  {"id":"ns-1261","cat":"what-is-a-norm","type":"reflect","hook":"Lensy: nobody printed 'greet elders first', yet most homes do it. Funny how that works?","prompt":"What do you think?","options":["True","Never noticed","Makes sense"],"affirm":"Norms spread by example, not by being written anywhere.","relearn":"Norms are passed on by watching, not by rulebooks.","persona":"any","source":"framing"},
  {"id":"ns-1262","cat":"what-is-a-norm","type":"reflect","hook":"Diya: at home, the eldest is served food first, no one ever said to. Is that a rule or a norm?","prompt":"What do you think?","options":["A norm","Just a habit","I'd call it both"],"affirm":"It's an unwritten norm, a quiet rule the family just follows.","relearn":"Unwritten 'this is how we do it' habits are norms.","persona":"Diya","source":"observation"},
  {"id":"ns-1263","cat":"what-is-a-norm","type":"reflect","hook":"Lensy: a fact is true everywhere; a norm can change as you cross a state line. Both feel 'normal', though.","prompt":"What do you think?","options":["Interesting","I see the difference","Tell me more"],"affirm":"That swap test, does it change by place, helps tell a norm from a fact.","relearn":"Facts hold everywhere; norms shift by place and time.","persona":"any","source":"framing"},
  {"id":"ns-1264","cat":"what-is-a-norm","type":"reflect","hook":"Lensy: 'everyone does it' tells you a norm is common, not that it's fair. Two different things, na?","prompt":"What do you think?","options":["Two different things","I get it","Worth remembering"],"affirm":"Common just means lots of people; fair is a separate question you can still ask.","relearn":"A norm being common doesn't make it fair.","persona":"any","source":"critical thinking"},
  {"id":"ns-1265","cat":"what-is-a-norm","type":"reflect","hook":"Lensy: some norms help, some harm, most are just habits. The skill is checking each one, not trusting all.","prompt":"What do you think?","options":["Check each one","Sounds fair","I'm in"],"affirm":"A norm detective tests each norm instead of swallowing the whole storm.","relearn":"Norms can help or harm; it's worth checking which.","persona":"any","source":"framing"},
  {"id":"ns-1266","cat":"what-is-a-norm","type":"reflect","hook":"Aarav: 'be a man' isn't written in any book, yet boys hear it everywhere. Is that a norm?","prompt":"What do you think?","options":["Yes, a norm","Never thought so","I think so"],"affirm":"Right, it's an unwritten norm, not a fact about boys.","relearn":"'Be a man' is a norm people made, not a law of nature.","persona":"Aarav","source":"observation"},
  {"id":"ns-1267","cat":"what-is-a-norm","type":"reflect","hook":"Asha: people made every norm around you, which means people can also change them. Heavy idea?","prompt":"What do you think?","options":["A bit","I like it","Makes me think"],"affirm":"If people built it, people can rebuild it, that's how change starts.","relearn":"What people made, people can change.","persona":"Asha","source":"framing"},
  {"id":"ns-1268","cat":"what-is-a-norm","type":"reflect","hook":"Lensy: a law is written and has consequences; a norm is just 'how we do things'. Easy to mix up?","prompt":"What do you think?","options":["A little","I can tell them apart","Tricky sometimes"],"affirm":"If it's printed with a penalty it's a law; if it's just expected, it's a norm.","relearn":"Laws are written with consequences; norms are unwritten.","persona":"any","source":"concept"},
  {"id":"ns-1269","cat":"what-is-a-norm","type":"reflect","hook":"Lensy: norms aren't carved in stone, plenty of old Indian norms have already changed. Surprising?","prompt":"What do you think?","options":["A bit","Good to know","Tell me more"],"affirm":"Norms have a history, and a history means they can shift again.","relearn":"Even very old norms can and do change.","persona":"any","source":"framing"},
  {"id":"ns-1270","cat":"what-is-a-norm","type":"reflect","hook":"Diya: I like sitting by the window, my cousin doesn't. That's not a norm, is it?","prompt":"What do you think?","options":["No, that's a taste","Right","Just your liking"],"affirm":"A liking that's only yours is a taste; a norm is shared by the whole group.","relearn":"A norm is shared by a group; a taste is just yours.","persona":"Diya","source":"observation"},
  {"id":"ns-1271","cat":"what-is-a-norm","type":"reflect","hook":"Lensy: ever notice you queue, greet, take shoes off, all without being told once today? Those are norms.","prompt":"What do you think?","options":["Whoa, true","I do that","Norms everywhere"],"affirm":"Half your day runs on unwritten norms you never had to be taught with words.","relearn":"Lots of everyday behaviour is guided by unwritten norms.","persona":"any","source":"observation"},
  {"id":"ns-1272","cat":"what-is-a-norm","type":"sort","hook":"Sort: an unwritten norm, or a true fact?","items":[{"id":"a","text":"\"Cover your head in this temple\""},{"id":"b","text":"The Earth goes around the sun"},{"id":"c","text":"\"Eat with your right hand\""},{"id":"d","text":"Ice melts into water"},{"id":"e","text":"\"Greet guests with chai\""},{"id":"f","text":"A year has twelve months"}],"bins":[{"id":"norm","label":"Norm","valence":"tell"},{"id":"fact","label":"Fact","valence":"neutral"}],"key":{"a":"norm","b":"fact","c":"norm","d":"fact","e":"norm","f":"fact"},"relearn":"Norms are people's customs; facts are true by nature.","persona":"any","source":"concept"},
  {"id":"ns-1273","cat":"what-is-a-norm","type":"sort","hook":"Sort: a norm you can question, or a fact you just accept?","items":[{"id":"a","text":"\"Girls should learn cooking, not cricket\""},{"id":"b","text":"Plants need sunlight to grow"},{"id":"c","text":"\"Boys shouldn't wear bright colours\""},{"id":"d","text":"Salt dissolves in water"},{"id":"e","text":"\"A bride must be quiet and shy\""},{"id":"f","text":"Sound travels through air"}],"bins":[{"id":"norm","label":"Norm (can question)","valence":"tell"},{"id":"fact","label":"Fact (just true)","valence":"neutral"}],"key":{"a":"norm","b":"fact","c":"norm","d":"fact","e":"norm","f":"fact"},"relearn":"You can question a norm; a fact is simply true.","persona":"any","source":"concept"},
  {"id":"ns-1274","cat":"what-is-a-norm","type":"sort","hook":"Sort: a written law, or an unwritten norm?","items":[{"id":"a","text":"\"Children must go to school\""},{"id":"b","text":"\"The bride's family hosts the wedding\""},{"id":"c","text":"\"Don't drive without a licence\""},{"id":"d","text":"\"Sons light the lamp on festivals\""},{"id":"e","text":"\"No firecrackers after the night limit\""},{"id":"f","text":"\"Save the last roti for a guest\""}],"bins":[{"id":"law","label":"Law","valence":"neutral"},{"id":"norm","label":"Norm","valence":"tell"}],"key":{"a":"law","b":"norm","c":"law","d":"norm","e":"law","f":"norm"},"relearn":"Laws are written and enforced; norms are just expected.","persona":"any","source":"concept"},
  {"id":"ns-1275","cat":"what-is-a-norm","type":"sort","hook":"Sort: a shared norm everyone follows, or just one person's taste?","items":[{"id":"a","text":"People remove footwear at the door"},{"id":"b","text":"Riya only likes filter coffee"},{"id":"c","text":"Guests are offered water first"},{"id":"d","text":"Sameer hates the colour yellow"},{"id":"e","text":"Neighbours share sweets at Diwali"},{"id":"f","text":"You like your dosa extra crispy"}],"bins":[{"id":"norm","label":"Shared norm","valence":"tell"},{"id":"taste","label":"Personal taste","valence":"neutral"}],"key":{"a":"norm","b":"taste","c":"norm","d":"taste","e":"norm","f":"taste"},"relearn":"A norm is shared by a group; a taste is just one person's.","persona":"any","source":"concept"},
  {"id":"ns-1276","cat":"what-is-a-norm","type":"sort","hook":"Sort: made by people (a norm), or fixed by nature (a fact)?","items":[{"id":"a","text":"\"Blue is a boy's colour\""},{"id":"b","text":"Iron is heavier than cotton"},{"id":"c","text":"\"Daughters move out after marriage\""},{"id":"d","text":"The sky looks blue by day"},{"id":"e","text":"\"Elders sit, youngsters serve\""},{"id":"f","text":"Fire is hot to touch"}],"bins":[{"id":"people","label":"Made by people","valence":"tell"},{"id":"nature","label":"By nature","valence":"neutral"}],"key":{"a":"people","b":"nature","c":"people","d":"nature","e":"people","f":"nature"},"relearn":"Norms are human-made; facts are set by nature.","persona":"any","source":"concept"},
  {"id":"ns-1277","cat":"what-is-a-norm","type":"sort","hook":"Sort: changes from place to place (norm), or the same everywhere (fact)?","items":[{"id":"a","text":"How you greet a stranger"},{"id":"b","text":"That water boils when heated enough"},{"id":"c","text":"What clothes count as 'formal'"},{"id":"d","text":"That magnets attract iron"},{"id":"e","text":"Whether you bargain at a shop"},{"id":"f","text":"That seeds grow into plants"}],"bins":[{"id":"varies","label":"Varies by place","valence":"tell"},{"id":"same","label":"Same everywhere","valence":"neutral"}],"key":{"a":"varies","b":"same","c":"varies","d":"same","e":"varies","f":"same"},"relearn":"Norms change with place; facts stay the same everywhere.","persona":"any","source":"concept"},
  {"id":"ns-1278","cat":"what-is-a-norm","type":"sort","hook":"Sort: just a common norm, or actually fair too?","items":[{"id":"a","text":"\"Everyone queues for their turn\""},{"id":"b","text":"\"Only girls clear the plates\""},{"id":"c","text":"\"We thank people who help us\""},{"id":"d","text":"\"Boys get the bigger share of milk\""},{"id":"e","text":"\"We don't litter the street\""},{"id":"f","text":"\"Girls eat after the boys\""}],"bins":[{"id":"fair","label":"Common and fair","valence":"pos"},{"id":"unfair","label":"Common but unfair","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"A norm being common doesn't make it fair, check both.","persona":"any","source":"critical thinking"},
  {"id":"ns-1279","cat":"what-is-a-norm","type":"sort","hook":"Sort: a norm you could change, or a fact you can't?","items":[{"id":"a","text":"\"Mehndi is only for girls\""},{"id":"b","text":"The sun is hotter than the moon"},{"id":"c","text":"\"Loud girls are 'badtameez'\""},{"id":"d","text":"Birds have feathers"},{"id":"e","text":"\"Boys mustn't help in the kitchen\""},{"id":"f","text":"Rivers flow to the sea"}],"bins":[{"id":"norm","label":"Norm (changeable)","valence":"tell"},{"id":"fact","label":"Fact (fixed)","valence":"neutral"}],"key":{"a":"norm","b":"fact","c":"norm","d":"fact","e":"norm","f":"fact"},"relearn":"Norms can change; facts of nature can't.","persona":"any","source":"concept"},
  {"id":"ns-1280","cat":"what-is-a-norm","type":"sort","hook":"Sort: an unwritten norm at home, or a written rule from school?","items":[{"id":"a","text":"\"Take blessings before an exam\""},{"id":"b","text":"\"Wear the school uniform\""},{"id":"c","text":"\"Don't start eating before elders\""},{"id":"d","text":"\"Submit homework by Monday\""},{"id":"e","text":"\"Take your shoes off at the temple\""},{"id":"f","text":"\"No running in the corridor\""}],"bins":[{"id":"norm","label":"Unwritten norm","valence":"tell"},{"id":"rule","label":"Written rule","valence":"neutral"}],"key":{"a":"norm","b":"rule","c":"norm","d":"rule","e":"norm","f":"rule"},"relearn":"Homes run on norms; schools also have written rules.","persona":"any","source":"concept"},
  {"id":"ns-1281","cat":"what-is-a-norm","type":"sort","hook":"Sort: a norm (a group habit), or a taste (your own liking)?","items":[{"id":"a","text":"Folding hands to say namaste"},{"id":"b","text":"Loving spicy food more than sweet"},{"id":"c","text":"Saving a seat for an elder on the bus"},{"id":"d","text":"Preferring blue over green"},{"id":"e","text":"Wishing neighbours on festivals"},{"id":"f","text":"Liking cricket more than football"}],"bins":[{"id":"norm","label":"Group norm","valence":"tell"},{"id":"taste","label":"Personal taste","valence":"neutral"}],"key":{"a":"norm","b":"taste","c":"norm","d":"taste","e":"norm","f":"taste"},"relearn":"Norms are shared group habits; tastes are personal.","persona":"any","source":"concept"},
  {"id":"ns-1282","cat":"what-is-a-norm","type":"sort","hook":"Sort: a kind norm that helps, or a harmful norm that limits a group?","items":[{"id":"a","text":"\"Offer your seat to someone older\""},{"id":"b","text":"\"Girls don't go out after dark\""},{"id":"c","text":"\"Wash hands before eating\""},{"id":"d","text":"\"Boys must never cry\""},{"id":"e","text":"\"Greet a guest warmly\""},{"id":"f","text":"\"Daughters need less schooling\""}],"bins":[{"id":"helps","label":"Helps everyone","valence":"pos"},{"id":"limits","label":"Limits a group","valence":"neg"}],"key":{"a":"helps","b":"limits","c":"helps","d":"limits","e":"helps","f":"limits"},"relearn":"Some norms help everyone; harmful ones limit one group.","persona":"any","source":"concept"},
  {"id":"ns-1283","cat":"what-is-a-norm","type":"sort","hook":"Sort: a rule that's really a norm, or one that's really a law?","items":[{"id":"a","text":"\"Bring a gift to a housewarming\""},{"id":"b","text":"\"Stop at a railway level crossing\""},{"id":"c","text":"\"Younger ones touch elders' feet\""},{"id":"d","text":"\"Wear a helmet while riding\""},{"id":"e","text":"\"Don't whistle indoors at night\""},{"id":"f","text":"\"Send children to school\""}],"bins":[{"id":"norm","label":"Norm","valence":"tell"},{"id":"law","label":"Law","valence":"neutral"}],"key":{"a":"norm","b":"law","c":"norm","d":"law","e":"norm","f":"law"},"relearn":"Some 'rules' are just norms; others are real laws.","persona":"any","source":"concept"},
  {"id":"ns-1284","cat":"what-is-a-norm","type":"sort","hook":"Sort: a real fact, or just a norm people call 'natural'?","items":[{"id":"a","text":"Cows eat grass"},{"id":"b","text":"\"Cooking is naturally a woman's job\""},{"id":"c","text":"The moon has no light of its own"},{"id":"d","text":"\"Boys are naturally braver\""},{"id":"e","text":"Honey comes from bees"},{"id":"f","text":"\"Girls are naturally shy\""}],"bins":[{"id":"fact","label":"Real fact","valence":"neutral"},{"id":"normfake","label":"Norm dressed as 'natural'","valence":"neg"}],"key":{"a":"fact","b":"normfake","c":"fact","d":"normfake","e":"fact","f":"normfake"},"relearn":"Calling a norm 'natural' doesn't make it a fact.","persona":"any","source":"critical thinking"},
  {"id":"ns-1285","cat":"what-is-a-norm","type":"sort","hook":"Sort: this came from people and history, or it's true by nature?","items":[{"id":"a","text":"\"Brides wear red\""},{"id":"b","text":"Rain comes from clouds"},{"id":"c","text":"\"Boys get the family name\""},{"id":"d","text":"Apples fall to the ground"},{"id":"e","text":"\"We don't sweep after dark\""},{"id":"f","text":"Day follows night"}],"bins":[{"id":"people","label":"From people","valence":"tell"},{"id":"nature","label":"By nature","valence":"neutral"}],"key":{"a":"people","b":"nature","c":"people","d":"nature","e":"people","f":"nature"},"relearn":"Norms come from people and history, not from nature.","persona":"any","source":"concept"},
  {"id":"ns-1286","cat":"what-is-a-norm","type":"sort","hook":"Sort: a habit that's just yours, or a norm your whole group shares?","items":[{"id":"a","text":"You read before sleeping"},{"id":"b","text":"Everyone removes shoes at the mandir"},{"id":"c","text":"You drink water from a steel glass"},{"id":"d","text":"Guests are seated before they're served"},{"id":"e","text":"You hum while studying"},{"id":"f","text":"People stand for a passing elder"}],"bins":[{"id":"own","label":"Just your habit","valence":"neutral"},{"id":"norm","label":"A group norm","valence":"tell"}],"key":{"a":"own","b":"norm","c":"own","d":"norm","e":"own","f":"norm"},"relearn":"A private habit is yours; a norm is shared by the group.","persona":"any","source":"concept"},
  {"id":"ns-1287","cat":"what-is-a-norm","type":"sort","hook":"Sort: a norm that's lasted but is fair, or one that's lasted but is unfair?","items":[{"id":"a","text":"\"Welcome guests with warmth\""},{"id":"b","text":"\"A girl's job is to adjust\""},{"id":"c","text":"\"Respect every elder\""},{"id":"d","text":"\"Sons inherit, daughters don't\""},{"id":"e","text":"\"Help a neighbour in need\""},{"id":"f","text":"\"Girls shouldn't laugh loudly\""}],"bins":[{"id":"fair","label":"Old and fair","valence":"pos"},{"id":"unfair","label":"Old but unfair","valence":"neg"}],"key":{"a":"fair","b":"unfair","c":"fair","d":"unfair","e":"fair","f":"unfair"},"relearn":"Being old doesn't make a norm fair, test each one.","persona":"any","source":"critical thinking"},
  {"id":"ns-1288","cat":"what-is-a-norm","type":"sort","hook":"Sort: an unwritten norm, or a personal choice that's only yours?","items":[{"id":"a","text":"Saying 'sorry' when you bump someone"},{"id":"b","text":"Choosing chess as your hobby"},{"id":"c","text":"Offering food before you eat alone"},{"id":"d","text":"Liking long hair on yourself"},{"id":"e","text":"Letting elders speak first"},{"id":"f","text":"Preferring to walk over cycle"}],"bins":[{"id":"norm","label":"Shared norm","valence":"tell"},{"id":"choice","label":"Personal choice","valence":"neutral"}],"key":{"a":"norm","b":"choice","c":"norm","d":"choice","e":"norm","f":"choice"},"relearn":"Norms are shared; personal choices are yours alone.","persona":"any","source":"concept"},
  {"id":"ns-1289","cat":"what-is-a-norm","type":"sort","hook":"Sort: same in every country (fact), or different country to country (norm)?","items":[{"id":"a","text":"How close you stand when talking"},{"id":"b","text":"That gravity pulls things down"},{"id":"c","text":"Whether you tip at a restaurant"},{"id":"d","text":"That the heart pumps blood"},{"id":"e","text":"Which side of the road you drive on"},{"id":"f","text":"That oxygen is in the air"}],"bins":[{"id":"varies","label":"Differs by country (norm)","valence":"tell"},{"id":"same","label":"Same everywhere (fact)","valence":"neutral"}],"key":{"a":"varies","b":"same","c":"varies","d":"same","e":"varies","f":"same"},"relearn":"Norms differ across countries; facts hold everywhere.","persona":"any","source":"concept"},
  {"id":"ns-1290","cat":"what-is-a-norm","type":"sort","hook":"Sort: a norm we'd keep, or a norm worth questioning?","items":[{"id":"a","text":"\"Ask before you borrow\""},{"id":"b","text":"\"Girls serve, boys are served\""},{"id":"c","text":"\"Say thank you for a gift\""},{"id":"d","text":"\"Boys don't show fear\""},{"id":"e","text":"\"Keep shared spaces clean\""},{"id":"f","text":"\"Daughters belong to another home\""}],"bins":[{"id":"keep","label":"Worth keeping","valence":"pos"},{"id":"question","label":"Worth questioning","valence":"uhoh"}],"key":{"a":"keep","b":"question","c":"keep","d":"question","e":"keep","f":"question"},"relearn":"Keep the helpful norms; question the harmful ones.","persona":"any","source":"framing"},
  {"id":"ns-1291","cat":"what-is-a-norm","type":"sort","hook":"Sort: a written school rule, or an unwritten classroom norm?","items":[{"id":"a","text":"\"Raise your hand to speak\""},{"id":"b","text":"\"Let the new student sit with you\""},{"id":"c","text":"\"Carry your ID card daily\""},{"id":"d","text":"\"Share your eraser if a friend asks\""},{"id":"e","text":"\"No mobile phones in class\""},{"id":"f","text":"\"Don't laugh at a wrong answer\""}],"bins":[{"id":"rule","label":"Written rule","valence":"neutral"},{"id":"norm","label":"Unwritten norm","valence":"tell"}],"key":{"a":"rule","b":"norm","c":"rule","d":"norm","e":"rule","f":"norm"},"relearn":"Classrooms have written rules and unwritten norms both.","persona":"any","source":"concept"},
  {"id":"ns-1292","cat":"what-is-a-norm","type":"strike-rewrite","hook":"\"A norm is the same as a law, you'll get in trouble for breaking it.\"","myth":{"un":"A norm is just like a law, with the same punishment.","re":"A norm is unwritten and has no legal penalty; a law is written and enforced.","why":"You can break a norm and only get a frown; breaking a law has legal consequences."},"relearn":"Norms and laws are different; only laws are written and enforced.","persona":"any","source":"concept"},
  {"id":"ns-1293","cat":"what-is-a-norm","type":"strike-rewrite","hook":"\"If a custom is really old, it must be true and right.\"","myth":{"un":"A custom that's very old must be correct and fair.","re":"Old just means it lasted; some old norms were unfair all along.","why":"Many norms India has dropped were old too, age never proved them right."},"relearn":"Age doesn't make a norm true or fair.","persona":"any","source":"critical thinking"},
  {"id":"ns-1294","cat":"what-is-a-norm","type":"strike-rewrite","hook":"\"'Boys are tough, girls are gentle', that's just biology.\"","myth":{"un":"'Boys are tough and girls are gentle' is a fact of nature.","re":"That's a norm people teach, not a fact, kids of any gender feel both.","why":"Children learn these roles from example; they aren't fixed by nature."},"relearn":"'Boys tough, girls gentle' is a taught norm, not a fact.","persona":"any","source":"critical thinking"},
  {"id":"ns-1295","cat":"what-is-a-norm","type":"strike-rewrite","hook":"\"What's normal here is normal everywhere, that's why it's normal.\"","myth":{"un":"Whatever is normal in my town is normal across the whole world.","re":"'Normal' changes by place; a custom here can be unheard of elsewhere.","why":"Norms vary across regions and cultures, so none is normal everywhere."},"relearn":"What's 'normal' varies by place; norms aren't universal.","persona":"any","source":"concept"},
  {"id":"ns-1296","cat":"what-is-a-norm","type":"strike-rewrite","hook":"\"It's a norm, so there's nothing anyone can do about it.\"","myth":{"un":"A norm is fixed, so no one can ever change it.","re":"Norms are made by people, which means people can change them.","why":"Big norms in India have already changed when people questioned them."},"relearn":"What people made, people can change.","persona":"Asha","source":"framing"},
  {"id":"ns-1297","cat":"what-is-a-norm","type":"strike-rewrite","hook":"\"If lots of people follow a norm, that proves it's fair.\"","myth":{"un":"A norm that lots of people follow must be a fair one.","re":"Popular only means common; fairness is a separate test you still apply.","why":"Plenty of people once followed unfair norms, numbers never made them fair."},"relearn":"Common doesn't mean fair; test each norm.","persona":"any","source":"critical thinking"},
  {"id":"ns-1298","cat":"what-is-a-norm","type":"strike-rewrite","hook":"\"Your favourite food is your taste, and that's a kind of norm too.\"","myth":{"un":"A personal liking, like your favourite food, counts as a norm.","re":"A taste is just yours; a norm is something a whole group shares.","why":"Norms are shared expectations; a private liking belongs to one person."},"relearn":"A norm is shared by a group; a taste is just yours.","persona":"any","source":"concept"},
  {"id":"ns-1299","cat":"what-is-a-norm","type":"strike-rewrite","hook":"\"Nobody wrote the norm down, so it isn't really a rule at all.\"","myth":{"un":"If a norm isn't written anywhere, it isn't really a rule.","re":"Norms are unwritten rules, real ones a group follows without a page.","why":"You feel a norm when you break it and get surprised looks, no writing needed."},"relearn":"A norm is a real, unwritten rule a group follows.","persona":"any","source":"concept"},
  {"id":"ns-1300","cat":"what-is-a-norm","type":"spot","hook":"A school morning. Spot the two unwritten norms.","scene":[{"id":"a","text":"Children touch elders' feet before leaving","trick":true},{"id":"b","text":"Students greet the teacher as she enters","trick":true},{"id":"c","text":"The bell rings at eight","trick":false},{"id":"d","text":"The bags are cloth","trick":false},{"id":"e","text":"The board is green","trick":false}],"why":"Touching feet and greeting the teacher are norms. The bell, bags and board are just things.","relearn":"Norms are 'how we behave', not the objects around us.","persona":"any","source":"observation"},
  {"id":"ns-1301","cat":"what-is-a-norm","type":"spot","hook":"At a family dinner. Spot the unwritten norms.","scene":[{"id":"a","text":"The eldest is served first","trick":true},{"id":"b","text":"No one starts until grandfather begins","trick":true},{"id":"c","text":"The dal is yellow","trick":false},{"id":"d","text":"There are six plates on the table","trick":false},{"id":"e","text":"The fan is on","trick":false}],"why":"Serving the eldest first and waiting for grandfather are norms the family just follows. The colour of the dal, the plate count and the fan are not norms.","relearn":"Norms guide who does what; they aren't the food or furniture.","persona":"any","source":"observation"},
  {"id":"ns-1302","cat":"what-is-a-norm","type":"spot","hook":"At a bus stop. Spot the unwritten norms at work.","scene":[{"id":"a","text":"People let an elderly woman board first","trick":true},{"id":"b","text":"A boy gives up his seat for a pregnant lady","trick":true},{"id":"c","text":"The bus is painted blue","trick":false},{"id":"d","text":"It's a hot afternoon","trick":false},{"id":"e","text":"The bus has four wheels","trick":false}],"why":"Letting an elder board first and giving up a seat are kind norms people follow. The bus colour, the weather and the wheels aren't norms.","relearn":"Norms are how people treat each other, not the objects nearby.","persona":"any","source":"observation"},
  {"id":"ns-1303","cat":"what-is-a-norm","type":"spot","hook":"At a temple. Spot the unwritten norms.","scene":[{"id":"a","text":"People remove their footwear outside","trick":true},{"id":"b","text":"Visitors lower their voices","trick":true},{"id":"c","text":"There is a brass bell at the door","trick":false},{"id":"d","text":"The floor is made of stone","trick":false},{"id":"e","text":"Flowers are sold nearby","trick":false}],"why":"Removing footwear and speaking softly are norms everyone follows here. The bell, the stone floor and the flower stall are just part of the place.","relearn":"Norms are the shared behaviour, not the building or its objects.","persona":"any","source":"observation"},
  {"id":"ns-1304","cat":"what-is-a-norm","type":"spot","hook":"Spot which two of these are norms (the rest are plain facts).","scene":[{"id":"a","text":"\"We bring sweets when we visit someone\"","trick":true},{"id":"b","text":"\"We call older cousins 'didi' or 'bhaiya'\"","trick":true},{"id":"c","text":"Water is wet","trick":false},{"id":"d","text":"The sun gives heat","trick":false},{"id":"e","text":"Stones sink in water","trick":false}],"why":"Bringing sweets and using 'didi'/'bhaiya' are unwritten norms. Water being wet, the sun's heat and sinking stones are facts of nature, not norms.","relearn":"Norms are customs people choose; facts are true by nature.","persona":"any","source":"concept"},
  {"id":"ns-1305","cat":"what-is-a-norm","type":"spot","hook":"Diya's house. Spot the two harmful norms among the kind ones.","scene":[{"id":"a","text":"\"Diya eats after her brother\"","trick":true},{"id":"b","text":"\"Diya can't cycle, she's 'a big girl' now\"","trick":true},{"id":"c","text":"\"Everyone washes hands first\"","trick":false},{"id":"d","text":"\"Guests get water first\"","trick":false},{"id":"e","text":"\"We thank the cook\"","trick":false}],"why":"Serving Diya last and banning her cycle limit her by gender. Washing hands, offering water and thanking the cook are kind norms.","relearn":"A norm that limits one gender is harmful, worth questioning.","persona":"Diya","source":"observation"},
  {"id":"ns-1306","cat":"what-is-a-norm","type":"spot","hook":"Spot the two unwritten norms; the rest are written rules.","scene":[{"id":"a","text":"\"Give up the seat for grandparents\"","trick":true},{"id":"b","text":"\"Don't point your feet at elders\"","trick":true},{"id":"c","text":"\"Wear your seatbelt\"","trick":false},{"id":"d","text":"\"Carry your driving licence\"","trick":false},{"id":"e","text":"\"Stop at the red signal\"","trick":false}],"why":"Giving up a seat and not pointing feet at elders are norms. Seatbelts, licences and red signals are written rules.","relearn":"Norms are unwritten; written rules and laws are different.","persona":"any","source":"concept"},
  {"id":"ns-1307","cat":"what-is-a-norm","type":"spot","hook":"Spot the two 'facts' that are really just norms in disguise.","scene":[{"id":"a","text":"\"Girls are naturally neater\"","trick":true},{"id":"b","text":"\"Boys are born leaders\"","trick":true},{"id":"c","text":"Plants make their own food in sunlight","trick":false},{"id":"d","text":"Metal expands when heated","trick":false},{"id":"e","text":"The Earth spins once a day","trick":false}],"why":"'Girls are neater' and 'boys are leaders' are norms people teach, dressed up as facts. The other three are real science facts.","relearn":"A norm called 'natural' is still a norm, not a fact.","persona":"any","source":"critical thinking"},
  {"id":"ns-1308","cat":"what-is-a-norm","type":"match","hook":"Match each example to what kind of 'rule' it is.","pairs":[{"left":"\"Greet elders first\"","right":"An unwritten norm"},{"left":"\"Wear a seatbelt\"","right":"A written law"},{"left":"\"Water boils when heated\"","right":"A fact of nature"},{"left":"\"You love rainy days\"","right":"A personal taste"},{"left":"\"You bite your nails\"","right":"A private habit"}],"relearn":"Norm, law, fact, taste and habit are five different things.","persona":"any","source":"vocabulary"},
  {"id":"ns-1309","cat":"what-is-a-norm","type":"match","hook":"Match each norm to where we usually meet it.","pairs":[{"left":"Taking shoes off","right":"At a temple or home"},{"left":"Standing in a queue","right":"At a ticket counter"},{"left":"Touching elders' feet","right":"At a family gathering"},{"left":"Lowering your voice","right":"In a library"},{"left":"Letting elders board first","right":"On a crowded bus"}],"relearn":"Norms live in places; each setting has its own.","persona":"any","source":"observation"},
  {"id":"ns-1310","cat":"what-is-a-norm","type":"match","hook":"Match the everyday word to its plain meaning.","pairs":[{"left":"Unwritten","right":"Not printed down anywhere"},{"left":"Custom","right":"A norm a community keeps"},{"left":"Common","right":"Followed by many people"},{"left":"Fair","right":"Kind to everyone, both ways"},{"left":"Question it","right":"Ask if it's truly right"}],"relearn":"Knowing these words helps you talk about norms clearly.","persona":"any","source":"vocabulary"},
  {"id":"ns-1311","cat":"what-is-a-norm","type":"match","hook":"Match each norm to the place where it changes.","pairs":[{"left":"Which hand to eat with","right":"Differs across regions"},{"left":"How you greet someone","right":"Differs across countries"},{"left":"What 'on time' means","right":"Differs across cultures"},{"left":"What clothes are 'formal'","right":"Differs across occasions"},{"left":"Whether you bargain","right":"Differs across markets"}],"relearn":"Norms shift from place to place; that's how you spot them.","persona":"any","source":"concept"},
  {"id":"ns-1312","cat":"what-is-a-norm","type":"match","hook":"Match each statement to why it's a norm or a fact.","pairs":[{"left":"\"Brides wear red\"","right":"A custom people chose"},{"left":"\"Ice is colder than steam\"","right":"True by physics"},{"left":"\"Sons carry the family name\"","right":"A rule families made up"},{"left":"\"The sun is a star\"","right":"True by science"},{"left":"\"Guests come bearing gifts\"","right":"A habit a community keeps"}],"relearn":"Norms are human-made; facts are set by nature.","persona":"any","source":"concept"},
  {"id":"ns-1313","cat":"what-is-a-norm","type":"match","hook":"Match each harmful norm to the gentle, fair version.","pairs":[{"left":"\"Girls eat last\"","right":"\"Everyone eats together\""},{"left":"\"Boys mustn't cry\"","right":"\"Anyone can have feelings\""},{"left":"\"Daughters need less school\"","right":"\"Every child learns fully\""},{"left":"\"Cooking is a girl's job\"","right":"\"Everyone shares the cooking\""},{"left":"\"Only sons inherit\"","right":"\"Children share equally\""}],"relearn":"A harmful norm can be flipped to a fair one.","persona":"any","source":"framing"},
  {"id":"ns-1314","cat":"what-is-a-norm","type":"role-play","hook":"Your little cousin asks: \"What even is a norm?\" Pick the clearest way to explain.","setup":"You're the big kid now. Explain a norm in words a younger cousin gets.","yourLine":[{"text":"\"It's an unwritten rule a group just follows, like taking shoes off at home.\"","best":true},{"text":"\"It's a law, you get punished if you break it.\""},{"text":"\"It's just a fact, like water being wet.\""}],"relearn":"A norm is an unwritten rule a group follows.","persona":"any","source":"concept"},
  {"id":"ns-1315","cat":"what-is-a-norm","type":"role-play","hook":"A friend says \"queuing is a law\". Pick the line that gently sets it straight.","setup":"Your friend mixes up norms and laws. Help, without sounding bossy.","yourLine":[{"text":"\"It's actually a norm, no law makes us queue, we just all agree to.\"","best":true},{"text":"\"Yeah, totally a law, you'd be arrested for jumping the line.\""},{"text":"\"Who cares, it's the same thing anyway.\""}],"relearn":"Queuing is a norm, not a law; no penalty makes us do it.","persona":"any","source":"concept"},
  {"id":"ns-1316","cat":"what-is-a-norm","type":"role-play","hook":"Someone says \"that's just how it's always been\". Pick the calm, curious reply.","setup":"You want to show a norm can be questioned, kindly, not rudely.","yourLine":[{"text":"\"People made it, so maybe we can ask if it's still fair?\"","best":true},{"text":"\"That's a silly reason, you're all wrong.\""},{"text":"\"Okay, then I'll never ask anything.\""}],"relearn":"'It's always been this way' isn't a reason; you can still ask.","persona":"any","source":"framing"},
  {"id":"ns-1317","cat":"what-is-a-norm","type":"role-play","hook":"Aarav says \"'be a man' is just true\". Pick the line that names it as a norm.","setup":"You want to show Aarav 'be a man' is a norm, not a fact, without mocking him.","yourLine":[{"text":"\"It's a norm people teach, not a fact, boys feel things too.\"","best":true},{"text":"\"You're so weak for even saying that.\""},{"text":"\"Yeah, real men never feel anything, ever.\""}],"relearn":"'Be a man' is a taught norm, not a fact about boys.","persona":"Aarav","source":"critical thinking"},
  {"id":"ns-1318","cat":"what-is-a-norm","type":"role-play","hook":"A cousin says \"if everyone does it, it's right\". Pick the thoughtful reply.","setup":"You want to separate 'common' from 'fair', calmly.","yourLine":[{"text":"\"Common just means lots of people, we can still ask if it's fair.\"","best":true},{"text":"\"No, everyone is always wrong about everything.\""},{"text":"\"Fine, whatever's popular must be perfect.\""}],"relearn":"Common doesn't mean fair; you can still ask the question.","persona":"any","source":"critical thinking"},
  {"id":"ns-1319","cat":"what-is-a-norm","type":"role-play","hook":"Diya is asked \"isn't a norm the same as a fact?\" Pick the clear answer.","setup":"Diya explains the difference to a classmate during a project.","yourLine":[{"text":"\"No, a fact is true everywhere; a norm changes from place to place.\"","best":true},{"text":"\"They're exactly the same, don't worry about it.\""},{"text":"\"A norm is a fact you can't ever change.\""}],"relearn":"A fact is true everywhere; a norm varies by place.","persona":"Diya","source":"concept"},
  {"id":"ns-1320","cat":"what-is-a-norm","type":"role-play","hook":"A friend asks \"so are all norms bad then?\" Pick the balanced reply.","setup":"You explain that the game sorts norms, it doesn't trash them all.","yourLine":[{"text":"\"No, some norms help everyone, the trick is checking each one.\"","best":true},{"text":"\"Yes, every norm is terrible, throw them all out.\""},{"text":"\"No, every norm is perfect, never question any.\""}],"relearn":"Not all norms are bad; check each one, keep the helpful.","persona":"any","source":"framing"},
  {"id":"ns-1321","cat":"what-is-a-norm","type":"role-play","hook":"Asha is asked \"can a norm really change?\" Pick the line that gives honest hope.","setup":"Asha answers a kid who thinks norms are stuck forever.","yourLine":[{"text":"\"People made them, so people can change them, India's already changed many.\"","best":true},{"text":"\"No, norms are stuck forever, don't bother trying.\""},{"text":"\"Only grown-ups in big offices can change anything.\""}],"relearn":"What people made, people can change.","persona":"Asha","source":"framing"},
  {"id":"ns-1322","cat":"what-is-a-norm","type":"branch","hook":"Teacher asks: is 'girls sit in the back row' a fact or a norm?","options":[{"text":"\"A norm, people made it, so it can change.\"","consequence":"The class sees it isn't nature; a few rethink it.","best":true},{"text":"\"A fact, that's just how girls are.\"","consequence":"A made-up rule gets sold as nature."},{"text":"Stay quiet, everyone sits that way.","consequence":"The norm carries on unquestioned."}],"debrief":"It's a norm people made, not a fact, so it can change.","relearn":"A seating rule is a norm, not a fact of nature.","persona":"any","source":"critical thinking"},
  {"id":"ns-1323","cat":"what-is-a-norm","type":"branch","hook":"A friend says \"touching elders' feet is a law, you'll be fined.\"","options":[{"text":"\"It's a respected norm, not a law, no fine exists.\"","consequence":"Your friend tells a custom from a law.","best":true},{"text":"Agree, say they'll be fined too.","consequence":"A false 'law' scares people."},{"text":"\"Norms and laws are the same.\"","consequence":"The difference stays blurry."}],"debrief":"It's a norm, not a law; only laws carry penalties.","relearn":"Norms are unwritten with no penalty; laws are written.","persona":"any","source":"concept"},
  {"id":"ns-1324","cat":"what-is-a-norm","type":"branch","hook":"A new kid eats with a fork. Classmates whisper it's 'wrong'.","options":[{"text":"\"Eating style is a norm that varies, neither's wrong.\"","consequence":"The kid feels welcome.","best":true},{"text":"Join in, \"here we eat with hands.\"","consequence":"The kid feels shamed for a valid norm."},{"text":"Say nothing, let it go on.","consequence":"'Our way is the only way' stands."}],"debrief":"How we eat is a norm that varies; different isn't wrong.","relearn":"Norms vary by place; different doesn't mean wrong.","persona":"any","source":"observation"},
  {"id":"ns-1325","cat":"what-is-a-norm","type":"branch","hook":"Someone says \"this rule is really old, so it must be right.\"","options":[{"text":"\"Old means it lasted, not that it's fair, let's test it.\"","consequence":"You both check if it's actually fair.","best":true},{"text":"Agree, old means correct.","consequence":"An unfair old norm gets a free pass."},{"text":"\"All old things are useless, scrap them.\"","consequence":"Kind old norms get thrown out too."}],"debrief":"Age means a norm lasted, not that it's fair; test each one.","relearn":"Being old doesn't make a norm right; test it.","persona":"any","source":"critical thinking"},
  {"id":"ns-1326","cat":"what-is-a-norm","type":"branch","hook":"Your sister says \"liking spicy food is a norm in our family.\"","options":[{"text":"\"That's a taste, not a norm, we can differ.\"","consequence":"You both see a liking isn't a group rule.","best":true},{"text":"Agree, all must like spicy food.","consequence":"A taste is forced on everyone."},{"text":"\"Tastes and norms are the same.\"","consequence":"The line stays muddled."}],"debrief":"A food you like is a taste; a norm is shared by a group.","relearn":"A norm is shared by a group; a taste is just yours.","persona":"any","source":"concept"},
  {"id":"ns-1327","cat":"what-is-a-norm","type":"branch","hook":"In a debate someone claims \"a norm everyone follows can't be unfair.\"","options":[{"text":"\"Common only means popular, we can still ask if it's fair.\"","consequence":"The debate turns to fairness.","best":true},{"text":"Agree, if it's popular it's fair.","consequence":"Unfair-but-common norms get protected."},{"text":"\"Popular means fair and true.\"","consequence":"Numbers get treated as proof."}],"debrief":"People once followed unfair norms too; common isn't fair.","relearn":"A norm being common doesn't make it fair.","persona":"any","source":"critical thinking"},
  {"id":"ns-1328","cat":"what-is-a-norm","type":"branch","hook":"Diya wonders if 'girls cook, boys play' is just 'natural'.","options":[{"text":"\"It's a norm people taught, not nature, we can question it.\"","consequence":"Diya sees it isn't fixed.","best":true},{"text":"\"It's biology, girls are built to cook.\"","consequence":"A made-up role is sold as nature."},{"text":"\"Stop thinking, just obey.\"","consequence":"Her fair question is shut down."}],"debrief":"That role is a norm, not nature, so it's open to question.","relearn":"Such roles are norms people made, not nature.","persona":"Diya","source":"critical thinking"},
  {"id":"ns-1329","cat":"what-is-a-norm","type":"branch","hook":"A friend says \"a norm isn't a real rule, no one wrote it down.\"","options":[{"text":"\"It's a real unwritten rule, you feel it when you break one.\"","consequence":"Your friend sees norms are real.","best":true},{"text":"Agree, ignore every unwritten norm.","consequence":"You confuse those around you."},{"text":"\"Only written things matter.\"","consequence":"You miss norms that shape daily life."}],"debrief":"Norms are real unwritten rules; you notice them when crossed.","relearn":"A norm is a real, unwritten rule a group follows.","persona":"any","source":"concept"},
  {"id":"ns-1330","cat":"what-is-a-norm","type":"sort","hook":"Sort: a group norm everyone follows, or just one person's repeated habit?","items":[{"id":"a","text":"People greet neighbours each morning"},{"id":"b","text":"Ravi cracks his knuckles when bored"},{"id":"c","text":"Guests are seen to the gate"},{"id":"d","text":"Meena doodles in every margin"},{"id":"e","text":"Shoes come off at the doorway"},{"id":"f","text":"Kabir taps his pen while thinking"}],"bins":[{"id":"norm","label":"Group norm","valence":"tell"},{"id":"habit","label":"Personal habit","valence":"neutral"}],"key":{"a":"norm","b":"habit","c":"norm","d":"habit","e":"norm","f":"habit"},"relearn":"A norm is shared by a group; a habit is one person's repeated act.","persona":"any","source":"concept"},
  {"id":"ns-1331","cat":"what-is-a-norm","type":"match","hook":"Match each example to what kind of thing it is.","pairs":[{"left":"\"We queue at the counter\"","right":"A shared norm"},{"left":"\"You bite your nails when nervous\"","right":"A personal habit"},{"left":"\"You love the colour purple\"","right":"A private taste"},{"left":"\"Children must attend school\"","right":"A written law"},{"left":"\"Water freezes when cold enough\"","right":"A natural fact"}],"relearn":"Norm, habit, taste, law and fact are five different things.","persona":"any","source":"vocabulary"},
  {"id":"ns-1350","cat":"where-from","type":"sort","hook":"Sort: did this pass a norm down to you, or not?","items":[{"id":"a","text":"Granny showing how to greet guests"},{"id":"b","text":"A serial where the bahu does every chore"},{"id":"c","text":"Cousins copying each other"},{"id":"d","text":"A teacher's reaction when you spoke"},{"id":"e","text":"An ad: only mums do laundry"},{"id":"f","text":"A monsoon cloud overhead"}],"bins":[{"id":"teaches","label":"Teaches a norm","valence":"pos"},{"id":"nope","label":"Teaches nothing","valence":"neutral"}],"key":{"a":"teaches","b":"teaches","c":"teaches","d":"teaches","e":"teaches","f":"nope"},"relearn":"We learn norms by example and reaction: family, media, friends, school.","persona":"any","source":"origins"},
  {"id":"ns-1351","cat":"where-from","type":"sort","hook":"Sort: grew from care, or from old ranking of people?","items":[{"id":"a","text":"\"Boil water\": stop illness"},{"id":"b","text":"\"This caste sits apart\": ranking"},{"id":"c","text":"\"Help the new kid\": kindness"},{"id":"d","text":"\"Daughters eat last\": old order"},{"id":"e","text":"\"Shoes off indoors\": stay clean"},{"id":"f","text":"\"Fair brides wanted more\": bias"}],"bins":[{"id":"care","label":"Grew from care","valence":"pos"},{"id":"rank","label":"Old ranking","valence":"neg"}],"key":{"a":"care","b":"rank","c":"care","d":"rank","e":"care","f":"rank"},"relearn":"Some norms began with care; others are just old, unfair ranking.","persona":"any","source":"origins"},
  {"id":"ns-1352","cat":"where-from","type":"sort","hook":"Sort: a norm that lives mostly in one region, or one shared almost everywhere?","items":[{"id":"a","text":"Eating with hands at home"},{"id":"b","text":"Saying sorry when you bump someone"},{"id":"c","text":"A special harvest dance for one state"},{"id":"d","text":"Queuing for a bus"},{"id":"e","text":"A wedding ritual unique to one community"},{"id":"f","text":"Helping someone who falls down"}],"bins":[{"id":"local","label":"Mostly one place","valence":"neutral"},{"id":"wide","label":"Almost everywhere","valence":"pos"}],"key":{"a":"local","b":"wide","c":"local","d":"wide","e":"local","f":"wide"},"relearn":"Norms vary hugely across regions; none is truly universal.","persona":"any","source":"origins"},
  {"id":"ns-1353","cat":"where-from","type":"sort","hook":"Sort: born long ago and changed, or born long ago and still kept?","items":[{"id":"a","text":"Schools once barred girls: changed"},{"id":"b","text":"Sharing food with a guest: kept"},{"id":"c","text":"Widows once couldn't remarry: changed"},{"id":"d","text":"Touching elders' feet to greet: kept"},{"id":"e","text":"Only sons did the last rites: changing"},{"id":"f","text":"Welcoming travellers: kept"}],"bins":[{"id":"changed","label":"Has changed","valence":"pos"},{"id":"kept","label":"Still kept","valence":"neutral"}],"key":{"a":"changed","b":"kept","c":"changed","d":"kept","e":"changed","f":"kept"},"relearn":"Old norms can change or stay; age alone never settles it.","persona":"any","source":"origins / change"},
  {"id":"ns-1354","cat":"where-from","type":"sort","hook":"Sort: a 'rule' people invented, or a fact of nature nobody chose?","items":[{"id":"a","text":"Pink is 'a girl's colour'"},{"id":"b","text":"Water flows downhill"},{"id":"c","text":"Boys 'should' like cricket more"},{"id":"d","text":"The sun rises in the east"},{"id":"e","text":"Girls 'should' speak softly"},{"id":"f","text":"Ice is colder than steam"}],"bins":[{"id":"made","label":"People invented it","valence":"neg"},{"id":"nature","label":"Fact of nature","valence":"neutral"}],"key":{"a":"made","b":"nature","c":"made","d":"nature","e":"made","f":"nature"},"relearn":"Norms come from people, not nature, so they can be wrong and can change.","persona":"any","source":"origins"},
  {"id":"ns-1355","cat":"where-from","type":"sort","hook":"Sort: where Diya first met each norm in her house.","items":[{"id":"a","text":"Cycling 'stopped' once she 'grew up'"},{"id":"b","text":"A TV mum cooking while dad reads"},{"id":"c","text":"Being served food last at dinner"},{"id":"d","text":"An aunt saying \"log kya kahenge\""},{"id":"e","text":"A clock ticking on the wall"},{"id":"f","text":"Rain falling on the terrace"}],"bins":[{"id":"learned","label":"A norm she learned","valence":"uhoh"},{"id":"justthere","label":"Just there, no norm","valence":"neutral"}],"key":{"a":"learned","b":"learned","c":"learned","d":"learned","e":"justthere","f":"justthere"},"relearn":"We pick up norms from family, media and the reactions around us.","persona":"Diya","source":"origins"},
  {"id":"ns-1356","cat":"where-from","type":"sort","hook":"Sort: began for safety, or only ever about control?","items":[{"id":"a","text":"\"Don't drink pond water\": health"},{"id":"b","text":"\"Women shouldn't earn\": control"},{"id":"c","text":"\"Cover hot oil\": safety"},{"id":"d","text":"\"Girls can't study far\": control"},{"id":"e","text":"\"Tie cattle before dark\": care"},{"id":"f","text":"\"Wives must always agree\": control"}],"bins":[{"id":"safety","label":"For safety","valence":"pos"},{"id":"control","label":"About control","valence":"neg"}],"key":{"a":"safety","b":"control","c":"safety","d":"control","e":"safety","f":"control"},"relearn":"Some norms began with care; others only to control a group.","persona":"any","source":"origins"},
  {"id":"ns-1357","cat":"where-from","type":"sort","hook":"Sort: a norm passed down at home, or at school?","items":[{"id":"a","text":"How to fold hands and greet a guest"},{"id":"b","text":"Standing quietly in the morning line"},{"id":"c","text":"Who clears the plates after a meal"},{"id":"d","text":"Raising a hand before you speak"},{"id":"e","text":"Touching grandparents' feet on festivals"},{"id":"f","text":"Wearing the same uniform as everyone"}],"bins":[{"id":"home","label":"Learned at home","valence":"neutral"},{"id":"school","label":"Learned at school","valence":"neutral"}],"key":{"a":"home","b":"school","c":"home","d":"school","e":"home","f":"school"},"relearn":"We learn different norms in different places: home, school, friends, media.","persona":"any","source":"origins"},
  {"id":"ns-1358","cat":"where-from","type":"sort","hook":"Sort: already changed, or still waiting to change?","items":[{"id":"a","text":"Women presenting TV news"},{"id":"b","text":"\"Boys mustn't cry\" still common"},{"id":"c","text":"Girls captaining cricket"},{"id":"d","text":"Dowry still quietly demanded"},{"id":"e","text":"Dads pushing prams"},{"id":"f","text":"\"Sons are needed\" still whispered"}],"bins":[{"id":"already","label":"Already changing","valence":"pos"},{"id":"waiting","label":"Still waiting","valence":"uhoh"}],"key":{"a":"already","b":"waiting","c":"already","d":"waiting","e":"already","f":"waiting"},"relearn":"Some norms have shifted; others still need a fair question to change.","persona":"any","source":"change"},
  {"id":"ns-1359","cat":"where-from","type":"sort","hook":"Sort: does each idea come from people or from nature?","items":[{"id":"a","text":"\"Girls wear bangles, boys don't\""},{"id":"b","text":"Babies need milk to grow"},{"id":"c","text":"\"Eldest son must take over the shop\""},{"id":"d","text":"Plants turn toward sunlight"},{"id":"e","text":"\"Brides move to the husband's home\""},{"id":"f","text":"Rain follows the monsoon winds"}],"bins":[{"id":"people","label":"From people","valence":"neg"},{"id":"nature","label":"From nature","valence":"neutral"}],"key":{"a":"people","b":"nature","c":"people","d":"nature","e":"people","f":"nature"},"relearn":"People made these social rules; nature didn't, so they can be questioned.","persona":"any","source":"origins"},
  {"id":"ns-1360","cat":"where-from","type":"sort","hook":"Sort: Aarav's 'be a man' rules, handed down by people, or laws of nature?","items":[{"id":"a","text":"\"Real boys never cry\""},{"id":"b","text":"You feel hungry after sport"},{"id":"c","text":"\"A man must always provide\""},{"id":"d","text":"Your heart beats faster when you run"},{"id":"e","text":"\"Asking for help is weak\""},{"id":"f","text":"You get sleepy late at night"}],"bins":[{"id":"handed","label":"Handed-down norm","valence":"neg"},{"id":"body","label":"How a body works","valence":"neutral"}],"key":{"a":"handed","b":"body","c":"handed","d":"body","e":"handed","f":"body"},"relearn":"\"Be a man\" rules were made by people; they aren't facts about boys.","persona":"Aarav","source":"origins"},
  {"id":"ns-1361","cat":"where-from","type":"sort","hook":"Sort: a norm that spread through screens, or one taught face to face?","items":[{"id":"a","text":"A film hero who never shows fear"},{"id":"b","text":"Your mother showing you to share"},{"id":"c","text":"An ad where only women clean floors"},{"id":"d","text":"A coach teaching fair play"},{"id":"e","text":"A reel mocking boys who dance"},{"id":"f","text":"A neighbour greeting everyone kindly"}],"bins":[{"id":"screen","label":"From screens","valence":"uhoh"},{"id":"person","label":"Person to person","valence":"neutral"}],"key":{"a":"screen","b":"person","c":"screen","d":"person","e":"screen","f":"person"},"relearn":"Media teaches norms too, and media often normalises unfair ones.","persona":"any","source":"origins / media"},
  {"id":"ns-1362","cat":"where-from","type":"sort","hook":"Sort: born from care, or just an unexamined old habit?","items":[{"id":"a","text":"\"Let the sick rest\": care"},{"id":"b","text":"\"Left hand is impure\": habit"},{"id":"c","text":"\"Share tiffin with a friend\""},{"id":"d","text":"\"Girls cover heads, boys needn't\""},{"id":"e","text":"\"Walk an elder home at night\""},{"id":"f","text":"\"Only boys light the lamp\""}],"bins":[{"id":"care","label":"Born from care","valence":"pos"},{"id":"habit","label":"Old habit","valence":"neg"}],"key":{"a":"care","b":"habit","c":"care","d":"habit","e":"care","f":"habit"},"relearn":"Some norms began kind; some are just unexamined habits.","persona":"any","source":"origins"},
  {"id":"ns-1363","cat":"where-from","type":"sort","hook":"Sort: did this come from history, or is it a plain fact?","items":[{"id":"a","text":"\"Women shouldn't go out at night\""},{"id":"b","text":"Night is darker than day"},{"id":"c","text":"\"Cooking is women's work\""},{"id":"d","text":"Fire is hotter than ice"},{"id":"e","text":"\"Boys shouldn't wear bright colours\""},{"id":"f","text":"Heavy things sink in water"}],"bins":[{"id":"history","label":"From old custom","valence":"neg"},{"id":"fact","label":"A plain fact","valence":"neutral"}],"key":{"a":"history","b":"fact","c":"history","d":"fact","e":"history","f":"fact"},"relearn":"Norms come from old custom, not from nature. Facts are different.","persona":"any","source":"origins"},
  {"id":"ns-1364","cat":"where-from","type":"sort","hook":"Sort: Rohit's home, which jobs got stuck to a gender by old habit?","items":[{"id":"a","text":"\"Dad fixes the bike\": habit"},{"id":"b","text":"\"Mum cooks every meal\": habit"},{"id":"c","text":"\"Anyone can wash the dishes\": fair"},{"id":"d","text":"\"Only mum irons clothes\": habit"},{"id":"e","text":"\"We both help with homework\": fair"},{"id":"f","text":"\"Either parent can drop kids\": fair"}],"bins":[{"id":"stuck","label":"Stuck by habit","valence":"neg"},{"id":"shared","label":"Shared fairly","valence":"pos"}],"key":{"a":"stuck","b":"stuck","c":"shared","d":"stuck","e":"shared","f":"shared"},"relearn":"Old role-split norms stuck jobs to a gender; chores can be shared fairly.","persona":"Rohit","source":"origins"},
  {"id":"ns-1365","cat":"where-from","type":"strike-rewrite","hook":"\"If our family always did it, it must be the right way.\"","myth":{"un":"Our family always did it, so it must be right.","re":"A norm being old in your family doesn't make it fair.","why":"Families pass on both kind customs and unfair ones."},"relearn":"\"We've always done it\" tells you a norm's age, not whether it's fair.","persona":"any","source":"origins"},
  {"id":"ns-1366","cat":"where-from","type":"strike-rewrite","hook":"\"Whatever the films show is just how the world really is.\"","myth":{"un":"Films and ads just show how the world really is.","re":"Media often repeats norms and can make unfair ones look normal.","why":"Stories are chosen by people, not copied from nature."},"relearn":"We learn norms from media too, and media can normalise unfair ones.","persona":"any","source":"origins / media"},
  {"id":"ns-1367","cat":"where-from","type":"strike-rewrite","hook":"\"One person can never change a norm everyone follows.\"","myth":{"un":"One person can never change a norm everyone follows.","re":"Big norm changes in India often began with a few people questioning.","why":"What people made, people can remake, usually starting small."},"relearn":"Norms are human-made, so even a small start can change them.","persona":"any","source":"agency / change"},
  {"id":"ns-1368","cat":"where-from","type":"strike-rewrite","hook":"\"This is our culture, so none of it can ever be questioned.\"","myth":{"un":"It's our culture, so no part of it can be questioned.","re":"You can keep the kind parts of a culture and question the unfair ones.","why":"Cultures are made by people and have always grown and changed."},"relearn":"Questioning a harmful custom isn't rejecting your whole culture.","persona":"any","source":"origins"},
  {"id":"ns-1369","cat":"where-from","type":"strike-rewrite","hook":"\"Other places do it differently because they're simply wrong.\"","myth":{"un":"Other places do it differently because they are wrong.","re":"Norms vary by region and family; different isn't the same as wrong.","why":"There's no single 'normal'. Each place grew its own customs."},"relearn":"Norms differ across places; variety shows they're human-made, not fixed.","persona":"any","source":"origins"},
  {"id":"ns-1370","cat":"where-from","type":"strike-rewrite","hook":"\"This norm has no story. It just appeared from nowhere.\"","myth":{"un":"This norm just appeared on its own from nowhere.","re":"Every norm has a human origin: care, history, habit or power.","why":"Knowing where a norm came from helps you test if it's still fair."},"relearn":"Norms have human origins; tracing them helps us judge them.","persona":"any","source":"origins"},
  {"id":"ns-1371","cat":"where-from","type":"strike-rewrite","hook":"Aarav: \"Boys have always had to be tough. That'll never change.\"","myth":{"un":"Boys have always had to be tough, so it can never change.","re":"The 'always tough, never cry' idea is a made norm boys can question.","why":"It was taught to boys, not built into them, so it can change."},"relearn":"\"Be a man\" is a human-made norm. Boys can have feelings and ask for help.","persona":"Aarav","source":"origins"},
  {"id":"ns-1372","cat":"where-from","type":"strike-rewrite","hook":"Diya: \"Girls were always kept home. That's just how it is.\"","myth":{"un":"Girls were always kept home, so that's just how it is.","re":"Keeping girls home was a norm, and across India it has been changing.","why":"Girls now study, cycle and lead where that norm has been questioned."},"relearn":"\"That's just how it is\" is a norm, and this one is genuinely changing.","persona":"Diya","source":"origins / change"},
  {"id":"ns-1373","cat":"where-from","type":"strike-rewrite","hook":"\"Once a norm is set, it can only ever go one way.\"","myth":{"un":"Once a norm is set it can only ever move one way.","re":"Norms shift back and forth as people keep questioning them.","why":"They're kept alive by people's choices, not locked by nature."},"relearn":"Each generation can question and improve the norms it inherits.","persona":"any","source":"change"},
  {"id":"ns-1374","cat":"where-from","type":"strike-rewrite","hook":"\"My friends all do it, so it must be the normal, right thing.\"","myth":{"un":"All my friends do it, so it must be the right thing.","re":"Friends pass on norms too, and a common norm can still be unfair.","why":"Lots of people once followed unfair norms without noticing."},"relearn":"Friends teach us norms; common doesn't mean fair.","persona":"any","source":"origins"},
  {"id":"ns-1375","cat":"where-from","type":"strike-rewrite","hook":"\"Elders set this rule, so it can never be looked at again.\"","myth":{"un":"Elders set this rule, so it can never be looked at again.","re":"You can respect elders and still gently ask if a custom is fair.","why":"Elders themselves changed many norms they once inherited."},"relearn":"Respecting elders and questioning a norm can go together.","persona":"any","source":"origins"},
  {"id":"ns-1376","cat":"where-from","type":"strike-rewrite","hook":"\"If a custom comes from long ago, it must be wise and fair.\"","myth":{"un":"If a custom is from long ago, it must be wise and fair.","re":"Old customs can be kind or harmful. Age alone proves neither.","why":"People long ago, like us, made both fair and unfair rules."},"relearn":"Being old doesn't make a norm fair; test each one on its own.","persona":"any","source":"origins"},
  {"id":"ns-1377","cat":"where-from","type":"strike-rewrite","hook":"\"School taught it, so it must be a fact, not just a norm.\"","myth":{"un":"School taught it, so it must be a fact and not a norm.","re":"Schools pass on norms too, and some old ones were unfair.","why":"Once, schools split subjects by gender. That was a norm, now changed."},"relearn":"Even school can teach norms; norms and facts aren't the same.","persona":"any","source":"origins"},
  {"id":"ns-1378","cat":"where-from","type":"strike-rewrite","hook":"\"A really common norm must be a true law of life.\"","myth":{"un":"A very common norm must be a true law of life.","re":"How common a norm is can't tell you whether it's a fact or fair.","why":"Common customs and natural facts are simply different things."},"relearn":"Common isn't natural; norms are human-made and can be questioned.","persona":"any","source":"origins"},
  {"id":"ns-1379","cat":"where-from","type":"reflect","hook":"Lensy: think of one rule in your home nobody wrote down. Where do you reckon it came from?","prompt":"Where might it be from?","options":["Family","An old habit","A film or ad"],"affirm":"Most norms come from people, history and habit, which is exactly why they can change.","relearn":"Norms come from people and habit, not nature.","persona":"any","source":"origins"},
  {"id":"ns-1380","cat":"where-from","type":"reflect","hook":"Lensy: if a custom started for a kind reason but stopped helping, should we still keep it?","prompt":"What feels right?","options":["Update it","Keep the kind bit","Ask if it's fair"],"affirm":"You can honour the caring start of a custom and still let the unfair part go.","relearn":"Some norms began with care; we can keep the kind part and change the rest.","persona":"any","source":"origins"},
  {"id":"ns-1381","cat":"where-from","type":"reflect","hook":"Lensy: your grandparents grew up with very different norms than yours. Cool to think about?","prompt":"What do you make of it?","options":["Norms shift","Times change","People learn"],"affirm":"Norms vary across eras. Each generation re-stitches the ones it inherits.","relearn":"Norms vary across time; every generation can improve them.","persona":"any","source":"change"},
  {"id":"ns-1382","cat":"where-from","type":"reflect","hook":"Asha: in my village, a norm started shifting when just three families tried something fairer. Believable?","prompt":"What do you think?","options":["Yes","Change is collective","It starts small"],"affirm":"Big norm changes often begin with a few people questioning together.","relearn":"Change starts small and spreads when people keep living it.","persona":"Asha","source":"change"},
  {"id":"ns-1383","cat":"where-from","type":"reflect","hook":"Lensy: an ad shows only mums doing the laundry. Where do you think that picture came from?","prompt":"What's your hunch?","options":["An old norm","Lazy copying","Habit on repeat"],"affirm":"Media often just repeats an old norm. Spotting that is the first step to changing it.","relearn":"Media often normalises unfair norms; noticing it is the start.","persona":"any","source":"media"},
  {"id":"ns-1384","cat":"where-from","type":"reflect","hook":"Diya: I learned 'girls get served last' just by watching dinners at home. Make sense how that happens?","prompt":"What do you think?","options":["Yes","We copy what we see","Quietly taught"],"affirm":"We soak up norms by example and reaction, which means we can notice and rewrite them.","relearn":"We learn norms by watching family, so we can also unlearn them.","persona":"Diya","source":"origins"},
  {"id":"ns-1385","cat":"where-from","type":"reflect","hook":"Aarav: nobody sat me down and said 'be tough'. I just picked it up. Sound familiar?","prompt":"What do you reckon?","options":["Yes","Caught, not taught","From everywhere"],"affirm":"Norms are often caught, not taught, and what you caught, you can question.","relearn":"\"Be a man\" is a learned norm, not a fact about boys.","persona":"Aarav","source":"origins"},
  {"id":"ns-1386","cat":"where-from","type":"reflect","hook":"Lensy: if you could ask the very first person who made a norm 'why?', would that help?","prompt":"What do you think?","options":["Yes","Find the reason","Then test it"],"affirm":"Asking where a norm came from helps you judge if its reason still holds.","relearn":"Tracing a norm's origin helps us test if it's still fair.","persona":"any","source":"origins"},
  {"id":"ns-1387","cat":"where-from","type":"reflect","hook":"Lensy: some norms travelled here from films, some from grandparents, some from neighbours. Neat to untangle?","prompt":"What do you think?","options":["Yes","Many sources","Worth tracing"],"affirm":"Norms reach us from family, media, friends and school: many threads, all human.","relearn":"We learn norms from many human sources, never from nature.","persona":"any","source":"origins"},
  {"id":"ns-1388","cat":"where-from","type":"reflect","hook":"Rohit: my dad never cooked, his dad never cooked. I'm the first. Strange how a habit just rolls on?","prompt":"What do you think?","options":["Yes","Habits pass down","Until someone stops"],"affirm":"Role-split norms roll down the generations until someone gently changes the pattern.","relearn":"Norms pass down by habit; one person can start a fairer one.","persona":"Rohit","source":"origins / change"},
  {"id":"ns-1389","cat":"where-from","type":"reflect","hook":"Lensy: if a norm could be different somewhere else in India, does that make it easier to question here?","prompt":"What do you think?","options":["Yes","It's not the only way","Opens my mind"],"affirm":"Seeing a norm vary elsewhere shows it isn't fixed, which makes it easier to question.","relearn":"Norms vary by place; none is the only possible way.","persona":"any","source":"origins"},
  {"id":"ns-1390","cat":"where-from","type":"reflect","hook":"Lensy: every helpful norm you keep and every harmful one you question shapes the norms younger kids inherit. Feel that?","prompt":"What do you think?","options":["Yes","I'm a link","Pass on the fair ones"],"affirm":"You inherit norms and you pass them on: keep the helpful, question the harmful.","relearn":"Each generation can improve the norms it hands to the next.","persona":"any","source":"change"},
  {"id":"ns-1391","cat":"where-from","type":"reflect","hook":"Lensy: a custom can be hundreds of years old and still get gently updated. Does that surprise you?","prompt":"What do you think?","options":["A little","Not really","Good to know"],"affirm":"Even very old customs get re-stitched. Age never locks a norm in place.","relearn":"Even very old norms can and do change.","persona":"any","source":"change"},
  {"id":"ns-1392","cat":"where-from","type":"reflect","hook":"Lensy: which feels stronger to you: a norm because it's old, or a norm because it's fair?","prompt":"What do you think?","options":["Because it's fair","Fairness wins","Old isn't enough"],"affirm":"Fairness, not age, is what makes a norm worth keeping.","relearn":"Age doesn't make a norm fair; test each one.","persona":"any","source":"good-norm hint"},
  {"id":"ns-1393","cat":"where-from","type":"role-play","hook":"Where did the kitchen 'rule' come from? Say your line.","setup":"Your cousin shrugs: \"Boys don't help in the kitchen. That's just the rule.\" You answer:","yourLine":[{"text":"\"Who made that rule, though? People did, so we can do it differently.\"","best":true},{"text":"\"I guess... that's just how it's always been.\""}],"relearn":"People made role-split norms, so people can change them.","persona":"any","source":"origins"},
  {"id":"ns-1394","cat":"where-from","type":"role-play","hook":"\"It's ancient, so beyond question.\" Say your line.","setup":"At a wedding, an uncle says, \"This dowry custom is ancient, beyond question.\" You gently say:","yourLine":[{"text":"\"Ancient customs were made by people, uncle, and dowry is illegal now.\"","best":true},{"text":"\"Okay, if it's that old it must be fine.\""}],"relearn":"Old customs were made by people; dowry is harmful and illegal in India.","persona":"any","source":"origins"},
  {"id":"ns-1395","cat":"where-from","type":"role-play","hook":"\"Pink is a girl colour.\" Say your line.","setup":"A friend insists, \"Pink is a girl colour. Everyone knows that.\" You reply:","yourLine":[{"text":"\"That's just a habit people invented. Colours don't belong to anyone.\"","best":true},{"text":"\"Yeah, you're right, it's a girl colour.\""}],"relearn":"Colour 'rules' are invented norms, not facts of nature.","persona":"any","source":"origins"},
  {"id":"ns-1396","cat":"where-from","type":"role-play","hook":"\"Girls here never cycled.\" Say your line.","setup":"Diya's aunt says, \"Girls in our family have never cycled to school. Don't break tradition.\" Diya says:","yourLine":[{"text":"\"In lots of families that's changed, auntie. Can we try? I'll be careful.\"","best":true},{"text":"\"Fine, I'll just walk forever then.\""}],"relearn":"A family norm can vary and change; you can ask kindly.","persona":"Diya","source":"origins / change"},
  {"id":"ns-1397","cat":"where-from","type":"role-play","hook":"\"Boys have always been tough.\" Say your line.","setup":"Aarav's classmate teases, \"Crying is for girls. Boys have always been tough.\" Aarav answers:","yourLine":[{"text":"\"That's a made-up rule. Anyone can feel things. It doesn't make you weak.\"","best":true},{"text":"\"Whatever, I wasn't crying anyway.\""}],"relearn":"\"Boys must be tough\" is a taught norm, not a fact about boys.","persona":"Aarav","source":"origins"},
  {"id":"ns-1398","cat":"where-from","type":"role-play","hook":"\"It's from our ancestors. Don't question it.\" Say your line.","setup":"A neighbour says, \"This norm came from our ancestors, so no child should question it.\" You say:","yourLine":[{"text":"\"I respect them, and I think they'd be glad we keep checking it's still fair.\"","best":true},{"text":"\"Sorry, I won't ask about it again.\""}],"relearn":"Respecting elders and gently questioning a norm can go together.","persona":"any","source":"origins"},
  {"id":"ns-1399","cat":"where-from","type":"role-play","hook":"\"Why are only women cleaning on TV?\" Say your line.","setup":"On TV, only women are shown cleaning. Your little sister asks why. You explain:","yourLine":[{"text":"\"The ad's just copying an old norm. At home anyone can clean.\"","best":true},{"text":"\"That's just how it is, I suppose.\""}],"relearn":"Media often repeats an old norm; it isn't a fact.","persona":"any","source":"media"},
  {"id":"ns-1400","cat":"where-from","type":"role-play","hook":"\"Men here never cooked. Why start?\" Say your line.","setup":"Rohit's father says, \"Men in this house never cooked. Why start now?\" Rohit replies:","yourLine":[{"text":"\"Because that was just an old habit, Appa, and sharing cooking helps everyone.\"","best":true},{"text":"\"You're right, I'll leave it all to her.\""}],"relearn":"\"Men don't cook\" is an old habit, not a rule of nature.","persona":"Rohit","source":"origins"},
  {"id":"ns-1401","cat":"where-from","type":"match","hook":"Match each norm to where it most likely came from.","pairs":[{"left":"\"Wash hands before eating\"","right":"Care for health"},{"left":"\"Only sons inherit land\"","right":"Old power habit"},{"left":"\"Mums do all the cleaning\" on TV","right":"Repeated by media"},{"left":"\"Touch elders' feet to greet\"","right":"Taught by family"},{"left":"\"Girls shouldn't study far away\"","right":"Wish to control"}],"relearn":"Norms come from care, history, media, family or power, never nature.","persona":"any","source":"origins"},
  {"id":"ns-1402","cat":"where-from","type":"match","hook":"Match each old Indian norm to what it has become today.","pairs":[{"left":"Girls barred from school","right":"Girls fill classrooms now"},{"left":"Widows couldn't remarry","right":"Many remarry today"},{"left":"Marrying off young kids","right":"Now banned and rare"},{"left":"Untouchability practised","right":"Illegal and shrinking"},{"left":"Only boys learned trades","right":"All children learn skills"}],"relearn":"Big harmful norms in India have genuinely changed over time.","persona":"any","source":"India history"},
  {"id":"ns-1403","cat":"where-from","type":"match","hook":"Match each place we learn norms to an example of what it teaches.","pairs":[{"left":"Family","right":"How to greet a guest"},{"left":"Films and ads","right":"Who 'should' do chores"},{"left":"Friends","right":"What's 'cool' to wear"},{"left":"School","right":"Standing in a line"},{"left":"Festivals","right":"Songs and rituals"}],"relearn":"We learn norms from family, media, friends and school.","persona":"any","source":"origins"},
  {"id":"ns-1404","cat":"where-from","type":"match","hook":"Match each saying to the kind of origin it reveals.","pairs":[{"left":"\"Cover the food\"","right":"Began with care"},{"left":"\"Girls can't lead\"","right":"Old unfair power"},{"left":"\"Different states, different rules\"","right":"Varies by place"},{"left":"\"We changed that long ago\"","right":"Norms can change"},{"left":"\"My friends all do it\"","right":"Spread by peers"}],"relearn":"A norm's words often hint at where it came from.","persona":"any","source":"origins"},
  {"id":"ns-1405","cat":"where-from","type":"match","hook":"Match each region or era detail to what it shows about norms.","pairs":[{"left":"One state's harvest dance","right":"Norms vary by region"},{"left":"A custom gone in 50 years","right":"Norms change over time"},{"left":"A rule only in one family","right":"Norms vary by family"},{"left":"A greeting used nationwide","right":"Some norms spread wide"},{"left":"A festival unique to a town","right":"Local, not universal"}],"relearn":"Norms vary by region, family and era; none is universal.","persona":"any","source":"origins"},
  {"id":"ns-1406","cat":"where-from","type":"match","hook":"Match each made-by-people norm to the natural fact people sometimes confuse it with.","pairs":[{"left":"\"Boys are naturally tougher\"","right":"All bodies feel pain"},{"left":"\"Girls are naturally quiet\"","right":"Any child can be loud"},{"left":"\"Pink is for girls\"","right":"Light has many colours"},{"left":"\"Men don't cry\"","right":"All eyes make tears"},{"left":"\"Cooking suits women\"","right":"Anyone can learn to cook"}],"relearn":"Gender 'rules' are made-up norms, not facts of nature.","persona":"any","source":"origins"},
  {"id":"ns-1407","cat":"where-from","type":"match","hook":"Match each norm-source to a question that helps you check it.","pairs":[{"left":"Heard it from family","right":"\"Is it fair to everyone?\""},{"left":"Saw it on screen","right":"\"Who's missing from this picture?\""},{"left":"Friends all do it","right":"\"Common, but is it kind?\""},{"left":"It's very old","right":"\"Old, yet still fair?\""},{"left":"It started for safety","right":"\"Does it still keep us safe?\""}],"relearn":"Knowing a norm's source helps you test if it's still fair.","persona":"any","source":"good-norm hint"},
  {"id":"ns-1408","cat":"where-from","type":"match","hook":"Match each home norm Rohit noticed to where it came from.","pairs":[{"left":"\"Dad always fixes things\"","right":"Old role split"},{"left":"\"We boil water to drink\"","right":"Care for health"},{"left":"\"Mum serves everyone first\"","right":"Habit, rarely questioned"},{"left":"\"We thank guests for coming\"","right":"Family courtesy"},{"left":"\"Only mum irons\"","right":"Stuck by habit"}],"relearn":"Home norms come from care, courtesy or just old habit.","persona":"Rohit","source":"origins"},
  {"id":"ns-1409","cat":"where-from","type":"branch","hook":"A relative says a norm \"can't change because it's tradition.\" Best reply?","options":[{"text":"Note kindly that many Indian traditions have already changed.","consequence":"They pause and think.","best":true},{"text":"Say nothing; agree it can't change.","consequence":"The unfair norm rolls on."},{"text":"Snap that all traditions are wrong.","consequence":"They feel attacked, stop listening."}],"debrief":"Traditions are made by people and can change.","relearn":"Calling a norm 'tradition' doesn't lock it.","persona":"any","source":"change"},
  {"id":"ns-1410","cat":"where-from","type":"branch","hook":"A home norm came from old habit, not a real reason. What do you do?","options":[{"text":"Gently ask where it came from and if it's still fair.","consequence":"A calm conversation starts.","best":true},{"text":"Keep following it, never wondering why.","consequence":"The habit stays unexamined."},{"text":"Refuse loudly and storm off.","consequence":"Everyone argues; nothing changes."}],"debrief":"Tracing a norm's origin tells a caring custom from a stale habit.","relearn":"Asking where a norm came from helps you judge it.","persona":"any","source":"origins"},
  {"id":"ns-1411","cat":"where-from","type":"branch","hook":"A TV show makes an unfair norm look normal. Best move?","options":[{"text":"Notice it aloud and say things can be fairer at home.","consequence":"Your family spots it too.","best":true},{"text":"Copy the show: \"that's just how it is.\"","consequence":"The unfair norm passes on again."},{"text":"Trust the screen and never question it.","consequence":"You miss that media repeats old norms."}],"debrief":"Media often repeats norms; naming it starts the change.","relearn":"Media often normalises unfair norms; spot it.","persona":"any","source":"media"},
  {"id":"ns-1412","cat":"where-from","type":"branch","hook":"Diya's cycling is banned \"because she's a big girl now.\" Best response?","options":[{"text":"Ask calmly where the rule's from and if other girls cycle.","consequence":"Family sees it's a changeable norm.","best":true},{"text":"Decide girls aren't meant to cycle.","consequence":"A made-up limit feels natural."},{"text":"Sneak the cycle out secretly.","consequence":"Trust breaks; norm unquestioned."}],"debrief":"\"You're a girl now\" is a made norm. Question it kindly.","relearn":"Gendered limits are made norms, not facts.","persona":"Diya","source":"origins"},
  {"id":"ns-1413","cat":"where-from","type":"branch","hook":"Aarav hears \"boys always hide feelings.\" What helps him most?","options":[{"text":"Recall it's a taught norm and talk to someone he trusts.","consequence":"He feels lighter, less boxed in.","best":true},{"text":"Bottle it up: \"that's how boys are.\"","consequence":"The harmful norm keeps weighing on him."},{"text":"Call feelings weak and mock others.","consequence":"The 'be tough' norm spreads."}],"debrief":"\"Boys must be tough\" was handed to boys, not born in them.","relearn":"\"Be a man\" is a taught norm; it can change.","persona":"Aarav","source":"origins"},
  {"id":"ns-1414","cat":"where-from","type":"branch","hook":"A friend says a norm's fine \"because everyone does it.\" Best reply?","options":[{"text":"Say common doesn't mean fair. Many unfair norms were common.","consequence":"Your friend reconsiders it.","best":true},{"text":"Agree, since everyone doing it makes it right.","consequence":"\"Common = right\" goes unchallenged."},{"text":"Mock your friend for following the crowd.","consequence":"They get defensive, tune you out."}],"debrief":"How common a norm is can't tell you if it's fair.","relearn":"A norm being common doesn't make it fair.","persona":"any","source":"origins"},
  {"id":"ns-1415","cat":"where-from","type":"branch","hook":"An old school rule now seems unfair. Best step?","options":[{"text":"Politely ask a teacher why it exists and if it can update.","consequence":"The school looks afresh.","best":true},{"text":"Assume an old rule must be right.","consequence":"An outdated norm keeps limiting people."},{"text":"Break the rule secretly to prove a point.","consequence":"You get in trouble; the rule stays."}],"debrief":"Old rules were made by people and can be re-examined kindly.","relearn":"Even old rules were made by people and can change.","persona":"any","source":"origins"},
  {"id":"ns-1416","cat":"where-from","type":"branch","hook":"Rohit's father asks why he's changing the chore split \"after all these years.\" Best reply?","options":[{"text":"Explain it was just old habit, and sharing is fairer.","consequence":"His father warms to trying.","best":true},{"text":"Say nothing; keep the old split.","consequence":"The unfair habit continues."},{"text":"Blame his father for the old way.","consequence":"A row; nothing changes."}],"debrief":"Naming a norm as old habit makes it feel changeable.","relearn":"Old role-split norms are habits, not fixed facts.","persona":"Rohit","source":"origins"},
  {"id":"ns-1417","cat":"where-from","type":"sort","hook":"Sort: this 'rule' is a written-down law, or just an unwritten norm?","items":[{"id":"a","text":"Wear a helmet on a two-wheeler"},{"id":"b","text":"\"Girls serve the men first\""},{"id":"c","text":"Children must go to school"},{"id":"d","text":"\"Boys shouldn't wear pink\""},{"id":"e","text":"Don't litter in public: fineable"},{"id":"f","text":"\"Touch the feet of every elder\""}],"bins":[{"id":"law","label":"Written law","valence":"neutral"},{"id":"norm","label":"Unwritten norm","valence":"neutral"}],"key":{"a":"law","b":"norm","c":"law","d":"norm","e":"law","f":"norm"},"relearn":"Some rules are written laws; many are just unwritten norms. They differ.","persona":"any","source":"origins"},
  {"id":"ns-1418","cat":"where-from","type":"sort","hook":"Sort: a norm spread by copying friends, or one taught by an elder?","items":[{"id":"a","text":"A slang word the whole class uses"},{"id":"b","text":"Folding hands to say namaste"},{"id":"c","text":"A game everyone plays at recess"},{"id":"d","text":"Saving the first sweet for guests"},{"id":"e","text":"A hairstyle the gang copies"},{"id":"f","text":"Lighting the lamp at dusk"}],"bins":[{"id":"peers","label":"From friends","valence":"neutral"},{"id":"elders","label":"From elders","valence":"neutral"}],"key":{"a":"peers","b":"elders","c":"peers","d":"elders","e":"peers","f":"elders"},"relearn":"We pick up norms from friends and from elders. Both pass them on.","persona":"any","source":"origins"},
  {"id":"ns-1419","cat":"where-from","type":"sort","hook":"Sort: an inherited norm, or a fairer one you can start?","items":[{"id":"a","text":"\"Eldest son decides\": inherited"},{"id":"b","text":"\"We share chores\": you start"},{"id":"c","text":"\"Girls marry, why study\": inherited"},{"id":"d","text":"\"Every kid gets a say\": you start"},{"id":"e","text":"\"Boys hide tears\": inherited"},{"id":"f","text":"\"Asking for help is fine\": you start"}],"bins":[{"id":"inherited","label":"Inherited","valence":"uhoh"},{"id":"newfair","label":"You start","valence":"pos"}],"key":{"a":"inherited","b":"newfair","c":"inherited","d":"newfair","e":"inherited","f":"newfair"},"relearn":"You inherit some norms and can start fairer ones yourself.","persona":"any","source":"change"},
];

